//LFSR to generate pseudo-random numbers with load
module lfsr64_load (clk, rst, load, preload, seed, lfsr_out);
input clk, rst, load, preload;
input [63:0] seed;
output reg [63:0] lfsr_out;
  
//Variables
wire feedback;

//Behavioral description
always @(posedge clk) begin
  if (rst == 1'b1) begin
    lfsr_out <= {64{1'b1}};
  end
  else begin
    if (load == 1'b1 & preload == 1'b0) begin
      if (seed > 64'd0) begin
        lfsr_out <= seed;
      end
      else begin
        lfsr_out <= {64{1'b1}};
      end
    end
    else begin
      lfsr_out <= {lfsr_out[62:0], feedback};
    end
  end
end

assign feedback = lfsr_out[63] ^ lfsr_out[62] ^ lfsr_out[60] ^ lfsr_out[59];

endmodule

//LFSR to generate pseudo-random numbers
module lfsr64 (clk, rst, start, seed, lfsr_out);
  input clk, rst, start;
  input [63:0] seed;
  output reg [63:0] lfsr_out;
  
  //Variables
  wire feedback;
  reg enable;

  //Behavioral description
  always @(posedge clk) begin
    if (rst == 1'b1) begin
      lfsr_out <= 64'd0;
      enable <= 1'b0;
    end
    else begin
      if (start == 1'b0) begin
        lfsr_out <= 64'd0;
        enable <= 1'b0;
      end
      else begin
        if (enable == 1'b0) begin
          enable <= 1'b1;
          if (seed > 64'd0) begin
            lfsr_out <= seed;
          end
          else begin
            lfsr_out <= {64{1'b1}};
          end
        end
        else begin
          lfsr_out <= {lfsr_out[62:0], feedback};
        end
      end
    end
  end

  assign feedback = lfsr_out[63] ^ lfsr_out[62] ^ lfsr_out[60] ^ lfsr_out[59];
endmodule

//XORSHIFT to generate pseudo-random numbers
module xorshift64 (clk, rst, start, seed, xs_out);

input clk, rst, start;
input [63:0] seed;
output [63:0] xs_out;

reg [63:0] the_seed;
wire [63:0] int0, int1, int2;

always @ (posedge clk) begin
  if (rst == 1'b1 || start == 1'b0) begin
    if (seed == 64'd0) begin
      the_seed <= 64'd1;
    end
    else begin
      the_seed <= seed;
    end
  end
  else begin
    the_seed <= int2;
  end
end

assign int0 = the_seed ^ {the_seed[50:0], 13'd0};
assign int1 = int0 ^ {7'd0, int0[63:7]};
assign int2 = int1 ^ {int1[46:0], 17'd0};

assign xs_out = int2;

endmodule

//SUBSTITUTE BYTE using 4 S-Boxes
module substitute_byte_foursbox #(parameter BLOCK_SIZE = 512) (sb_in, sb_out);

input [BLOCK_SIZE-1:0] sb_in;
output [BLOCK_SIZE-1:0] sb_out;

localparam byte_cnt = (BLOCK_SIZE == 512) ? 5'd16 : (BLOCK_SIZE == 256) ? 4'd8 : 3'd4;

genvar i;
generate
  for (i=0; i<byte_cnt; i=i+1) begin
    `ifdef OPT
      sbox_3_alt6 sbox3_ins (.sbox_in(sb_in[(byte_cnt-i-1)*32+7  : (byte_cnt-i-1)*32]),    .sbox_out(sb_out[(byte_cnt-i-1)*32+7  : (byte_cnt-i-1)*32]));
      sbox_2_alt6 sbox2_ins (.sbox_in(sb_in[(byte_cnt-i-1)*32+15 : (byte_cnt-i-1)*32+8]),  .sbox_out(sb_out[(byte_cnt-i-1)*32+15 : (byte_cnt-i-1)*32+8]));
      sbox_1_alt6 sbox1_ins (.sbox_in(sb_in[(byte_cnt-i-1)*32+23 : (byte_cnt-i-1)*32+16]), .sbox_out(sb_out[(byte_cnt-i-1)*32+23 : (byte_cnt-i-1)*32+16]));
      sbox_0_alt6 sbox0_ins (.sbox_in(sb_in[(byte_cnt-i-1)*32+31 : (byte_cnt-i-1)*32+24]), .sbox_out(sb_out[(byte_cnt-i-1)*32+31 : (byte_cnt-i-1)*32+24]));
    `elsif NOOPT
      sbox_3 sbox3_ins (.sbox_in(sb_in[(byte_cnt-i-1)*32+7  : (byte_cnt-i-1)*32]),    .sbox_out(sb_out[(byte_cnt-i-1)*32+7  : (byte_cnt-i-1)*32]));
      sbox_2 sbox2_ins (.sbox_in(sb_in[(byte_cnt-i-1)*32+15 : (byte_cnt-i-1)*32+8]),  .sbox_out(sb_out[(byte_cnt-i-1)*32+15 : (byte_cnt-i-1)*32+8]));
      sbox_1 sbox1_ins (.sbox_in(sb_in[(byte_cnt-i-1)*32+23 : (byte_cnt-i-1)*32+16]), .sbox_out(sb_out[(byte_cnt-i-1)*32+23 : (byte_cnt-i-1)*32+16]));
      sbox_0 sbox0_ins (.sbox_in(sb_in[(byte_cnt-i-1)*32+31 : (byte_cnt-i-1)*32+24]), .sbox_out(sb_out[(byte_cnt-i-1)*32+31 : (byte_cnt-i-1)*32+24]));
    `endif
  end
endgenerate

endmodule

