        reg_sbpsmc_out[(BLOCK_SIZE-((col_counter+0) % 4)*64)-16 +: 8] <= sb_out[55:48];
        reg_sbpsmc_out[(BLOCK_SIZE-((col_counter+3) % 4)*64)-24 +: 8] <= sb_out[47:40];
        reg_sbpsmc_out[(BLOCK_SIZE-((col_counter+3) % 4)*64)-32 +: 8] <= sb_out[39:32];
        reg_sbpsmc_out[(BLOCK_SIZE-((col_counter+2) % 4)*64)-40 +: 8] <= sb_out[31:24];
        reg_sbpsmc_out[(BLOCK_SIZE-((col_counter+2) % 4)*64)-48 +: 8] <= sb_out[23:16];
        reg_sbpsmc_out[(BLOCK_SIZE-((col_counter+1) % 4)*64)-56 +: 8] <= sb_out[15:8];
        reg_sbpsmc_out[(BLOCK_SIZE-((col_counter+1) % 4)*64)-64 +: 8] <= sb_out[7:0];
      end
    end
    else begin
      if (col_counter < col_cnt) begin
        reg_sbpsmc_out[(BLOCK_SIZE-((col_counter+0) % 2)*64)-8  +: 8] <= sb_out[63:56];
        reg_sbpsmc_out[(BLOCK_SIZE-((col_counter+0) % 2)*64)-16 +: 8] <= sb_out[55:48];
        reg_sbpsmc_out[(BLOCK_SIZE-((col_counter+0) % 2)*64)-24 +: 8] <= sb_out[47:40];
        reg_sbpsmc_out[(BLOCK_SIZE-((col_counter+0) % 2)*64)-32 +: 8] <= sb_out[39:32];
        reg_sbpsmc_out[(BLOCK_SIZE-((col_counter+1) % 2)*64)-40 +: 8] <= sb_out[31:24];
        reg_sbpsmc_out[(BLOCK_SIZE-((col_counter+1) % 2)*64)-48 +: 8] <= sb_out[23:16];
        reg_sbpsmc_out[(BLOCK_SIZE-((col_counter+1) % 2)*64)-56 +: 8] <= sb_out[15:8];
        reg_sbpsmc_out[(BLOCK_SIZE-((col_counter+1) % 2)*64)-64 +: 8] <= sb_out[7:0];
      end
    end
    if (col_counter == col_m1) begin
      sbpsmc_rdy <= 1'b1;
    end
    else begin
      sbpsmc_rdy <= 1'b0;
    end
  end
end

assign mc_in = sbpsmc_in[(col_m1-col_counter)*64 +:64];

//Masked Inputs
assign s1_mc_in = lfsr_in;
assign s2_mc_in = mc_in ^ lfsr_in;

//Inverse Mix Column and Byte Substitution - First-Order Masking
inv_mix_column_64b_fom mc64b_ins (.s1_mc_in(s1_mc_in), .s2_mc_in(s2_mc_in), .s1_mc_out(s1_mc_out), .s2_mc_out(s2_mc_out));
inv_substitute_byte_64b_fom sb64b_ins (.s1_sb_in(s1_mc_out), .s2_sb_in(s2_mc_out), .s1_sb_out(s1_sb_out), .s2_sb_out(s2_sb_out));

//Output of the masked design
assign sb_out = s1_sb_out ^ s2_sb_out;

assign sbpsmc_out = reg_sbpsmc_out;

endmodule

//INTERMEDIATE KEY GENERATION
module gen_int_key #(parameter BLOCK_SIZE = 512, parameter KEY_LENGTH = 512) (key_in, int_key_out);

input [KEY_LENGTH-1:0] key_in;
output [BLOCK_SIZE-1:0] int_key_out;

localparam bs_m8 = BLOCK_SIZE - 8;

//Variables
wire [BLOCK_SIZE-1:0] int_key_in;
reg [BLOCK_SIZE-1:0] key_alfa, key_omega;
wire [7:0] the_const = (BLOCK_SIZE+KEY_LENGTH)/64 + 1;
wire [BLOCK_SIZE-1:0] m2p64a0_out, m2p64a1_out, sb0_out, sb1_out, sb2_out, ps0_out, ps1_out, ps2_out, mx0_out, mx1_out, mx2_out, m2a0_out;

//Input to the intermediate key transformation
assign int_key_in = {the_const, {bs_m8{1'b0}}};

//Alfa and Omega Keys
always @ (*) begin
  if (BLOCK_SIZE == KEY_LENGTH) begin
    key_alfa = key_in;
    key_omega = key_in;
  end
  else begin
    key_alfa = key_in[KEY_LENGTH-1:KEY_LENGTH/2];
    key_omega = key_in[KEY_LENGTH/2-1:0];
  end
end

//Transformations
mod2p64_add #(.BLOCK_SIZE(BLOCK_SIZE)) m2p64add_ins0 (.m2p64add_in_one(int_key_in), .m2p64add_in_two(key_alfa), .m2p64add_out(m2p64a0_out));
substitute_byte_foursbox #(.BLOCK_SIZE(BLOCK_SIZE)) sb_ins0 (.sb_in(m2p64a0_out), .sb_out(sb0_out));
permute_state #(.BLOCK_SIZE(BLOCK_SIZE)) ps_ins0 (.ps_in(sb0_out), .ps_out(ps0_out));
mix_column #(.BLOCK_SIZE(BLOCK_SIZE)) mx_ins0 (.mc_in(ps0_out), .mc_out(mx0_out));
mod2_add #(.BLOCK_SIZE(BLOCK_SIZE)) m2a_ins0 (.m2add_in_one(key_omega), .m2add_in_two(mx0_out), .m2add_out(m2a0_out));
substitute_byte_foursbox #(.BLOCK_SIZE(BLOCK_SIZE)) sb_ins1 (.sb_in(m2a0_out), .sb_out(sb1_out));
permute_state #(.BLOCK_SIZE(BLOCK_SIZE)) ps_ins1 (.ps_in(sb1_out), .ps_out(ps1_out));
mix_column #(.BLOCK_SIZE(BLOCK_SIZE)) mx_ins1 (.mc_in(ps1_out), .mc_out(mx1_out));
mod2p64_add #(.BLOCK_SIZE(BLOCK_SIZE)) m2p64add_ins1 (.m2p64add_in_one(key_alfa), .m2p64add_in_two(mx1_out), .m2p64add_out(m2p64a1_out));
substitute_byte_foursbox #(.BLOCK_SIZE(BLOCK_SIZE)) sb_ins2 (.sb_in(m2p64a1_out), .sb_out(sb2_out));
permute_state #(.BLOCK_SIZE(BLOCK_SIZE)) ps_ins2 (.ps_in(sb2_out), .ps_out(ps2_out));
mix_column #(.BLOCK_SIZE(BLOCK_SIZE)) mx_ins2 (.mc_in(ps2_out), .mc_out(mx2_out));

assign int_key_out = mx2_out;

endmodule

//EVEN ROUND KEY GENERATION
module gen_even_rnd_key # (parameter BLOCK_SIZE = 512, parameter KEY_LENGTH = 512) (key_in, int_key_in, rnd_num_in, even_key_out);

input [KEY_LENGTH-1:0] key_in;
input [BLOCK_SIZE-1:0] int_key_in;
input [4:0] rnd_num_in;
output [BLOCK_SIZE-1:0] even_key_out;

localparam bs_d16 = BLOCK_SIZE/16;

//Variables
reg [BLOCK_SIZE-1:0] shft_tmv, trans_key_in;
wire [BLOCK_SIZE-1:0] the_tmv;
reg [KEY_LENGTH-1:0] trans_in;
wire [BLOCK_SIZE-1:0] m2p64a0_out, m2p64a1_out, m2p64a2_out, sb0_out, sb1_out, ps0_out, ps1_out, mx0_out, mx1_out, m2a0_out;

//Generation of the TMV signal and its shifted version and addition with intermediate key under modulo 2^64
assign the_tmv= {bs_d16{16'h0100}};
always @ (*) begin
  case (rnd_num_in)
    5'd0    : shft_tmv = the_tmv;
    5'd2    : shft_tmv = {the_tmv[BLOCK_SIZE-2:0],  1'd0};
    5'd4    : shft_tmv = {the_tmv[BLOCK_SIZE-3:0],  2'd0};
    5'd6    : shft_tmv = {the_tmv[BLOCK_SIZE-4:0],  3'd0};
    5'd8    : shft_tmv = {the_tmv[BLOCK_SIZE-5:0],  4'd0};
    5'd10   : shft_tmv = {the_tmv[BLOCK_SIZE-6:0],  5'd0};
    5'd12   : shft_tmv = {the_tmv[BLOCK_SIZE-7:0],  6'd0};
    5'd14   : shft_tmv = {the_tmv[BLOCK_SIZE-8:0],  7'd0};
    5'd16   : shft_tmv = {the_tmv[BLOCK_SIZE-9:0],  7'd0, 1'b1};
    5'd18   : shft_tmv = {the_tmv[BLOCK_SIZE-10:0], 7'd0, 1'b1, 1'b0}; //Last two lines are due to the conflict between rotate and shift
    default : shft_tmv = the_tmv;
  endcase
end
mod2p64_add #(.BLOCK_SIZE(BLOCK_SIZE)) m2p64add_ins0 (.m2p64add_in_one(int_key_in), .m2p64add_in_two(shft_tmv), .m2p64add_out(m2p64a0_out));

//Generation of the input to the transformations
always @ (*) begin
  if (BLOCK_SIZE == KEY_LENGTH) begin
    if (BLOCK_SIZE == 128) begin
      case (rnd_num_in) 
        5'd0    : trans_in = key_in;
        5'd2    : trans_in = {key_in[63:0], key_in[127:64]};
        5'd4    : trans_in = key_in;
        5'd6    : trans_in = {key_in[63:0], key_in[127:64]};
        5'd8    : trans_in = key_in;
        5'd10   : trans_in = {key_in[63:0], key_in[127:64]};
        default : trans_in = key_in;
      endcase
    end
    else if (BLOCK_SIZE == 256) begin
      case (rnd_num_in) 
        5'd0    : trans_in = key_in;
        5'd2    : trans_in = {key_in[191:0], key_in[255:192]};
        5'd4    : trans_in = {key_in[127:0], key_in[255:128]};
        5'd6    : trans_in = {key_in[63:0],  key_in[255:64]};
        5'd8    : trans_in = key_in;
        5'd10   : trans_in = {key_in[191:0], key_in[255:192]};
        5'd12   : trans_in = {key_in[127:0], key_in[255:128]};
        5'd14   : trans_in = {key_in[63:0],  key_in[255:64]};
        default : trans_in = key_in;
      endcase
    end
    else begin
      case (rnd_num_in) 
        5'd0    : trans_in = key_in;
        5'd2    : trans_in = {key_in[447:0], key_in[511:448]};
        5'd4    : trans_in = {key_in[383:0], key_in[511:384]};
        5'd6    : trans_in = {key_in[319:0], key_in[511:320]};
        5'd8    : trans_in = {key_in[255:0], key_in[511:256]};
        5'd10   : trans_in = {key_in[191:0], key_in[511:192]};
        5'd12   : trans_in = {key_in[127:0], key_in[511:128]};
        5'd14   : trans_in = {key_in[63:0],  key_in[511:64]};
        5'd16   : trans_in = key_in;
        5'd18   : trans_in = {key_in[447:0], key_in[511:448]};
        default : trans_in = key_in;
      endcase
    end
  end
  else begin
    if (BLOCK_SIZE == 128) begin
      case (rnd_num_in) 
        5'd0    : trans_in = key_in;
        5'd2    : trans_in = key_in;
        5'd4    : trans_in = {key_in[191:0], key_in[255:192]};
        5'd6    : trans_in = {key_in[191:0], key_in[255:192]};
        5'd8    : trans_in = {key_in[127:0], key_in[255:128]};
        5'd10   : trans_in = {key_in[127:0], key_in[255:128]};
        5'd12   : trans_in = {key_in[63:0],  key_in[255:64]};
        5'd14   : trans_in = {key_in[63:0],  key_in[255:64]};
        default : trans_in = key_in;
      endcase
    end
    else begin
      case (rnd_num_in) 
        5'd0    : trans_in = key_in;
        5'd2    : trans_in = key_in;
        5'd4    : trans_in = {key_in[447:0], key_in[511:448]};
        5'd6    : trans_in = {key_in[447:0], key_in[511:448]};
        5'd8    : trans_in = {key_in[383:0], key_in[511:384]};
        5'd10   : trans_in = {key_in[383:0], key_in[511:384]};
        5'd12   : trans_in = {key_in[319:0], key_in[511:320]};
        5'd14   : trans_in = {key_in[319:0], key_in[511:320]};
        5'd16   : trans_in = {key_in[255:0], key_in[511:256]};
        5'd18   : trans_in = {key_in[255:0], key_in[511:256]};
        default : trans_in = key_in;
      endcase
    end
  end
end
always @ (*) begin
  if (BLOCK_SIZE == KEY_LENGTH) begin
    trans_key_in = trans_in;
  end
  else begin
    case (rnd_num_in) 
      5'd0    : trans_key_in = trans_in[KEY_LENGTH-1:KEY_LENGTH-BLOCK_SIZE];
      5'd2    : trans_key_in = trans_in[BLOCK_SIZE-1:0];
      5'd4    : trans_key_in = trans_in[KEY_LENGTH-1:KEY_LENGTH-BLOCK_SIZE]; 
      5'd6    : trans_key_in = trans_in[BLOCK_SIZE-1:0]; 
      5'd8    : trans_key_in = trans_in[KEY_LENGTH-1:KEY_LENGTH-BLOCK_SIZE]; 
      5'd10   : trans_key_in = trans_in[BLOCK_SIZE-1:0]; 
      5'd12   : trans_key_in = trans_in[KEY_LENGTH-1:KEY_LENGTH-BLOCK_SIZE]; 
      5'd14   : trans_key_in = trans_in[BLOCK_SIZE-1:0]; 
      5'd16   : trans_key_in = trans_in[KEY_LENGTH-1:KEY_LENGTH-BLOCK_SIZE]; 
      5'd18   : trans_key_in = trans_in[BLOCK_SIZE-1:0]; 
      default : trans_key_in = trans_in[BLOCK_SIZE-1:0]; 
    endcase
  end
end

//Transformations
mod2p64_add #(.BLOCK_SIZE(BLOCK_SIZE)) m2p64add_ins1 (.m2p64add_in_one(m2p64a0_out), .m2p64add_in_two(trans_key_in), .m2p64add_out(m2p64a1_out));
substitute_byte_foursbox #(.BLOCK_SIZE(BLOCK_SIZE)) sb_ins0 (.sb_in(m2p64a1_out), .sb_out(sb0_out));
permute_state #(.BLOCK_SIZE(BLOCK_SIZE)) ps_ins0 (.ps_in(sb0_out), .ps_out(ps0_out));
mix_column #(.BLOCK_SIZE(BLOCK_SIZE)) mx_ins0 (.mc_in(ps0_out), .mc_out(mx0_out));
mod2_add #(.BLOCK_SIZE(BLOCK_SIZE)) m2a_ins0 (.m2add_in_one(m2p64a0_out), .m2add_in_two(mx0_out), .m2add_out(m2a0_out));
substitute_byte_foursbox #(.BLOCK_SIZE(BLOCK_SIZE)) sb_ins1 (.sb_in(m2a0_out), .sb_out(sb1_out));
permute_state #(.BLOCK_SIZE(BLOCK_SIZE)) ps_ins1 (.ps_in(sb1_out), .ps_out(ps1_out));
mix_column #(.BLOCK_SIZE(BLOCK_SIZE)) mx_ins1 (.mc_in(ps1_out), .mc_out(mx1_out));
mod2p64_add #(.BLOCK_SIZE(BLOCK_SIZE)) m2p64add_ins2 (.m2p64add_in_one(m2p64a0_out), .m2p64add_in_two(mx1_out), .m2p64add_out(m2p64a2_out));

//Output
assign even_key_out = m2p64a2_out;

endmodule

//ODD ROUND KEY GENERATION
module gen_odd_rnd_key #(parameter BLOCK_SIZE = 512) (even_key_in, odd_key_out);

input [BLOCK_SIZE-1:0] even_key_in;
output [BLOCK_SIZE-1:0] odd_key_out;

localparam the_lr = (BLOCK_SIZE/4+24);

assign odd_key_out = {even_key_in[BLOCK_SIZE-1-the_lr:0], even_key_in[BLOCK_SIZE-1:BLOCK_SIZE-the_lr]};

endmodule

//ROUND KEY GENERATION
module gen_rnd_key #(parameter BLOCK_SIZE = 512, parameter KEY_LENGTH = 512) (key_in, int_key_in, even_key_in, rnd_num_in, rnd_key_out);

input [KEY_LENGTH-1:0] key_in;
input [BLOCK_SIZE-1:0] int_key_in, even_key_in;
input [4:0] rnd_num_in;
output [BLOCK_SIZE-1:0] rnd_key_out;

//Variables
wire [BLOCK_SIZE-1:0] even_key_out, odd_key_out;

gen_even_rnd_key # (.BLOCK_SIZE(BLOCK_SIZE), .KEY_LENGTH(KEY_LENGTH)) gerk_ins (.key_in(key_in), .int_key_in(int_key_in), .rnd_num_in(rnd_num_in), .even_key_out(even_key_out));
gen_odd_rnd_key # (.BLOCK_SIZE(BLOCK_SIZE)) gork_ins (.even_key_in(even_key_in), .odd_key_out(odd_key_out));

assign rnd_key_out = (rnd_num_in[0] == 1'b0) ? even_key_out : odd_key_out;

endmodule

//KALYNA ENCRYPTION BLOCK - PARALLEL
module kalyna_enc_block_parallel #(parameter BLOCK_SIZE = 512, parameter KEY_LENGTH = 512) (block_in, key_in, block_out);

input [BLOCK_SIZE-1:0] block_in;
input [KEY_LENGTH-1:0] key_in;
output [BLOCK_SIZE-1:0] block_out;

localparam rnd_cnt = (BLOCK_SIZE == KEY_LENGTH && BLOCK_SIZE == 128) ? 5'd10 : (BLOCK_SIZE == KEY_LENGTH && BLOCK_SIZE == 256) ? 5'd14 : (BLOCK_SIZE == KEY_LENGTH && BLOCK_SIZE == 512) ? 5'd18 : (BLOCK_SIZE != KEY_LENGTH && BLOCK_SIZE == 128) ? 5'd14 : 5'd18;

//Variables
wire [BLOCK_SIZE-1:0] int_key;
wire [BLOCK_SIZE-1:0] key_rnd_arr [rnd_cnt:0];
wire [BLOCK_SIZE-1:0] sb_rnd_arr [rnd_cnt:0];
wire [BLOCK_SIZE-1:0] pr_rnd_arr [rnd_cnt:0];
wire [BLOCK_SIZE-1:0] mx_rnd_arr [rnd_cnt:0];
wire [BLOCK_SIZE-1:0] a2_rnd_arr [rnd_cnt-1:0];
wire [BLOCK_SIZE-1:0] m2p64a_lrnd;

//Generate Intermediate Key
gen_int_key #(.BLOCK_SIZE(BLOCK_SIZE), .KEY_LENGTH(KEY_LENGTH)) gik_ins (.key_in(key_in), .int_key_out(int_key));

//Transformations
//Round 0
gen_rnd_key #(.BLOCK_SIZE(BLOCK_SIZE), .KEY_LENGTH(KEY_LENGTH)) grk_ins0 (.key_in(key_in), .int_key_in(int_key), .even_key_in({BLOCK_SIZE{1'b0}}), .rnd_num_in(5'd0), .rnd_key_out(key_rnd_arr[0]));
mod2p64_add #(.BLOCK_SIZE(BLOCK_SIZE)) m2p64add_ins0 (.m2p64add_in_one(key_rnd_arr[0]), .m2p64add_in_two(block_in), .m2p64add_out(a2_rnd_arr[0]));

//Round 1---rnd_cnt-1
genvar i;
generate
  for (i=1; i<rnd_cnt; i=i+1) begin
    parameter [4:0] NR = i;

    gen_rnd_key #(.BLOCK_SIZE(BLOCK_SIZE), .KEY_LENGTH(KEY_LENGTH)) grk_ins (.key_in(key_in), .int_key_in(int_key), .even_key_in(key_rnd_arr[i-1]), .rnd_num_in(NR), .rnd_key_out(key_rnd_arr[i]));
    substitute_byte_foursbox #(.BLOCK_SIZE(BLOCK_SIZE)) sb_ins (.sb_in(a2_rnd_arr[i-1]), .sb_out(sb_rnd_arr[i]));
    permute_state #(.BLOCK_SIZE(BLOCK_SIZE)) ps_ins (.ps_in(sb_rnd_arr[i]), .ps_out(pr_rnd_arr[i]));
    mix_column #(.BLOCK_SIZE(BLOCK_SIZE)) mx_ins0 (.mc_in(pr_rnd_arr[i]), .mc_out(mx_rnd_arr[i]));
    mod2_add #(.BLOCK_SIZE(BLOCK_SIZE)) m2a_ins0 (.m2add_in_one(key_rnd_arr[i]), .m2add_in_two(mx_rnd_arr[i]), .m2add_out(a2_rnd_arr[i]));
  end  
endgenerate

//Last round
gen_rnd_key #(.BLOCK_SIZE(BLOCK_SIZE), .KEY_LENGTH(KEY_LENGTH)) grk_ins_lr (.key_in(key_in), .int_key_in(int_key), .even_key_in({BLOCK_SIZE{1'b0}}), .rnd_num_in(rnd_cnt), .rnd_key_out(key_rnd_arr[rnd_cnt]));
substitute_byte_foursbox #(.BLOCK_SIZE(BLOCK_SIZE)) sb_ins_lr (.sb_in(a2_rnd_arr[rnd_cnt-1]), .sb_out(sb_rnd_arr[rnd_cnt]));
permute_state #(.BLOCK_SIZE(BLOCK_SIZE)) ps_ins_lr (.ps_in(sb_rnd_arr[rnd_cnt]), .ps_out(pr_rnd_arr[rnd_cnt]));
mix_column #(.BLOCK_SIZE(BLOCK_SIZE)) mx_ins0_lr (.mc_in(pr_rnd_arr[rnd_cnt]), .mc_out(mx_rnd_arr[rnd_cnt]));
mod2p64_add #(.BLOCK_SIZE(BLOCK_SIZE)) m2p64add_ins_lr (.m2p64add_in_one(key_rnd_arr[rnd_cnt]), .m2p64add_in_two(mx_rnd_arr[rnd_cnt]), .m2p64add_out(m2p64a_lrnd));

assign block_out = m2p64a_lrnd;

endmodule

//KALYNA ENCRYPTION BLOCK - SERIAL - ONE ROUND IN ONE CLOCK CYCLE 
module kalyna_enc_block_serial #(parameter BLOCK_SIZE = 512, parameter KEY_LENGTH = 512) (clk, rst, start, block_in, key_in, block_out, block_rdy);

input clk, rst, start;
input [BLOCK_SIZE-1:0] block_in;
input [KEY_LENGTH-1:0] key_in;
output reg [BLOCK_SIZE-1:0] block_out;
output reg block_rdy;

localparam rnd_cnt = (BLOCK_SIZE == KEY_LENGTH && BLOCK_SIZE == 128) ? 5'd10 : (BLOCK_SIZE == KEY_LENGTH && BLOCK_SIZE == 256) ? 5'd14 : (BLOCK_SIZE == KEY_LENGTH && BLOCK_SIZE == 512) ? 5'd18 : (BLOCK_SIZE != KEY_LENGTH && BLOCK_SIZE == 128) ? 5'd14 : 5'd18;

//Variables
reg [4:0] rnd_counter, rnd_index;
reg [BLOCK_SIZE-1:0] rnd_block_in, fal_block_in, pre_key_reg, m2p64a_reg, m2a_reg;
wire [BLOCK_SIZE-1:0] int_key, rnd_key, m2p64a_out, m2a_out, sb_out, ps_out, mc_out;

//Counter
always @ (posedge clk) begin
  if (rst == 1'b1) begin
    rnd_counter <= 5'd0;
  end
  else begin
    if (start == 1'b0) begin
      rnd_counter <= 5'd0;
    end
    else begin
      if (rnd_counter <= rnd_cnt + 1'b1) begin
        rnd_counter <= rnd_counter + 1'b1;
      end
    end
  end
end
//rnd_index
always @ (*) begin
  if (rnd_counter > 5'd0) begin
    rnd_index = rnd_counter - 1'b1;
  end
  else begin
    rnd_index = 5'd0;
  end
end

//Registers
always @ (posedge clk) begin
  if (rst == 1'b1) begin
    block_rdy <= 1'b0;
    m2a_reg <= {BLOCK_SIZE{1'b0}};
    block_out <= {BLOCK_SIZE{1'b0}};
    m2p64a_reg <= {BLOCK_SIZE{1'b0}};
    pre_key_reg <= {BLOCK_SIZE{1'b0}};
  end
  else begin
    if (start == 1'b0) begin
      block_rdy <= 1'b0;
      m2a_reg <= {BLOCK_SIZE{1'b0}};
      block_out <= {BLOCK_SIZE{1'b0}};
      m2p64a_reg <= {BLOCK_SIZE{1'b0}};
      pre_key_reg <= {BLOCK_SIZE{1'b0}};
    end
    else begin
      m2a_reg <= m2a_out;
      pre_key_reg <= rnd_key;
      m2p64a_reg <= m2p64a_out;
      if (rnd_index == rnd_cnt) begin
        block_out <= m2p64a_out;
        block_rdy <= 1'b1;
      end
      else begin
        block_out <= {BLOCK_SIZE{1'b0}};
        block_rdy <= 1'b0;
      end
    end
  end
end

//Round Block Input
always @ (*) begin
  if (rnd_index == 5'd1) begin
    rnd_block_in = m2p64a_reg;
  end
  else begin
    rnd_block_in = m2a_reg;
  end
end

//First and Last Block Input
always @ (*) begin
  if (rnd_index == 5'd0) begin
    fal_block_in = block_in;
  end
  else if (rnd_index == rnd_cnt) begin
    fal_block_in = mc_out;
  end
  else begin
    fal_block_in = {BLOCK_SIZE{1'b0}};
  end
end

//Intermediate and Round Key
gen_int_key #(.BLOCK_SIZE(BLOCK_SIZE), .KEY_LENGTH(KEY_LENGTH)) gik_ins (.key_in(key_in), .int_key_out(int_key));
gen_rnd_key #(.BLOCK_SIZE(BLOCK_SIZE), .KEY_LENGTH(KEY_LENGTH)) grk_ins (.key_in(key_in), .int_key_in(int_key), .even_key_in(pre_key_reg), .rnd_num_in(rnd_index), .rnd_key_out(rnd_key));

//Transformations
mod2p64_add #(.BLOCK_SIZE(BLOCK_SIZE)) m2p64a_ins (.m2p64add_in_one(rnd_key), .m2p64add_in_two(fal_block_in), .m2p64add_out(m2p64a_out));
substitute_byte_foursbox #(.BLOCK_SIZE(BLOCK_SIZE)) sb_ins (.sb_in(rnd_block_in), .sb_out(sb_out));
permute_state #(.BLOCK_SIZE(BLOCK_SIZE)) ps_ins (.ps_in(sb_out), .ps_out(ps_out));
mix_column #(.BLOCK_SIZE(BLOCK_SIZE)) mx_ins (.mc_in(ps_out), .mc_out(mc_out));
mod2_add #(.BLOCK_SIZE(BLOCK_SIZE)) m2a_ins (.m2add_in_one(rnd_key), .m2add_in_two(mc_out), .m2add_out(m2a_out));

endmodule

//KALYNA ENCRYPTION BLOCK - SERIAL - ONE 64-bit OPERATION IN ONE CLOCK CYCLE - Hiding
module kalyna_enc_block_serial64b_oboc_hid #(parameter BLOCK_SIZE = 128, parameter KEY_LENGTH = 128) (clk, rst, start, block_in, key_in, block_out, block_rdy);

input clk, rst, start;
input [BLOCK_SIZE-1:0] block_in;
input [KEY_LENGTH-1:0] key_in;
output reg [BLOCK_SIZE-1:0] block_out;
output reg block_rdy;

//Local parameters
localparam bs_m8   = BLOCK_SIZE - 8;
localparam bs_d16  = BLOCK_SIZE/16;
localparam the_lr  = (BLOCK_SIZE/4+24);
localparam rnd_cnt = (BLOCK_SIZE == KEY_LENGTH && BLOCK_SIZE == 128) ? 5'd10 : (BLOCK_SIZE == KEY_LENGTH && BLOCK_SIZE == 256) ? 5'd14 : (BLOCK_SIZE == KEY_LENGTH && BLOCK_SIZE == 512) ? 5'd18 : (BLOCK_SIZE != KEY_LENGTH && BLOCK_SIZE == 128) ? 5'd14 : 5'd18;

//Variables
reg [4:0] rnd_num;
reg [5:0] curr_state;
reg [KEY_LENGTH-1:0] trans_in;
reg xor_start, add_start, sbpsmc_start, reg_block_rdy, reg_enc_start;
reg [BLOCK_SIZE-1:0] key_alfa, key_omega, add_one_in, add_two_in, int_key, shft_tmv, trans_key_in, tmv_key, round_out;
wire m2add_rdy, m2p64add_rdy, sbpsmc_rdy;
wire [BLOCK_SIZE-1:0] int_key_in, the_tmv;
wire [7:0] the_const = (BLOCK_SIZE+KEY_LENGTH)/64 + 1;
wire [BLOCK_SIZE-1:0] m2add_out, m2p64add_out, sbpsmc_out;

//Input to the intermediate key transformation
assign int_key_in = {the_const, {bs_m8{1'b0}}};

//Alfa and Omega Keys for the intermediate key transformation
always @ (*) begin
  if (BLOCK_SIZE == KEY_LENGTH) begin
    key_alfa = key_in;
    key_omega = key_in;
  end
  else begin
    key_alfa = key_in[KEY_LENGTH-1:KEY_LENGTH/2];
    key_omega = key_in[KEY_LENGTH/2-1:0];
  end
end

//Generation of the TMV signal and its shifted version
assign the_tmv= {bs_d16{16'h0100}};
always @ (*) begin
  case (rnd_num)
    5'd0    : shft_tmv = the_tmv;
    5'd2    : shft_tmv = {the_tmv[BLOCK_SIZE-2:0],  1'd0};
    5'd4    : shft_tmv = {the_tmv[BLOCK_SIZE-3:0],  2'd0};
    5'd6    : shft_tmv = {the_tmv[BLOCK_SIZE-4:0],  3'd0};
    5'd8    : shft_tmv = {the_tmv[BLOCK_SIZE-5:0],  4'd0};
    5'd10   : shft_tmv = {the_tmv[BLOCK_SIZE-6:0],  5'd0};
    5'd12   : shft_tmv = {the_tmv[BLOCK_SIZE-7:0],  6'd0};
    5'd14   : shft_tmv = {the_tmv[BLOCK_SIZE-8:0],  7'd0};
    5'd16   : shft_tmv = {the_tmv[BLOCK_SIZE-9:0],  7'd0, 1'b1};
    5'd18   : shft_tmv = {the_tmv[BLOCK_SIZE-10:0], 7'd0, 1'b1, 1'b0}; //Last two lines are due to the conflict between rotate and shift
    default : shft_tmv = the_tmv;
  endcase
end

//Generation of the input to the transformations
always @ (*) begin
  if (BLOCK_SIZE == KEY_LENGTH) begin
    if (BLOCK_SIZE == 128) begin
      case (rnd_num) 
        5'd0    : trans_in = key_in;
        5'd2    : trans_in = {key_in[63:0], key_in[127:64]};
        5'd4    : trans_in = key_in;
        5'd6    : trans_in = {key_in[63:0], key_in[127:64]};
        5'd8    : trans_in = key_in;
        5'd10   : trans_in = {key_in[63:0], key_in[127:64]};
        default : trans_in = key_in;
      endcase
    end
    else if (BLOCK_SIZE == 256) begin
      case (rnd_num) 
        5'd0    : trans_in = key_in;
        5'd2    : trans_in = {key_in[191:0], key_in[255:192]};
        5'd4    : trans_in = {key_in[127:0], key_in[255:128]};
        5'd6    : trans_in = {key_in[63:0],  key_in[255:64]};
        5'd8    : trans_in = key_in;
        5'd10   : trans_in = {key_in[191:0], key_in[255:192]};
        5'd12   : trans_in = {key_in[127:0], key_in[255:128]};
        5'd14   : trans_in = {key_in[63:0],  key_in[255:64]};
        default : trans_in = key_in;
      endcase
    end
    else begin
      case (rnd_num) 
        5'd0    : trans_in = key_in;
        5'd2    : trans_in = {key_in[447:0], key_in[511:448]};
        5'd4    : trans_in = {key_in[383:0], key_in[511:384]};
        5'd6    : trans_in = {key_in[319:0], key_in[511:320]};
        5'd8    : trans_in = {key_in[255:0], key_in[511:256]};
        5'd10   : trans_in = {key_in[191:0], key_in[511:192]};
        5'd12   : trans_in = {key_in[127:0], key_in[511:128]};
        5'd14   : trans_in = {key_in[63:0],  key_in[511:64]};
        5'd16   : trans_in = key_in;
        5'd18   : trans_in = {key_in[447:0], key_in[511:448]};
        default : trans_in = key_in;
      endcase
    end
  end
  else begin
    if (BLOCK_SIZE == 128) begin
      case (rnd_num) 
        5'd0    : trans_in = key_in;
        5'd2    : trans_in = key_in;
        5'd4    : trans_in = {key_in[191:0], key_in[255:192]};
        5'd6    : trans_in = {key_in[191:0], key_in[255:192]};
        5'd8    : trans_in = {key_in[127:0], key_in[255:128]};
        5'd10   : trans_in = {key_in[127:0], key_in[255:128]};
        5'd12   : trans_in = {key_in[63:0],  key_in[255:64]};
        5'd14   : trans_in = {key_in[63:0],  key_in[255:64]};
        default : trans_in = key_in;
      endcase
    end
    else begin
      case (rnd_num) 
        5'd0    : trans_in = key_in;
        5'd2    : trans_in = key_in;
        5'd4    : trans_in = {key_in[447:0], key_in[511:448]};
        5'd6    : trans_in = {key_in[447:0], key_in[511:448]};
        5'd8    : trans_in = {key_in[383:0], key_in[511:384]};
        5'd10   : trans_in = {key_in[383:0], key_in[511:384]};
        5'd12   : trans_in = {key_in[319:0], key_in[511:320]};
        5'd14   : trans_in = {key_in[319:0], key_in[511:320]};
        5'd16   : trans_in = {key_in[255:0], key_in[511:256]};
        5'd18   : trans_in = {key_in[255:0], key_in[511:256]};
        default : trans_in = key_in;
      endcase
    end
  end
end
always @ (*) begin
  if (BLOCK_SIZE == KEY_LENGTH) begin
    trans_key_in = trans_in;
  end
  else begin
    case (rnd_num) 
      5'd0    : trans_key_in = trans_in[KEY_LENGTH-1:KEY_LENGTH-BLOCK_SIZE];
      5'd2    : trans_key_in = trans_in[BLOCK_SIZE-1:0];
      5'd4    : trans_key_in = trans_in[KEY_LENGTH-1:KEY_LENGTH-BLOCK_SIZE]; 
      5'd6    : trans_key_in = trans_in[BLOCK_SIZE-1:0]; 
      5'd8    : trans_key_in = trans_in[KEY_LENGTH-1:KEY_LENGTH-BLOCK_SIZE]; 
      5'd10   : trans_key_in = trans_in[BLOCK_SIZE-1:0]; 
      5'd12   : trans_key_in = trans_in[KEY_LENGTH-1:KEY_LENGTH-BLOCK_SIZE]; 
      5'd14   : trans_key_in = trans_in[BLOCK_SIZE-1:0]; 
      5'd16   : trans_key_in = trans_in[KEY_LENGTH-1:KEY_LENGTH-BLOCK_SIZE]; 
      5'd18   : trans_key_in = trans_in[BLOCK_SIZE-1:0]; 
      default : trans_key_in = trans_in[BLOCK_SIZE-1:0]; 
    endcase
  end
end

//The reg_enc_start signal indicates that the encryption process is started
always @ (posedge clk) begin
  if (rst == 1'b1) begin
    reg_enc_start <= 1'b0;
  end
  else begin
    if (block_rdy == 1'b1) begin
      reg_enc_start <= 1'b0;
    end
    else begin
      if (start == 1'b1) begin
        reg_enc_start <= 1'b1;
      end
    end
  end
end

//Block inputs in each state  
always @ (posedge clk) begin
  if (rst == 1'b1) begin
    rnd_num <= 5'd0;
    add_start <= 1'b0;
    xor_start <= 1'b0;
    curr_state <= 6'd0;
    sbpsmc_start <= 1'b0;
    reg_block_rdy <= 1'b0;
    tmv_key <= {BLOCK_SIZE{1'b0}};
    int_key <= {BLOCK_SIZE{1'b0}};
    round_out <= {BLOCK_SIZE{1'b0}};
    add_one_in <= {BLOCK_SIZE{1'b0}};
    add_two_in <= {BLOCK_SIZE{1'b0}};
  end
  else begin
    if (reg_enc_start == 1'b0) begin
      rnd_num <= 5'd0;
      add_start <= 1'b0;
      xor_start <= 1'b0;
      curr_state <= 6'd0;
      sbpsmc_start <= 1'b0;
      reg_block_rdy <= 1'b0;
      tmv_key <= {BLOCK_SIZE{1'b0}};
      int_key <= {BLOCK_SIZE{1'b0}};
      round_out <= {BLOCK_SIZE{1'b0}};
      add_one_in <= {BLOCK_SIZE{1'b0}};
      add_two_in <= {BLOCK_SIZE{1'b0}};
    end
    else begin
      case (curr_state)
        //Intermediate key generattion starts here
        6'd0 : begin
          //SOME OPERATIONS
          xor_start <= add_one_in[0];
          sbpsmc_start <= add_one_in[1];

          //ADD - INTKEY
          add_start <= 1'b1;
          add_one_in <= int_key_in;
          add_two_in <= key_alfa;

          curr_state <= 6'd1;
        end
        6'd1 : begin
          if (m2p64add_rdy == 1'b1) begin
            //SOME OPERATIONS
            add_start <= add_one_in[2];
            xor_start <= add_one_in[3];

            //SPLT - INTKEY
            sbpsmc_start <= 1'b1;
            add_one_in <= m2p64add_out;

            curr_state <= 6'd2;
          end
        end
        6'd2 : begin
          if (sbpsmc_rdy == 1'b1) begin
            //SOME OPERATIONS
            add_start <= add_one_in[4];
            sbpsmc_start <= add_one_in[5];

            //XOR - INTKEY
            xor_start <= 1'b1;
            add_one_in <= key_omega;
            add_two_in <= sbpsmc_out;

            curr_state <= 6'd3;
          end
        end
        6'd3 : begin
          if (m2add_rdy == 1'b1) begin
            //SOME OPERATIONS
            add_start <= add_one_in[6];
            xor_start <= add_one_in[7];

            //SPLT - INTKEY
            sbpsmc_start <= 1'b1;
            add_one_in <= m2add_out;
            
            curr_state <= 6'd4;
          end
        end
        6'd4 : begin
          if (sbpsmc_rdy == 1'b1) begin
            //SOME OPERATIONS
            xor_start <= add_one_in[8];
            sbpsmc_start <= add_one_in[9];

            //ADD - INTKEY
            add_start <= 1'b1;
            add_one_in <= key_alfa;
            add_two_in <= sbpsmc_out;

            curr_state <= 6'd5;
          end
        end
        6'd5 : begin
          if (m2p64add_rdy == 1'b1) begin
            //SOME OPERATIONS
            add_start <= add_one_in[10];
            xor_start <= add_one_in[11];

            //RND - KEY0
            rnd_num <= 5'd0;

            //SPLT - INTKEY
            sbpsmc_start <= 1'b1;
            add_one_in <= m2p64add_out;
            
            curr_state <= 6'd6;
          end
        end
        //Intermediate key generation ends and round 0 key generation starts here
        6'd6 : begin
          if (sbpsmc_rdy == 1'b1) begin
            //SOME OPERATIONS
            xor_start <= add_one_in[12];
            sbpsmc_start <= add_one_in[13];

            int_key <= sbpsmc_out;

            //ADD - KEY0
            add_start <= 1'b1;
            add_one_in <= sbpsmc_out;
            add_two_in <= shft_tmv;

            curr_state <= 6'd7;
          end
        end
        6'd7 : begin
          if (m2p64add_rdy == 1'b1) begin
            //SOME OPERATIONS
            xor_start <= add_one_in[14];
            sbpsmc_start <= add_one_in[15];

            tmv_key <= m2p64add_out;

            //ADD - KEY0
            add_one_in <= m2p64add_out;
            add_two_in <= trans_key_in;

            curr_state <= 6'd8;
          end
        end
        6'd8 : begin
          if (m2p64add_rdy == 1'b1) begin
            //SOME OPERATIONS
            add_start <= add_one_in[16];
            xor_start <= add_one_in[17];

            //SPLT - KEY0
            sbpsmc_start <= 1'b1;
            add_one_in <= m2p64add_out;

            curr_state <= 6'd9;
          end
        end
        6'd9 : begin
          if (sbpsmc_rdy == 1'b1) begin
            //SOME OPERATIONS
            add_start <= add_one_in[18];
            sbpsmc_start <= add_one_in[19];

            //XOR - KEY0
            xor_start <= 1'b1;
            add_one_in <= tmv_key;
            add_two_in <= sbpsmc_out;

            curr_state <= 6'd10;
          end
        end
        6'd10 : begin
          if (m2add_rdy == 1'b1) begin
            //SOME OPERATIONS
            add_start <= add_one_in[20];
            xor_start <= add_one_in[21];

            //SPLT - KEY0
            sbpsmc_start <= 1'b1;
            add_one_in <= m2add_out;

            curr_state <= 6'd11;
          end
        end
        6'd11 : begin
          if (sbpsmc_rdy == 1'b1) begin
            //SOME OPERATIONS
            xor_start <= add_one_in[22];
            sbpsmc_start <= add_one_in[23];

            //ADD - KEY0
            add_start <= 1'b1;
            add_one_in <= tmv_key;
            add_two_in <= sbpsmc_out;

            curr_state <= 6'd12;
          end
        end
        //Round 0 key generation ends here and Round 0-1 operations start here
        6'd12 : begin
          if (m2p64add_rdy == 1'b1) begin
            //SOME OPERATIONS
            xor_start <= add_one_in[24];
            sbpsmc_start <= add_one_in[25];

            tmv_key <= m2p64add_out;
            //ADD - RND0
            add_one_in <= m2p64add_out;
            add_two_in <= block_in;

            curr_state <= 6'd13;
          end
        end
        6'd13 : begin
          if (m2p64add_rdy == 1'b1) begin
            //SOME OPERATIONS
            add_start <= add_one_in[26];
            xor_start <= add_one_in[27];

            //SPLT - RND1
            sbpsmc_start <= 1'b1;
            add_one_in <= m2p64add_out;

            curr_state <= 6'd14;
          end
        end
        6'd14 : begin
          if (sbpsmc_rdy == 1'b1) begin
            //SOME OPERATIONS
            add_start <= add_one_in[28];
            sbpsmc_start <= add_one_in[29];

            //RND - KEY2
            rnd_num <= rnd_num + 5'd2;
            //XOR - RND1
            xor_start <= 1'b1;
            add_one_in <= sbpsmc_out;
            add_two_in <= {tmv_key[BLOCK_SIZE-1-the_lr:0], tmv_key[BLOCK_SIZE-1:BLOCK_SIZE-the_lr]};

            curr_state <= 6'd15;
          end
        end
        //Round 2 key generation starts here
        6'd15 : begin
          if (m2add_rdy == 1'b1) begin
            //SOME OPERATIONS
            xor_start <= add_one_in[30];
            sbpsmc_start <= add_one_in[31];

            round_out <= m2add_out;
            //ADD - KEY2
            add_start <= 1'b1;
            add_one_in <= int_key;
            add_two_in <= shft_tmv;

            curr_state <= 6'd16;
          end
        end
        6'd16 : begin
          if (m2p64add_rdy == 1'b1) begin
            //SOME OPERATIONS
            xor_start <= add_one_in[32];
            sbpsmc_start <= add_one_in[33];

            tmv_key <= m2p64add_out;

            //ADD - KEY2
            add_one_in <= m2p64add_out;
            add_two_in <= trans_key_in;

            curr_state <= 6'd17;
          end
        end
        6'd17 : begin
          if (m2p64add_rdy == 1'b1) begin
            //SOME OPERATIONS
            add_start <= add_one_in[34];
            xor_start <= add_one_in[35];

            //SPLT - KEY2
            sbpsmc_start <= 1'b1;
            add_one_in <= m2p64add_out;

            curr_state <= 6'd18;
          end
        end
        6'd18 : begin
          if (sbpsmc_rdy == 1'b1) begin
            //SOME OPERATIONS
            add_start <= add_one_in[36];
            sbpsmc_start <= add_one_in[37];

            //XOR - KEY2
            xor_start <= 1'b1;
            add_one_in <= tmv_key;
            add_two_in <= sbpsmc_out;

            curr_state <= 6'd19;
          end
        end
        6'd19 : begin
          if (m2add_rdy == 1'b1) begin
            //SOME OPERATIONS
            add_start <= add_one_in[38];
            xor_start <= add_one_in[39];

            //SPLT - KEY2
            sbpsmc_start <= 1'b1;
            add_one_in <= m2add_out;

            curr_state <= 6'd20;
          end
        end
        6'd20 : begin
          if (sbpsmc_rdy == 1'b1) begin
            //SOME OPERATIONS
            xor_start <= add_one_in[40];
            sbpsmc_start <= add_one_in[41];

            //ADD - KEY2
            add_start <= 1'b1;
            add_one_in <= tmv_key;
            add_two_in <= sbpsmc_out;

            curr_state <= 6'd21;
          end
        end
        //Round 2 key generation ends here and Round 2-3 operations start here
        6'd21 : begin
          if (m2p64add_rdy == 1'b1) begin
            //SOME OPERATIONS
            add_start <= add_one_in[42];
            xor_start <= add_one_in[43];

            tmv_key <= m2p64add_out;

            //SPLT - RND2
            sbpsmc_start <= 1'b1;
            add_one_in <= round_out;

            curr_state <= 6'd22;
          end
        end
        6'd22 : begin
          if (sbpsmc_rdy == 1'b1) begin
            //SOME OPERATIONS
            add_start <= add_one_in[44];
            sbpsmc_start <= add_one_in[45];

            //XOR - RND2
            xor_start <= 1'b1;
            add_one_in <= sbpsmc_out;
            add_two_in <= tmv_key;

            curr_state <= 6'd23;
          end
        end
        6'd23 : begin
          if (m2add_rdy == 1'b1) begin
            //SOME OPERATIONS
            add_start <= add_one_in[46];
            xor_start <= add_one_in[47];

            //SPLT -RND3
            sbpsmc_start <= 1'b1;
            add_one_in <= m2add_out;

            curr_state <= 6'd24;
          end
        end
        6'd24 : begin
          if (sbpsmc_rdy == 1'b1) begin
            //SOME OPERATIONS
            add_start <= add_one_in[48];
            sbpsmc_start <= add_one_in[49];

            //RND - KEY4
            rnd_num <= rnd_num + 5'd2;

            //XOR - RND3
            xor_start <= 1'b1;
            add_one_in <= sbpsmc_out;
            add_two_in <= {tmv_key[BLOCK_SIZE-1-the_lr:0], tmv_key[BLOCK_SIZE-1:BLOCK_SIZE-the_lr]};

            curr_state <= 6'd25;
          end
        end
        //Round 2-3 operations end here and Round 4 key generation starts here
        6'd25 : begin
          if (m2add_rdy == 1'b1) begin
            //SOME OPERATIONS
            xor_start <= add_one_in[50];
            sbpsmc_start <= add_one_in[51];

            round_out <= m2add_out;
            //ADD - KEY4
            add_start <= 1'b1;
            add_one_in <= int_key;
            add_two_in <= shft_tmv;

            curr_state <= 6'd26;
          end
        end
        6'd26 : begin
          if (m2p64add_rdy == 1'b1) begin
            //SOME OPERATIONS
            xor_start <= add_one_in[52];
            sbpsmc_start <= add_one_in[53];

            tmv_key <= m2p64add_out;

            //ADD - KEY4
            add_one_in <= m2p64add_out;
            add_two_in <= trans_key_in;

            curr_state <= 6'd27;
          end
        end
        6'd27 : begin
          if (m2p64add_rdy == 1'b1) begin
            //SOME OPERATIONS
            add_start <= add_one_in[54];
            xor_start <= add_one_in[55];

            //SPLT - KEY4
            sbpsmc_start <= 1'b1;
            add_one_in <= m2p64add_out;

            curr_state <= 6'd28;
          end
        end
        6'd28 : begin
          if (sbpsmc_rdy == 1'b1) begin
            //SOME OPERATIONS
            add_start <= add_one_in[56];
            sbpsmc_start <= add_one_in[57];

            //XOR - KEY4
            xor_start <= 1'b1;
            add_one_in <= tmv_key;
            add_two_in <= sbpsmc_out;

            curr_state <= 6'd29;
          end
        end
        6'd29 : begin
          if (m2add_rdy == 1'b1) begin
            //SOME OPERATIONS
            add_start <= add_one_in[58];
            xor_start <= add_one_in[59];

            //SPLT - KEY4
            sbpsmc_start <= 1'b1;
            add_one_in <= m2add_out;

            curr_state <= 6'd30;
          end
        end
        6'd30 : begin
          if (sbpsmc_rdy == 1'b1) begin
            //SOME OPERATIONS
            xor_start <= add_one_in[60];
            sbpsmc_start <= add_one_in[61];

            //ADD - KEY4
            add_start <= 1'b1;
