        end
        6'd59 : begin
          if (m2add_rdy == 1'b1) begin
            //SOME OPERATIONS
            add_start <= add_one_in[118];
            xor_start <= add_one_in[119];

            //SPLT - KEY10
            sbpsmc_start <= 1'b1;
            add_one_in <= m2add_out;

