            sbpsmc_start <= add_one_in[125];

            //ADD - RND10
            add_start <= 1'b1;
            add_one_in <= sbpsmc_out;
            add_two_in <= tmv_key;

            curr_state <= 6'd63;
          end
        end
        6'd63 : begin
          if (m2p64add_rdy == 1'b1) begin
            //SOME OPERATIONS
            add_start <= 1'b0;
            xor_start <= 1'b0;
            sbpsmc_start <= 1'b0;

            round_out <= m2p64add_out;
            reg_block_rdy <= 1'b1;

            curr_state <= 6'd0;
          end
        end
        default : begin
          rnd_num <= 5'd0;
          add_start <= 1'b0;
          xor_start <= 1'b0;
          curr_state <= 6'd0;
          sbpsmc_start <= 1'b0;
          reg_block_rdy <= 1'b0;
          tmv_key <= {BLOCK_SIZE{1'b0}};
          int_key <= {BLOCK_SIZE{1'b0}};
          round_out <= {BLOCK_SIZE{1'b0}};
          add_one_in <= {BLOCK_SIZE{1'b0}};
          add_two_in <= {BLOCK_SIZE{1'b0}};
        end
      endcase
    end
  end
end

//Pseudo-Random Number Generator
`ifdef XORSHIFT
  //XORSHIFT
  xorshift64 xs_ins (.clk(clk), .rst(rst), .start(reg_enc_start), .seed(block_in[63:0]), .xs_out(prng_out));
`elsif LFSR
  //LFSR
  lfsr64 lfsr_ins (.clk(clk), .rst(rst), .start(reg_enc_start), .seed(block_in[63:0]), .lfsr_out(prng_out));
`endif

//Additions - Duplication
mod2_add_serial64b_fom #(.BLOCK_SIZE(BLOCK_SIZE)) m2a_ins1 (.clk(clk), .rst(rst), .m2add_start(xor_start), .m2add_in_one(add_one_in), .m2add_in_two(add_two_in), .lfsr_in(prng_out), .m2add_out(m2add_out_one), .m2add_rdy(m2add_rdy_one));
mod2_add_serial64b #(.BLOCK_SIZE(BLOCK_SIZE)) m2a_ins2 (.clk(clk), .rst(rst), .m2add_start(xor_start), .m2add_in_one(add_two_in), .m2add_in_two(add_one_in), .m2add_out(m2add_out_two), .m2add_rdy(m2add_rdy_two));
mod2p64_add_serial64b_fom #(.BLOCK_SIZE(BLOCK_SIZE)) m2p64a_ins1 (.clk(clk), .rst(rst), .m2p64add_start(add_start), .m2p64add_in_one(add_one_in), .m2p64add_in_two(add_two_in), .lfsr_in(prng_out), .m2p64add_out(m2p64add_out_one), .m2p64add_rdy(m2p64add_rdy_one));
mod2p64_add_serial64b #(.BLOCK_SIZE(BLOCK_SIZE)) m2p64a_ins2 (.clk(clk), .rst(rst), .m2p64add_start(add_start), .m2p64add_in_one(add_two_in), .m2p64add_in_two(add_one_in), .m2p64add_out(m2p64add_out_two), .m2p64add_rdy(m2p64add_rdy_two));
//Substitution Permutation Mix-Column - Duplication
sbpsmc_serial64b_fom #(.BLOCK_SIZE(BLOCK_SIZE)) sbpsmc64b_ins1 (.clk(clk), .rst(rst), .sbpsmc_start(sbpsmc_start), .sbpsmc_in(add_one_in), .lfsr_in(prng_out), .sbpsmc_out(sbpsmc_out_one), .sbpsmc_rdy(sbpsmc_rdy_one));
sbpsmc_serial64b #(.BLOCK_SIZE(BLOCK_SIZE)) sbpsmc64b_ins2 (.clk(clk), .rst(rst), .sbpsmc_start(sbpsmc_start), .sbpsmc_in(add_one_in), .sbpsmc_out(sbpsmc_out_two), .sbpsmc_rdy(sbpsmc_rdy_two));

//Duplication Comparisons
//Modulo 2 Addition
assign m2add_rdy = m2add_rdy_one & m2add_rdy_two;
always @ (m2add_rdy, m2add_out_one, m2add_out_two) begin
  if (m2add_rdy == 1'b1) begin
    if (m2add_out_one == m2add_out_two) begin
      m2add_out = m2add_out_one;
    end
    else begin
      m2add_out = {BLOCK_SIZE{1'b0}};
    end
  end
  else begin
    m2add_out = m2add_out_one;
  end
end
//Modulo 2^64 Addition
assign m2p64add_rdy = m2p64add_rdy_one & m2p64add_rdy_two;
always @ (m2p64add_rdy, m2p64add_out_one, m2p64add_out_two) begin
  if (m2p64add_rdy == 1'b1) begin
    if (m2p64add_out_one == m2p64add_out_two) begin
      m2p64add_out = m2p64add_out_one;
    end
    else begin
      m2p64add_out = {BLOCK_SIZE{1'b0}};
    end
  end
  else begin
    m2p64add_out = m2p64add_out_one;
  end
end
//SPM
assign sbpsmc_rdy = sbpsmc_rdy_one & sbpsmc_rdy_two;
always @ (sbpsmc_rdy, sbpsmc_out_one, sbpsmc_out_two) begin
  if (sbpsmc_rdy == 1'b1) begin
    if (sbpsmc_out_one == sbpsmc_out_two) begin
      sbpsmc_out = sbpsmc_out_one;
    end
    else begin
      sbpsmc_out = {BLOCK_SIZE{1'b0}};
    end
  end
  else begin
    sbpsmc_out = sbpsmc_out_one;
  end
end

//Fault Injection
assign flt_inj = ((m2add_rdy & m2add_out_one != m2add_out_two) | (m2p64add_rdy & m2p64add_out_one != m2p64add_out_two) | (sbpsmc_rdy & sbpsmc_out_one != sbpsmc_out_two)) ? 1'b1 : 1'b0;
always @ (posedge clk) begin
  if (rst == 1'b1) begin
    reg_flt_inj <= 1'b0;
  end
  else begin
    if (flt_inj == 1'b1) begin
      reg_flt_inj <= 1'b1;
    end
  end
end

//Previous current state
always @ (posedge clk) begin
  if (rst == 1'b1) begin
    pre_curr_state <= 6'd0;
  end
  else begin
    if (reg_enc_start == 1'b0) begin
      pre_curr_state <= 6'd0;
    end
    else begin
      if (m2add_rdy == 1'b1 | m2p64add_rdy == 1'b1 | sbpsmc_rdy == 1'b1) begin
        pre_curr_state <= curr_state;
      end
    end
  end
end

//Fault in the state
assign flt_state = (pre_curr_state != 6'd55 & pre_curr_state != 6'd63 & curr_state - pre_curr_state > 6'd1) ? 1'b1 : 1'b0;
always @ (posedge clk) begin
  if (rst == 1'b1) begin
    reg_flt_state <= 1'b0;
  end
  else begin
    if (flt_state == 1'b1) begin
      reg_flt_state <= 1'b1;
    end
  end
end

//Block Outputs
always @ (posedge clk) begin
  if (rst == 1'b1) begin
    block_rdy <= 1'b0;
    block_out <= {BLOCK_SIZE{1'b0}};
  end
  else begin
    if (reg_enc_start == 1'b0) begin
      block_rdy <= 1'b0;
      block_out <= {BLOCK_SIZE{1'b0}};
    end
    else begin
      if (reg_block_rdy == 1'b1) begin
        block_rdy <= 1'b1;
        block_out <= round_out;
      end
    end
  end
end

endmodule

//KALYNA ENCRYPTION BLOCK - SERIAL - ONE 64-bit OPERATION IN ONE CLOCK CYCLE - First-Order Masking and Hiding + Duplication
module kalyna_enc_block_serial64b_oboc_fomhiddup #(parameter BLOCK_SIZE = 128, parameter KEY_LENGTH = 128) (clk, rst, start, block_in, key_in, block_out, block_rdy);

input clk, rst, start;
input [BLOCK_SIZE-1:0] block_in;
input [KEY_LENGTH-1:0] key_in;
output reg [BLOCK_SIZE-1:0] block_out;
output reg block_rdy;

//Local parameters
localparam bs_m8   = BLOCK_SIZE - 8;
localparam bs_d16  = BLOCK_SIZE/16;
localparam the_lr  = (BLOCK_SIZE/4+24);
localparam rnd_cnt = (BLOCK_SIZE == KEY_LENGTH && BLOCK_SIZE == 128) ? 5'd10 : (BLOCK_SIZE == KEY_LENGTH && BLOCK_SIZE == 256) ? 5'd14 : (BLOCK_SIZE == KEY_LENGTH && BLOCK_SIZE == 512) ? 5'd18 : (BLOCK_SIZE != KEY_LENGTH && BLOCK_SIZE == 128) ? 5'd14 : 5'd18;

//Variables
reg [4:0] rnd_num;
reg [KEY_LENGTH-1:0] trans_in;
reg [5:0] curr_state, pre_curr_state;
reg xor_start, add_start, sbpsmc_start, reg_block_rdy, reg_enc_start, reg_flt_inj;
reg [BLOCK_SIZE-1:0] key_alfa, key_omega, add_one_in, add_two_in, int_key, shft_tmv, trans_key_in, tmv_key, round_out, m2add_out, m2p64add_out, sbpsmc_out;
wire [63:0] prng_out_one, prng_out_two;
wire [BLOCK_SIZE-1:0] int_key_in, the_tmv;
wire [7:0] the_const = (BLOCK_SIZE+KEY_LENGTH)/64 + 1;
wire [BLOCK_SIZE-1:0] m2add_out_one, m2add_out_two, m2p64add_out_one, m2p64add_out_two, sbpsmc_out_one, sbpsmc_out_two;
wire m2add_rdy, m2add_rdy_one, m2add_rdy_two, m2p64add_rdy, m2p64add_rdy_one, m2p64add_rdy_two, sbpsmc_rdy, sbpsmc_rdy_one, sbpsmc_rdy_two, flt_inj, flt_state;

//Input to the intermediate key transformation
assign int_key_in = {the_const, {bs_m8{1'b0}}};

//Alfa and Omega Keys for the intermediate key transformation
always @ (*) begin
  if (BLOCK_SIZE == KEY_LENGTH) begin
    key_alfa = key_in;
    key_omega = key_in;
  end
  else begin
    key_alfa = key_in[KEY_LENGTH-1:KEY_LENGTH/2];
    key_omega = key_in[KEY_LENGTH/2-1:0];
  end
end

//Generation of the TMV signal and its shifted version
assign the_tmv= {bs_d16{16'h0100}};
always @ (*) begin
  case (rnd_num)
    5'd0    : shft_tmv = the_tmv;
    5'd2    : shft_tmv = {the_tmv[BLOCK_SIZE-2:0],  1'd0};
    5'd4    : shft_tmv = {the_tmv[BLOCK_SIZE-3:0],  2'd0};
    5'd6    : shft_tmv = {the_tmv[BLOCK_SIZE-4:0],  3'd0};
    5'd8    : shft_tmv = {the_tmv[BLOCK_SIZE-5:0],  4'd0};
    5'd10   : shft_tmv = {the_tmv[BLOCK_SIZE-6:0],  5'd0};
    5'd12   : shft_tmv = {the_tmv[BLOCK_SIZE-7:0],  6'd0};
    5'd14   : shft_tmv = {the_tmv[BLOCK_SIZE-8:0],  7'd0};
    5'd16   : shft_tmv = {the_tmv[BLOCK_SIZE-9:0],  7'd0, 1'b1};
    5'd18   : shft_tmv = {the_tmv[BLOCK_SIZE-10:0], 7'd0, 1'b1, 1'b0}; //Last two lines are due to the conflict between rotate and shift
    default : shft_tmv = the_tmv;
  endcase
end

//Generation of the input to the transformations
always @ (*) begin
  if (BLOCK_SIZE == KEY_LENGTH) begin
    if (BLOCK_SIZE == 128) begin
      case (rnd_num) 
        5'd0    : trans_in = key_in;
        5'd2    : trans_in = {key_in[63:0], key_in[127:64]};
        5'd4    : trans_in = key_in;
        5'd6    : trans_in = {key_in[63:0], key_in[127:64]};
        5'd8    : trans_in = key_in;
        5'd10   : trans_in = {key_in[63:0], key_in[127:64]};
        default : trans_in = key_in;
      endcase
    end
    else if (BLOCK_SIZE == 256) begin
      case (rnd_num) 
        5'd0    : trans_in = key_in;
        5'd2    : trans_in = {key_in[191:0], key_in[255:192]};
        5'd4    : trans_in = {key_in[127:0], key_in[255:128]};
        5'd6    : trans_in = {key_in[63:0],  key_in[255:64]};
        5'd8    : trans_in = key_in;
        5'd10   : trans_in = {key_in[191:0], key_in[255:192]};
        5'd12   : trans_in = {key_in[127:0], key_in[255:128]};
        5'd14   : trans_in = {key_in[63:0],  key_in[255:64]};
        default : trans_in = key_in;
      endcase
    end
    else begin
      case (rnd_num) 
        5'd0    : trans_in = key_in;
        5'd2    : trans_in = {key_in[447:0], key_in[511:448]};
        5'd4    : trans_in = {key_in[383:0], key_in[511:384]};
        5'd6    : trans_in = {key_in[319:0], key_in[511:320]};
        5'd8    : trans_in = {key_in[255:0], key_in[511:256]};
        5'd10   : trans_in = {key_in[191:0], key_in[511:192]};
        5'd12   : trans_in = {key_in[127:0], key_in[511:128]};
        5'd14   : trans_in = {key_in[63:0],  key_in[511:64]};
        5'd16   : trans_in = key_in;
        5'd18   : trans_in = {key_in[447:0], key_in[511:448]};
        default : trans_in = key_in;
      endcase
    end
  end
  else begin
    if (BLOCK_SIZE == 128) begin
      case (rnd_num) 
        5'd0    : trans_in = key_in;
        5'd2    : trans_in = key_in;
        5'd4    : trans_in = {key_in[191:0], key_in[255:192]};
        5'd6    : trans_in = {key_in[191:0], key_in[255:192]};
        5'd8    : trans_in = {key_in[127:0], key_in[255:128]};
        5'd10   : trans_in = {key_in[127:0], key_in[255:128]};
        5'd12   : trans_in = {key_in[63:0],  key_in[255:64]};
        5'd14   : trans_in = {key_in[63:0],  key_in[255:64]};
        default : trans_in = key_in;
      endcase
    end
    else begin
      case (rnd_num) 
        5'd0    : trans_in = key_in;
        5'd2    : trans_in = key_in;
        5'd4    : trans_in = {key_in[447:0], key_in[511:448]};
        5'd6    : trans_in = {key_in[447:0], key_in[511:448]};
        5'd8    : trans_in = {key_in[383:0], key_in[511:384]};
        5'd10   : trans_in = {key_in[383:0], key_in[511:384]};
        5'd12   : trans_in = {key_in[319:0], key_in[511:320]};
        5'd14   : trans_in = {key_in[319:0], key_in[511:320]};
        5'd16   : trans_in = {key_in[255:0], key_in[511:256]};
        5'd18   : trans_in = {key_in[255:0], key_in[511:256]};
        default : trans_in = key_in;
      endcase
    end
  end
end
always @ (*) begin
  if (BLOCK_SIZE == KEY_LENGTH) begin
    trans_key_in = trans_in;
  end
  else begin
    case (rnd_num) 
      5'd0    : trans_key_in = trans_in[KEY_LENGTH-1:KEY_LENGTH-BLOCK_SIZE];
      5'd2    : trans_key_in = trans_in[BLOCK_SIZE-1:0];
      5'd4    : trans_key_in = trans_in[KEY_LENGTH-1:KEY_LENGTH-BLOCK_SIZE]; 
      5'd6    : trans_key_in = trans_in[BLOCK_SIZE-1:0]; 
      5'd8    : trans_key_in = trans_in[KEY_LENGTH-1:KEY_LENGTH-BLOCK_SIZE]; 
      5'd10   : trans_key_in = trans_in[BLOCK_SIZE-1:0]; 
      5'd12   : trans_key_in = trans_in[KEY_LENGTH-1:KEY_LENGTH-BLOCK_SIZE]; 
      5'd14   : trans_key_in = trans_in[BLOCK_SIZE-1:0]; 
      5'd16   : trans_key_in = trans_in[KEY_LENGTH-1:KEY_LENGTH-BLOCK_SIZE]; 
      5'd18   : trans_key_in = trans_in[BLOCK_SIZE-1:0]; 
      default : trans_key_in = trans_in[BLOCK_SIZE-1:0]; 
    endcase
  end
end

//The reg_enc_start signal indicates that the encryption process is started
always @ (posedge clk) begin
  if (rst == 1'b1) begin
    reg_enc_start <= 1'b0;
  end
  else begin
    if (block_rdy == 1'b1) begin
      reg_enc_start <= 1'b0;
    end
    else begin
      if (reg_flt_inj == 1'b1 | flt_state) begin
        reg_enc_start <= 1'b0;
      end
      else begin
        if (start == 1'b1) begin
          reg_enc_start <= 1'b1;
        end
      end
    end
  end
end

//Previous current state
always @ (posedge clk) begin
  if (rst == 1'b1) begin
    pre_curr_state <= 6'd0;
  end
  else begin
    if (reg_enc_start == 1'b0) begin
      pre_curr_state <= 6'd0;
    end
    else begin
      if (m2add_rdy == 1'b1 | m2p64add_rdy == 1'b1 | sbpsmc_rdy == 1'b1) begin
        pre_curr_state <= curr_state;
      end
    end
  end
end
assign flt_state = (pre_curr_state != 6'd55 & curr_state - pre_curr_state > 1'd1) ? 1'b1 : 1'b0;

//Block inputs in each state  
always @ (posedge clk) begin
  if (rst == 1'b1) begin
    rnd_num <= 5'd0;
    add_start <= 1'b0;
    xor_start <= 1'b0;
    curr_state <= 6'd0;
    sbpsmc_start <= 1'b0;
    reg_block_rdy <= 1'b0;
    tmv_key <= {BLOCK_SIZE{1'b0}};
    int_key <= {BLOCK_SIZE{1'b0}};
    round_out <= {BLOCK_SIZE{1'b0}};
    add_one_in <= {BLOCK_SIZE{1'b0}};
    add_two_in <= {BLOCK_SIZE{1'b0}};
  end
  else begin
    if (reg_enc_start == 1'b0) begin
      rnd_num <= 5'd0;
      add_start <= 1'b0;
      xor_start <= 1'b0;
      curr_state <= 6'd0;
      sbpsmc_start <= 1'b0;
      reg_block_rdy <= 1'b0;
      tmv_key <= {BLOCK_SIZE{1'b0}};
      int_key <= {BLOCK_SIZE{1'b0}};
      round_out <= {BLOCK_SIZE{1'b0}};
      add_one_in <= {BLOCK_SIZE{1'b0}};
      add_two_in <= {BLOCK_SIZE{1'b0}};
    end
    else begin
      case (curr_state)
        //Intermediate key generattion starts here
        6'd0 : begin
          //SOME OPERATIONS
          xor_start <= add_one_in[0];
          sbpsmc_start <= add_one_in[1];

          //ADD - INTKEY
          add_start <= 1'b1;
          add_one_in <= int_key_in;
          add_two_in <= key_alfa;

          curr_state <= 6'd1;
        end
        6'd1 : begin
          if (m2p64add_rdy == 1'b1) begin
            //SOME OPERATIONS
            add_start <= add_one_in[2];
            xor_start <= add_one_in[3];

            //SPLT - INTKEY
            sbpsmc_start <= 1'b1;
            add_one_in <= m2p64add_out;

            curr_state <= 6'd2;
          end
        end
        6'd2 : begin
          if (sbpsmc_rdy == 1'b1) begin
            //SOME OPERATIONS
            add_start <= add_one_in[4];
            sbpsmc_start <= add_one_in[5];

            //XOR - INTKEY
            xor_start <= 1'b1;
            add_one_in <= key_omega;
            add_two_in <= sbpsmc_out;

            curr_state <= 6'd3;
          end
        end
        6'd3 : begin
          if (m2add_rdy == 1'b1) begin
            //SOME OPERATIONS
            add_start <= add_one_in[6];
            xor_start <= add_one_in[7];

            //SPLT - INTKEY
            sbpsmc_start <= 1'b1;
            add_one_in <= m2add_out;
            
            curr_state <= 6'd4;
          end
        end
        6'd4 : begin
          if (sbpsmc_rdy == 1'b1) begin
            //SOME OPERATIONS
            xor_start <= add_one_in[8];
            sbpsmc_start <= add_one_in[9];

            //ADD - INTKEY
            add_start <= 1'b1;
            add_one_in <= key_alfa;
            add_two_in <= sbpsmc_out;

            curr_state <= 6'd5;
          end
        end
        6'd5 : begin
          if (m2p64add_rdy == 1'b1) begin
            //SOME OPERATIONS
            add_start <= add_one_in[10];
            xor_start <= add_one_in[11];

            //RND - KEY0
            rnd_num <= 5'd0;

            //SPLT - INTKEY
            sbpsmc_start <= 1'b1;
            add_one_in <= m2p64add_out;
            
            curr_state <= 6'd6;
          end
        end
        //Intermediate key generation ends and round 0 key generation starts here
        6'd6 : begin
          if (sbpsmc_rdy == 1'b1) begin
            //SOME OPERATIONS
            xor_start <= add_one_in[12];
            sbpsmc_start <= add_one_in[13];

            int_key <= sbpsmc_out;

            //ADD - KEY0
            add_start <= 1'b1;
            add_one_in <= sbpsmc_out;
            add_two_in <= shft_tmv;

            curr_state <= 6'd7;
          end
        end
        6'd7 : begin
          if (m2p64add_rdy == 1'b1) begin
            //SOME OPERATIONS
            xor_start <= add_one_in[14];
            sbpsmc_start <= add_one_in[15];

            tmv_key <= m2p64add_out;

            //ADD - KEY0
            add_one_in <= m2p64add_out;
            add_two_in <= trans_key_in;

            curr_state <= 6'd8;
          end
        end
        6'd8 : begin
          if (m2p64add_rdy == 1'b1) begin
            //SOME OPERATIONS
            add_start <= add_one_in[16];
            xor_start <= add_one_in[17];

            //SPLT - KEY0
            sbpsmc_start <= 1'b1;
            add_one_in <= m2p64add_out;

            curr_state <= 6'd9;
          end
        end
        6'd9 : begin
          if (sbpsmc_rdy == 1'b1) begin
            //SOME OPERATIONS
            add_start <= add_one_in[18];
            sbpsmc_start <= add_one_in[19];

            //XOR - KEY0
            xor_start <= 1'b1;
            add_one_in <= tmv_key;
            add_two_in <= sbpsmc_out;

            curr_state <= 6'd10;
          end
        end
        6'd10 : begin
          if (m2add_rdy == 1'b1) begin
            //SOME OPERATIONS
            add_start <= add_one_in[20];
            xor_start <= add_one_in[21];

            //SPLT - KEY0
            sbpsmc_start <= 1'b1;
            add_one_in <= m2add_out;

            curr_state <= 6'd11;
          end
        end
        6'd11 : begin
          if (sbpsmc_rdy == 1'b1) begin
            //SOME OPERATIONS
            xor_start <= add_one_in[22];
            sbpsmc_start <= add_one_in[23];

            //ADD - KEY0
            add_start <= 1'b1;
            add_one_in <= tmv_key;
            add_two_in <= sbpsmc_out;

            curr_state <= 6'd12;
          end
        end
        //Round 0 key generation ends here and Round 0-1 operations start here
        6'd12 : begin
          if (m2p64add_rdy == 1'b1) begin
            //SOME OPERATIONS
