//Additions - Duplication
mod2_add_serial64b_fom #(.BLOCK_SIZE(BLOCK_SIZE)) m2a_ins1 (.clk(clk), .rst(rst), .m2add_start(xor_start), .m2add_in_one(add_one_in), .m2add_in_two(add_two_in), .lfsr_in(prng_out_one), .m2add_out(m2add_out_one), .m2add_rdy(m2add_rdy_one));
mod2_add_serial64b_fom #(.BLOCK_SIZE(BLOCK_SIZE)) m2a_ins2 (.clk(clk), .rst(rst), .m2add_start(xor_start), .m2add_in_one(add_two_in), .m2add_in_two(add_one_in), .lfsr_in(prng_out_two), .m2add_out(m2add_out_two), .m2add_rdy(m2add_rdy_two));
mod2p64_add_serial64b_fom #(.BLOCK_SIZE(BLOCK_SIZE)) m2p64a_ins1 (.clk(clk), .rst(rst), .m2p64add_start(add_start), .m2p64add_in_one(add_one_in), .m2p64add_in_two(add_two_in), .lfsr_in(prng_out_one), .m2p64add_out(m2p64add_out_one), .m2p64add_rdy(m2p64add_rdy_one));
mod2p64_add_serial64b_fom #(.BLOCK_SIZE(BLOCK_SIZE)) m2p64a_ins2 (.clk(clk), .rst(rst), .m2p64add_start(add_start), .m2p64add_in_one(add_two_in), .m2p64add_in_two(add_one_in), .lfsr_in(prng_out_two), .m2p64add_out(m2p64add_out_two), .m2p64add_rdy(m2p64add_rdy_two));
//Substitution Permutation Mix-Column - Duplication
sbpsmc_serial64b_fom #(.BLOCK_SIZE(BLOCK_SIZE)) sbpsmc64b_ins1 (.clk(clk), .rst(rst), .sbpsmc_start(sbpsmc_start), .sbpsmc_in(add_one_in), .lfsr_in(prng_out_one), .sbpsmc_out(sbpsmc_out_one), .sbpsmc_rdy(sbpsmc_rdy_one));
sbpsmc_serial64b_fom #(.BLOCK_SIZE(BLOCK_SIZE)) sbpsmc64b_ins2 (.clk(clk), .rst(rst), .sbpsmc_start(sbpsmc_start), .sbpsmc_in(add_one_in), .lfsr_in(prng_out_two), .sbpsmc_out(sbpsmc_out_two), .sbpsmc_rdy(sbpsmc_rdy_two));

//Duplication Comparisons
//Modulo 2 Addition
assign m2add_rdy = m2add_rdy_one & m2add_rdy_two;
always @ (m2add_rdy, m2add_out_one, m2add_out_two) begin
  if (m2add_rdy == 1'b1) begin
    if (m2add_out_one == m2add_out_two) begin
      m2add_out = m2add_out_one;
    end
    else begin
      m2add_out = {BLOCK_SIZE{1'b0}};
    end
  end
  else begin
    m2add_out = m2add_out_one;
  end
end
//Modulo 2^64 Addition
assign m2p64add_rdy = m2p64add_rdy_one & m2p64add_rdy_two;
always @ (m2p64add_rdy, m2p64add_out_one, m2p64add_out_two) begin
  if (m2p64add_rdy == 1'b1) begin
    if (m2p64add_out_one == m2p64add_out_two) begin
      m2p64add_out = m2p64add_out_one;
    end
    else begin
      m2p64add_out = {BLOCK_SIZE{1'b0}};
    end
  end
  else begin
    m2p64add_out = m2p64add_out_one;
  end
end
//SPM
assign sbpsmc_rdy = sbpsmc_rdy_one & sbpsmc_rdy_two;
always @ (sbpsmc_rdy, sbpsmc_out_one, sbpsmc_out_two) begin
  if (sbpsmc_rdy == 1'b1) begin
    if (sbpsmc_out_one == sbpsmc_out_two) begin
      sbpsmc_out = sbpsmc_out_one;
    end
    else begin
      sbpsmc_out = {BLOCK_SIZE{1'b0}};
    end
  end
  else begin
    sbpsmc_out = sbpsmc_out_one;
  end
end
//Fault Injection
assign flt_inj = ((m2add_rdy & m2add_out_one != m2add_out_two) | (m2p64add_rdy & m2p64add_out_one != m2p64add_out_two) | (sbpsmc_rdy & sbpsmc_out_one != sbpsmc_out_two)) ? 1'b1 : 1'b0;
always @ (posedge clk) begin
  if (rst == 1'b1) begin
    reg_flt_inj <= 1'b0;
  end
  else begin
    if (flt_inj == 1'b1) begin
      reg_flt_inj <= 1'b1;
    end
  end
end

//Block Outputs
always @ (posedge clk) begin
  if (rst == 1'b1) begin
    block_rdy <= 1'b0;
    block_out <= {BLOCK_SIZE{1'b0}};
  end
  else begin
    if (reg_enc_start == 1'b0) begin
      block_rdy <= 1'b0;
      block_out <= {BLOCK_SIZE{1'b0}};
    end
    else begin
      if (reg_block_rdy == 1'b1) begin
        block_rdy <= 1'b1;
        block_out <= round_out;
      end
    end
  end
end

endmodule

//KALYNA ENCRYPTION BLOCK - SERIAL - ONE OPERATION IN ONE CLOCK CYCLE 
module kalyna_enc_block_serial_oboc #(parameter BLOCK_SIZE = 128, parameter KEY_LENGTH = 128) (clk, rst, start, block_in, key_in, block_out, block_rdy);

input clk, rst, start;
input [BLOCK_SIZE-1:0] block_in;
input [KEY_LENGTH-1:0] key_in;
output reg [BLOCK_SIZE-1:0] block_out;
output reg block_rdy;

//Local parameters
localparam bs_m8 = BLOCK_SIZE - 8;
localparam bs_d16 = BLOCK_SIZE/16;
localparam the_lr = (BLOCK_SIZE/4+24);
localparam rnd_cnt = (BLOCK_SIZE == KEY_LENGTH && BLOCK_SIZE == 128) ? 5'd10 : (BLOCK_SIZE == KEY_LENGTH && BLOCK_SIZE == 256) ? 5'd14 : (BLOCK_SIZE == KEY_LENGTH && BLOCK_SIZE == 512) ? 5'd18 : (BLOCK_SIZE != KEY_LENGTH && BLOCK_SIZE == 128) ? 5'd14 : 5'd18;

//Variables
reg [4:0] rnd_num;
reg [5:0] curr_state;
reg [KEY_LENGTH-1:0] trans_in;
reg reg_block_rdy, reg_enc_start;
reg [BLOCK_SIZE-1:0] key_alfa, key_omega, add_one_in, add_two_in, int_key, shft_tmv, trans_key_in, tmv_key, round_out;
wire [BLOCK_SIZE-1:0] int_key_in, the_tmv;
wire [7:0] the_const = (BLOCK_SIZE+KEY_LENGTH)/64 + 1;
wire [BLOCK_SIZE-1:0] m2add_out, m2p64add_out, sbpsmc_out;

//Input to the intermediate key transformation
assign int_key_in = {the_const, {bs_m8{1'b0}}};

//Alfa and Omega Keys for the intermediate key transformation
always @ (*) begin
  if (BLOCK_SIZE == KEY_LENGTH) begin
    key_alfa = key_in;
    key_omega = key_in;
  end
  else begin
    key_alfa = key_in[KEY_LENGTH-1:KEY_LENGTH/2];
    key_omega = key_in[KEY_LENGTH/2-1:0];
  end
end

//Generation of the TMV signal and its shifted version
assign the_tmv= {bs_d16{16'h0100}};
always @ (*) begin
  case (rnd_num)
    5'd0    : shft_tmv = the_tmv;
    5'd2    : shft_tmv = {the_tmv[BLOCK_SIZE-2:0],  1'd0};
    5'd4    : shft_tmv = {the_tmv[BLOCK_SIZE-3:0],  2'd0};
    5'd6    : shft_tmv = {the_tmv[BLOCK_SIZE-4:0],  3'd0};
    5'd8    : shft_tmv = {the_tmv[BLOCK_SIZE-5:0],  4'd0};
    5'd10   : shft_tmv = {the_tmv[BLOCK_SIZE-6:0],  5'd0};
    5'd12   : shft_tmv = {the_tmv[BLOCK_SIZE-7:0],  6'd0};
    5'd14   : shft_tmv = {the_tmv[BLOCK_SIZE-8:0],  7'd0};
    5'd16   : shft_tmv = {the_tmv[BLOCK_SIZE-9:0],  7'd0, 1'b1};
    5'd18   : shft_tmv = {the_tmv[BLOCK_SIZE-10:0], 7'd0, 1'b1, 1'b0}; //Last two lines are due to the conflict between rotate and shift
    default : shft_tmv = the_tmv;
  endcase
end

//Generation of the input to the transformations
always @ (*) begin
  if (BLOCK_SIZE == KEY_LENGTH) begin
    if (BLOCK_SIZE == 128) begin
      case (rnd_num) 
        5'd0    : trans_in = key_in;
        5'd2    : trans_in = {key_in[63:0], key_in[127:64]};
        5'd4    : trans_in = key_in;
        5'd6    : trans_in = {key_in[63:0], key_in[127:64]};
        5'd8    : trans_in = key_in;
        5'd10   : trans_in = {key_in[63:0], key_in[127:64]};
        default : trans_in = key_in;
      endcase
    end
    else if (BLOCK_SIZE == 256) begin
      case (rnd_num) 
        5'd0    : trans_in = key_in;
        5'd2    : trans_in = {key_in[191:0], key_in[255:192]};
        5'd4    : trans_in = {key_in[127:0], key_in[255:128]};
        5'd6    : trans_in = {key_in[63:0],  key_in[255:64]};
        5'd8    : trans_in = key_in;
        5'd10   : trans_in = {key_in[191:0], key_in[255:192]};
        5'd12   : trans_in = {key_in[127:0], key_in[255:128]};
        5'd14   : trans_in = {key_in[63:0],  key_in[255:64]};
        default : trans_in = key_in;
      endcase
    end
    else begin
      case (rnd_num) 
        5'd0    : trans_in = key_in;
        5'd2    : trans_in = {key_in[447:0], key_in[511:448]};
        5'd4    : trans_in = {key_in[383:0], key_in[511:384]};
        5'd6    : trans_in = {key_in[319:0], key_in[511:320]};
        5'd8    : trans_in = {key_in[255:0], key_in[511:256]};
        5'd10   : trans_in = {key_in[191:0], key_in[511:192]};
        5'd12   : trans_in = {key_in[127:0], key_in[511:128]};
        5'd14   : trans_in = {key_in[63:0],  key_in[511:64]};
        5'd16   : trans_in = key_in;
        5'd18   : trans_in = {key_in[447:0], key_in[511:448]};
        default : trans_in = key_in;
      endcase
    end
  end
  else begin
    if (BLOCK_SIZE == 128) begin
      case (rnd_num) 
        5'd0    : trans_in = key_in;
        5'd2    : trans_in = key_in;
        5'd4    : trans_in = {key_in[191:0], key_in[255:192]};
        5'd6    : trans_in = {key_in[191:0], key_in[255:192]};
        5'd8    : trans_in = {key_in[127:0], key_in[255:128]};
        5'd10   : trans_in = {key_in[127:0], key_in[255:128]};
        5'd12   : trans_in = {key_in[63:0],  key_in[255:64]};
        5'd14   : trans_in = {key_in[63:0],  key_in[255:64]};
        default : trans_in = key_in;
      endcase
    end
    else begin
      case (rnd_num) 
        5'd0    : trans_in = key_in;
        5'd2    : trans_in = key_in;
        5'd4    : trans_in = {key_in[447:0], key_in[511:448]};
        5'd6    : trans_in = {key_in[447:0], key_in[511:448]};
        5'd8    : trans_in = {key_in[383:0], key_in[511:384]};
        5'd10   : trans_in = {key_in[383:0], key_in[511:384]};
        5'd12   : trans_in = {key_in[319:0], key_in[511:320]};
        5'd14   : trans_in = {key_in[319:0], key_in[511:320]};
        5'd16   : trans_in = {key_in[255:0], key_in[511:256]};
        5'd18   : trans_in = {key_in[255:0], key_in[511:256]};
        default : trans_in = key_in;
      endcase
    end
  end
end
always @ (*) begin
  if (BLOCK_SIZE == KEY_LENGTH) begin
    trans_key_in = trans_in;
  end
  else begin
    case (rnd_num) 
      5'd0    : trans_key_in = trans_in[KEY_LENGTH-1:KEY_LENGTH-BLOCK_SIZE];
      5'd2    : trans_key_in = trans_in[BLOCK_SIZE-1:0];
      5'd4    : trans_key_in = trans_in[KEY_LENGTH-1:KEY_LENGTH-BLOCK_SIZE]; 
      5'd6    : trans_key_in = trans_in[BLOCK_SIZE-1:0]; 
      5'd8    : trans_key_in = trans_in[KEY_LENGTH-1:KEY_LENGTH-BLOCK_SIZE]; 
      5'd10   : trans_key_in = trans_in[BLOCK_SIZE-1:0]; 
      5'd12   : trans_key_in = trans_in[KEY_LENGTH-1:KEY_LENGTH-BLOCK_SIZE]; 
      5'd14   : trans_key_in = trans_in[BLOCK_SIZE-1:0]; 
      5'd16   : trans_key_in = trans_in[KEY_LENGTH-1:KEY_LENGTH-BLOCK_SIZE]; 
      5'd18   : trans_key_in = trans_in[BLOCK_SIZE-1:0]; 
      default : trans_key_in = trans_in[BLOCK_SIZE-1:0]; 
    endcase
  end
end

//The reg_enc_start signal indicates that the encryption process is started
always @ (posedge clk) begin
  if (rst == 1'b1) begin
    reg_enc_start <= 1'b0;
  end
  else begin
    if (block_rdy == 1'b1) begin
      reg_enc_start <= 1'b0;
    end
    else begin
      if (start == 1'b1) begin
        reg_enc_start <= 1'b1;
      end
    end
  end
end

//Block inputs in each state  
always @ (posedge clk) begin
  if (rst == 1'b1) begin
    rnd_num <= 5'd0;
    curr_state <= 6'd0;
    reg_block_rdy <= 1'b0;
    tmv_key <= {BLOCK_SIZE{1'b0}};
    int_key <= {BLOCK_SIZE{1'b0}};
    round_out <= {BLOCK_SIZE{1'b0}};
    add_one_in <= {BLOCK_SIZE{1'b0}};
    add_two_in <= {BLOCK_SIZE{1'b0}};
  end
  else begin
    if (reg_enc_start == 1'b0) begin
      rnd_num <= 5'd0;
      curr_state <= 6'd0;
      reg_block_rdy <= 1'b0;
      tmv_key <= {BLOCK_SIZE{1'b0}};
      int_key <= {BLOCK_SIZE{1'b0}};
      round_out <= {BLOCK_SIZE{1'b0}};
      add_one_in <= {BLOCK_SIZE{1'b0}};
      add_two_in <= {BLOCK_SIZE{1'b0}};
    end
    else begin
      case (curr_state)
        //Intermediate key generattion starts here
        6'd0 : begin
          //ADD - INTKEY
          add_one_in <= int_key_in;
          add_two_in <= key_alfa;

          curr_state <= 6'd1;
        end
        6'd1 : begin
          //SPLT - INTKEY
          add_one_in <= m2p64add_out;

          curr_state <= 6'd2;
        end
        6'd2 : begin
          //XOR - INTKEY
          add_one_in <= key_omega;
          add_two_in <= sbpsmc_out;

          curr_state <= 6'd3;
        end
        6'd3 : begin
          //SPLT - INTKEY
          add_one_in <= m2add_out;
          
          curr_state <= 6'd4;
        end
        6'd4 : begin
          //ADD - INTKEY
          add_one_in <= key_alfa;
          add_two_in <= sbpsmc_out;

          curr_state <= 6'd5;
        end
        6'd5 : begin
          //RND - KEY0
          rnd_num <= 5'd0;

          //SPLT - INTKEY
          add_one_in <= m2p64add_out;
          
          curr_state <= 6'd6;
        end
        //Intermediate key generation ends and round 0 key generation starts here
        6'd6 : begin
          int_key <= sbpsmc_out;

          //ADD - KEY0
          add_one_in <= sbpsmc_out;
          add_two_in <= shft_tmv;

          curr_state <= 6'd7;
        end
        6'd7 : begin
          tmv_key <= m2p64add_out;

          //ADD - KEY0
          add_one_in <= m2p64add_out;
          add_two_in <= trans_key_in;

          curr_state <= 6'd8;
        end
        6'd8 : begin
          //SPLT - KEY0
          add_one_in <= m2p64add_out;

          curr_state <= 6'd9;
        end
        6'd9 : begin
          //XOR - KEY0
          add_one_in <= tmv_key;
          add_two_in <= sbpsmc_out;

          curr_state <= 6'd10;
        end
        6'd10 : begin
          //SPLT - KEY0
          add_one_in <= m2add_out;

          curr_state <= 6'd11;
        end
        6'd11 : begin
          //ADD - KEY0
          add_one_in <= tmv_key;
          add_two_in <= sbpsmc_out;

          curr_state <= 6'd12;
        end
        //Round 0 key generation ends here and Round 0-1 operations start here
        6'd12 : begin
          tmv_key <= m2p64add_out;
          //ADD - RND0
          add_one_in <= m2p64add_out;
          add_two_in <= block_in;

          curr_state <= 6'd13;
        end
        6'd13 : begin
          //SPLT - RND1
          add_one_in <= m2p64add_out;

          curr_state <= 6'd14;
        end
        6'd14 : begin
          //RND - KEY2
          rnd_num <= rnd_num + 5'd2;
          //XOR - RND1
          add_one_in <= sbpsmc_out;
          add_two_in <= {tmv_key[BLOCK_SIZE-1-the_lr:0], tmv_key[BLOCK_SIZE-1:BLOCK_SIZE-the_lr]};

          curr_state <= 6'd15;
        end
        //Round 2 key generation starts here
        6'd15 : begin
          round_out <= m2add_out;
          //ADD - KEY2
          add_one_in <= int_key;
          add_two_in <= shft_tmv;

          curr_state <= 6'd16;
        end
        6'd16 : begin
          tmv_key <= m2p64add_out;

          //ADD - KEY2
          add_one_in <= m2p64add_out;
          add_two_in <= trans_key_in;

          curr_state <= 6'd17;
        end
        6'd17 : begin
          //SPLT - KEY2
          add_one_in <= m2p64add_out;

          curr_state <= 6'd18;
        end
        6'd18 : begin
          //XOR - KEY2
          add_one_in <= tmv_key;
          add_two_in <= sbpsmc_out;

          curr_state <= 6'd19;
        end
        6'd19 : begin
          //SPLT - KEY2
          add_one_in <= m2add_out;

          curr_state <= 6'd20;
        end
        6'd20 : begin
          //ADD - KEY2
          add_one_in <= tmv_key;
          add_two_in <= sbpsmc_out;

          curr_state <= 6'd21;
        end
        //Round 2 key generation ends here and Round 2-3 operations start here
        6'd21 : begin
          tmv_key <= m2p64add_out;

          //SPLT - RND2
          add_one_in <= round_out;

          curr_state <= 6'd22;
        end
        6'd22 : begin
          //XOR - RND2
          add_one_in <= sbpsmc_out;
          add_two_in <= tmv_key;

          curr_state <= 6'd23;
        end
        6'd23 : begin
          //SPLT -RND3
          add_one_in <= m2add_out;

          curr_state <= 6'd24;
        end
        6'd24 : begin
          //RND - KEY4
          rnd_num <= rnd_num + 5'd2;

          //XOR - RND3
          add_one_in <= sbpsmc_out;
          add_two_in <= {tmv_key[BLOCK_SIZE-1-the_lr:0], tmv_key[BLOCK_SIZE-1:BLOCK_SIZE-the_lr]};

          curr_state <= 6'd25;
        end
        //Round 2-3 operations end here and Round 4 key generation starts here
        6'd25 : begin
          round_out <= m2add_out;
          //ADD - KEY4
          add_one_in <= int_key;
          add_two_in <= shft_tmv;

          curr_state <= 6'd26;
        end
        6'd26 : begin
          tmv_key <= m2p64add_out;

          //ADD - KEY4
          add_one_in <= m2p64add_out;
          add_two_in <= trans_key_in;

          curr_state <= 6'd27;
        end
        6'd27 : begin
          //SPLT - KEY4
          add_one_in <= m2p64add_out;

          curr_state <= 6'd28;
        end
        6'd28 : begin
          //XOR - KEY4
          add_one_in <= tmv_key;
          add_two_in <= sbpsmc_out;

          curr_state <= 6'd29;
        end
        6'd29 : begin
          //SPLT - KEY4
          add_one_in <= m2add_out;

          curr_state <= 6'd30;
        end
        6'd30 : begin
          //ADD - KEY4
          add_one_in <= tmv_key;
          add_two_in <= sbpsmc_out;

          curr_state <= 6'd31;
        end
        //Round 4 key generation ends here and Round 4-5 operations start here
        6'd31 : begin
          tmv_key <= m2p64add_out;

          //SPLT - RND4
          add_one_in <= round_out;

          curr_state <= 6'd32;
        end
        6'd32 : begin
          //XOR - RND4
          add_one_in <= sbpsmc_out;
          add_two_in <= tmv_key;

          curr_state <= 6'd33;
        end
        6'd33 : begin
          //SPLT -RND5
          add_one_in <= m2add_out;

          curr_state <= 6'd34;
        end
        6'd34 : begin
          //RND - KEY6
          rnd_num <= rnd_num + 5'd2;

          //XOR - RND5
          add_one_in <= sbpsmc_out;
          add_two_in <= {tmv_key[BLOCK_SIZE-1-the_lr:0], tmv_key[BLOCK_SIZE-1:BLOCK_SIZE-the_lr]};

          curr_state <= 6'd35;
        end
        //Round 4-5 operations end here and Round 6 key generation starts here
        6'd35 : begin
          round_out <= m2add_out;
          //ADD - KEY6
          add_one_in <= int_key;
          add_two_in <= shft_tmv;

          curr_state <= 6'd36;
        end
        6'd36 : begin
          tmv_key <= m2p64add_out;

          //ADD - KEY6
          add_one_in <= m2p64add_out;
          add_two_in <= trans_key_in;

          curr_state <= 6'd37;
        end
        6'd37 : begin
          //SPLT - KEY6
          add_one_in <= m2p64add_out;

          curr_state <= 6'd38;
        end
        6'd38 : begin
          //XOR - KEY6
          add_one_in <= tmv_key;
          add_two_in <= sbpsmc_out;

          curr_state <= 6'd39;
        end
        6'd39 : begin
          //SPLT - KEY6
          add_one_in <= m2add_out;

          curr_state <= 6'd40;
        end
        6'd40 : begin
          //ADD - KEY6
          add_one_in <= tmv_key;
          add_two_in <= sbpsmc_out;

          curr_state <= 6'd41;
        end
        //Round 6 key generation ends here and Round 6-7 operations start here
        6'd41 : begin
          tmv_key <= m2p64add_out;

          //SPLT - RND6
          add_one_in <= round_out;

          curr_state <= 6'd42;
        end
        6'd42 : begin
          //XOR - RND6
          add_one_in <= sbpsmc_out;
          add_two_in <= tmv_key;

          curr_state <= 6'd43;
        end
        6'd43 : begin
          //SPLT -RND7
          add_one_in <= m2add_out;

          curr_state <= 6'd44;
        end
        6'd44 : begin
          //RND - KEY8
          rnd_num <= rnd_num + 5'd2;

          //XOR - RND7
          add_one_in <= sbpsmc_out;
          add_two_in <= {tmv_key[BLOCK_SIZE-1-the_lr:0], tmv_key[BLOCK_SIZE-1:BLOCK_SIZE-the_lr]};

          curr_state <= 6'd45;
        end
        //Round 6-7 operations end here and Round 8 key generation starts here
        6'd45 : begin
          round_out <= m2add_out;
          //ADD - KEY8
          add_one_in <= int_key;
          add_two_in <= shft_tmv;

          curr_state <= 6'd46;
        end
        6'd46 : begin
          tmv_key <= m2p64add_out;

          //ADD - KEY8
          add_one_in <= m2p64add_out;
          add_two_in <= trans_key_in;

          curr_state <= 6'd47;
        end
        6'd47 : begin
          //SPLT - KEY8
          add_one_in <= m2p64add_out;

          curr_state <= 6'd48;
        end
        6'd48 : begin
          //XOR - KEY8
          add_one_in <= tmv_key;
          add_two_in <= sbpsmc_out;

          curr_state <= 6'd49;
        end
        6'd49 : begin
          //SPLT - KEY8
          add_one_in <= m2add_out;

          curr_state <= 6'd50;
        end
        6'd50 : begin
          //ADD - KEY8
          add_one_in <= tmv_key;
          add_two_in <= sbpsmc_out;

          curr_state <= 6'd51;
        end
        //Round 8 key generation ends here and Round 8-9 operations start here
        6'd51 : begin
          tmv_key <= m2p64add_out;

          //SPLT - RND8
          add_one_in <= round_out;

          curr_state <= 6'd52;
        end
        6'd52 : begin
          //XOR - RND8
          add_one_in <= sbpsmc_out;
          add_two_in <= tmv_key;

          curr_state <= 6'd53;
        end
        6'd53 : begin
          //SPLT -RND9
          add_one_in <= m2add_out;

          curr_state <= 6'd54;
        end
        6'd54 : begin
          //RND - KEY10
          rnd_num <= rnd_num + 5'd2;

          //XOR - RND9
          add_one_in <= sbpsmc_out;
          add_two_in <= {tmv_key[BLOCK_SIZE-1-the_lr:0], tmv_key[BLOCK_SIZE-1:BLOCK_SIZE-the_lr]};

          curr_state <= 6'd55;
        end
        //Round 8-9 operations end here and Round 10 key generation starts here
        6'd55 : begin
          round_out <= m2add_out;
          //ADD - KEY10
          add_one_in <= int_key;
          add_two_in <= shft_tmv;

          if (rnd_cnt == 5'd10) begin
            curr_state <= 6'd56;
          end
          else if (rnd_cnt == 5'd14) begin
            if (rnd_num  == 5'd14) begin
              curr_state <= 6'd56;
            end
            else begin
              curr_state <= 6'd36;
            end
          end
          else begin
            if (rnd_num  == 5'd18) begin
              curr_state <= 6'd56;
            end
            else begin
              curr_state <= 6'd16;
            end
          end
        end
        6'd56 : begin
          tmv_key <= m2p64add_out;

          //ADD - KEY10
          add_one_in <= m2p64add_out;
          add_two_in <= trans_key_in;

          curr_state <= 6'd57;
        end
        6'd57 : begin
          //SPLT - KEY10
          add_one_in <= m2p64add_out;

          curr_state <= 6'd58;
        end
        6'd58 : begin
          //XOR - KEY10
          add_one_in <= tmv_key;
          add_two_in <= sbpsmc_out;

          curr_state <= 6'd59;
        end
        6'd59 : begin
          //SPLT - KEY10
          add_one_in <= m2add_out;

          curr_state <= 6'd60;
        end
        6'd60 : begin
          //ADD - KEY10
          add_one_in <= tmv_key;
          add_two_in <= sbpsmc_out;

          curr_state <= 6'd61;
        end
        //Round 10 key generation ends here and Round 10 operation starts here
        6'd61 : begin
          tmv_key <= m2p64add_out;

          //SPLT - RND10
          add_one_in <= round_out;

          curr_state <= 6'd62;
        end
        6'd62 : begin
          //ADD - RND10
          add_one_in <= sbpsmc_out;
          add_two_in <= tmv_key;

          curr_state <= 6'd63;
        end
        6'd63 : begin
          round_out <= m2p64add_out;
          reg_block_rdy <= 1'b1;

          curr_state <= 6'd0;
        end
        default : begin
          rnd_num <= 5'd0;
          curr_state <= 6'd0;
          reg_block_rdy <= 1'b0;
          tmv_key <= {BLOCK_SIZE{1'b0}};
          int_key <= {BLOCK_SIZE{1'b0}};
          round_out <= {BLOCK_SIZE{1'b0}};
          add_one_in <= {BLOCK_SIZE{1'b0}};
          add_two_in <= {BLOCK_SIZE{1'b0}};
        end
      endcase
    end
  end
end

//Additions
mod2_add #(.BLOCK_SIZE(BLOCK_SIZE)) m2a_ins (.m2add_in_one(add_one_in), .m2add_in_two(add_two_in), .m2add_out(m2add_out));
mod2p64_add #(.BLOCK_SIZE(BLOCK_SIZE)) m2p64a_ins (.m2p64add_in_one(add_one_in), .m2p64add_in_two(add_two_in), .m2p64add_out(m2p64add_out));
//Substitution Permutation Mix-Column
sbpsmc #(.BLOCK_SIZE(BLOCK_SIZE)) sbpsmc64b_ins (.sbpsmc_in(add_one_in), .sbpsmc_out(sbpsmc_out));

//Block Outputs
always @ (posedge clk) begin
  if (rst == 1'b1) begin
    block_rdy <= 1'b0;
    block_out <= {BLOCK_SIZE{1'b0}};
  end
  else begin
    if (reg_enc_start == 1'b0) begin
      block_rdy <= 1'b0;
      block_out <= {BLOCK_SIZE{1'b0}};
    end
    else begin
      if (reg_block_rdy == 1'b1) begin
        block_rdy <= 1'b1;
        block_out <= round_out;
      end
    end
  end
end

endmodule

//KALYNA ENCRYPTION BLOCK - SERIAL - ONE 64-bit OPERATION IN ONE CLOCK CYCLE 
module kalyna_enc_block_serial64b_oboc #(parameter BLOCK_SIZE = 128, parameter KEY_LENGTH = 128) (clk, rst, start, block_in, key_in, block_out, block_rdy);

input clk, rst, start;
input [BLOCK_SIZE-1:0] block_in;
input [KEY_LENGTH-1:0] key_in;
output reg [BLOCK_SIZE-1:0] block_out;
output reg block_rdy;

//Local parameters
localparam bs_m8 = BLOCK_SIZE - 8;
localparam bs_d16 = BLOCK_SIZE/16;
localparam the_lr = (BLOCK_SIZE/4+24);
localparam rnd_cnt = (BLOCK_SIZE == KEY_LENGTH && BLOCK_SIZE == 128) ? 5'd10 : (BLOCK_SIZE == KEY_LENGTH && BLOCK_SIZE == 256) ? 5'd14 : (BLOCK_SIZE == KEY_LENGTH && BLOCK_SIZE == 512) ? 5'd18 : (BLOCK_SIZE != KEY_LENGTH && BLOCK_SIZE == 128) ? 5'd14 : 5'd18;

//Variables
reg [4:0] rnd_num;
reg [5:0] curr_state;
reg [KEY_LENGTH-1:0] trans_in;
reg xor_start, add_start, sbpsmc_start, reg_block_rdy, reg_enc_start;
reg [BLOCK_SIZE-1:0] key_alfa, key_omega, add_one_in, add_two_in, int_key, shft_tmv, trans_key_in, tmv_key, round_out;
wire m2add_rdy, m2p64add_rdy, sbpsmc_rdy;
wire [BLOCK_SIZE-1:0] int_key_in, the_tmv;
wire [7:0] the_const = (BLOCK_SIZE+KEY_LENGTH)/64 + 1;
wire [BLOCK_SIZE-1:0] m2add_out, m2p64add_out, sbpsmc_out;

//Input to the intermediate key transformation
assign int_key_in = {the_const, {bs_m8{1'b0}}};

//Alfa and Omega Keys for the intermediate key transformation
always @ (*) begin
  if (BLOCK_SIZE == KEY_LENGTH) begin
    key_alfa = key_in;
    key_omega = key_in;
  end
  else begin
    key_alfa = key_in[KEY_LENGTH-1:KEY_LENGTH/2];
    key_omega = key_in[KEY_LENGTH/2-1:0];
  end
end

//Generation of the TMV signal and its shifted version
assign the_tmv= {bs_d16{16'h0100}};
always @ (*) begin
  case (rnd_num)
    5'd0    : shft_tmv = the_tmv;
    5'd2    : shft_tmv = {the_tmv[BLOCK_SIZE-2:0],  1'd0};
    5'd4    : shft_tmv = {the_tmv[BLOCK_SIZE-3:0],  2'd0};
    5'd6    : shft_tmv = {the_tmv[BLOCK_SIZE-4:0],  3'd0};
    5'd8    : shft_tmv = {the_tmv[BLOCK_SIZE-5:0],  4'd0};
    5'd10   : shft_tmv = {the_tmv[BLOCK_SIZE-6:0],  5'd0};
    5'd12   : shft_tmv = {the_tmv[BLOCK_SIZE-7:0],  6'd0};
    5'd14   : shft_tmv = {the_tmv[BLOCK_SIZE-8:0],  7'd0};
    5'd16   : shft_tmv = {the_tmv[BLOCK_SIZE-9:0],  7'd0, 1'b1};
    5'd18   : shft_tmv = {the_tmv[BLOCK_SIZE-10:0], 7'd0, 1'b1, 1'b0}; //Last two lines are due to the conflict between rotate and shift
    default : shft_tmv = the_tmv;
  endcase
end

//Generation of the input to the transformations
always @ (*) begin
  if (BLOCK_SIZE == KEY_LENGTH) begin
    if (BLOCK_SIZE == 128) begin
      case (rnd_num) 
        5'd0    : trans_in = key_in;
        5'd2    : trans_in = {key_in[63:0], key_in[127:64]};
        5'd4    : trans_in = key_in;
        5'd6    : trans_in = {key_in[63:0], key_in[127:64]};
        5'd8    : trans_in = key_in;
        5'd10   : trans_in = {key_in[63:0], key_in[127:64]};
        default : trans_in = key_in;
      endcase
    end
    else if (BLOCK_SIZE == 256) begin
      case (rnd_num) 
        5'd0    : trans_in = key_in;
        5'd2    : trans_in = {key_in[191:0], key_in[255:192]};
        5'd4    : trans_in = {key_in[127:0], key_in[255:128]};
        5'd6    : trans_in = {key_in[63:0],  key_in[255:64]};
        5'd8    : trans_in = key_in;
        5'd10   : trans_in = {key_in[191:0], key_in[255:192]};
        5'd12   : trans_in = {key_in[127:0], key_in[255:128]};
        5'd14   : trans_in = {key_in[63:0],  key_in[255:64]};
        default : trans_in = key_in;
      endcase
    end
    else begin
      case (rnd_num) 
        5'd0    : trans_in = key_in;
        5'd2    : trans_in = {key_in[447:0], key_in[511:448]};
        5'd4    : trans_in = {key_in[383:0], key_in[511:384]};
        5'd6    : trans_in = {key_in[319:0], key_in[511:320]};
        5'd8    : trans_in = {key_in[255:0], key_in[511:256]};
        5'd10   : trans_in = {key_in[191:0], key_in[511:192]};
        5'd12   : trans_in = {key_in[127:0], key_in[511:128]};
        5'd14   : trans_in = {key_in[63:0],  key_in[511:64]};
        5'd16   : trans_in = key_in;
        5'd18   : trans_in = {key_in[447:0], key_in[511:448]};
        default : trans_in = key_in;
      endcase
    end
  end
  else begin
    if (BLOCK_SIZE == 128) begin
      case (rnd_num) 
        5'd0    : trans_in = key_in;
        5'd2    : trans_in = key_in;
        5'd4    : trans_in = {key_in[191:0], key_in[255:192]};
        5'd6    : trans_in = {key_in[191:0], key_in[255:192]};
        5'd8    : trans_in = {key_in[127:0], key_in[255:128]};
        5'd10   : trans_in = {key_in[127:0], key_in[255:128]};
        5'd12   : trans_in = {key_in[63:0],  key_in[255:64]};
        5'd14   : trans_in = {key_in[63:0],  key_in[255:64]};
        default : trans_in = key_in;
      endcase
    end
    else begin
      case (rnd_num) 
        5'd0    : trans_in = key_in;
        5'd2    : trans_in = key_in;
        5'd4    : trans_in = {key_in[447:0], key_in[511:448]};
        5'd6    : trans_in = {key_in[447:0], key_in[511:448]};
        5'd8    : trans_in = {key_in[383:0], key_in[511:384]};
        5'd10   : trans_in = {key_in[383:0], key_in[511:384]};
        5'd12   : trans_in = {key_in[319:0], key_in[511:320]};
        5'd14   : trans_in = {key_in[319:0], key_in[511:320]};
        5'd16   : trans_in = {key_in[255:0], key_in[511:256]};
        5'd18   : trans_in = {key_in[255:0], key_in[511:256]};
        default : trans_in = key_in;
      endcase
    end
  end
end
always @ (*) begin
  if (BLOCK_SIZE == KEY_LENGTH) begin
    trans_key_in = trans_in;
  end
  else begin
    case (rnd_num) 
      5'd0    : trans_key_in = trans_in[KEY_LENGTH-1:KEY_LENGTH-BLOCK_SIZE];
      5'd2    : trans_key_in = trans_in[BLOCK_SIZE-1:0];
      5'd4    : trans_key_in = trans_in[KEY_LENGTH-1:KEY_LENGTH-BLOCK_SIZE]; 
      5'd6    : trans_key_in = trans_in[BLOCK_SIZE-1:0]; 
      5'd8    : trans_key_in = trans_in[KEY_LENGTH-1:KEY_LENGTH-BLOCK_SIZE]; 
      5'd10   : trans_key_in = trans_in[BLOCK_SIZE-1:0]; 
      5'd12   : trans_key_in = trans_in[KEY_LENGTH-1:KEY_LENGTH-BLOCK_SIZE]; 
      5'd14   : trans_key_in = trans_in[BLOCK_SIZE-1:0]; 
      5'd16   : trans_key_in = trans_in[KEY_LENGTH-1:KEY_LENGTH-BLOCK_SIZE]; 
      5'd18   : trans_key_in = trans_in[BLOCK_SIZE-1:0]; 
      default : trans_key_in = trans_in[BLOCK_SIZE-1:0]; 
    endcase
  end
end

//The reg_enc_start signal indicates that the encryption process is started
always @ (posedge clk) begin
  if (rst == 1'b1) begin
    reg_enc_start <= 1'b0;
  end
  else begin
    if (block_rdy == 1'b1) begin
      reg_enc_start <= 1'b0;
    end
    else begin
      if (start == 1'b1) begin
        reg_enc_start <= 1'b1;
      end
    end
  end
end

//Block inputs in each state  
always @ (posedge clk) begin
  if (rst == 1'b1) begin
    rnd_num <= 5'd0;
    add_start <= 1'b0;
    xor_start <= 1'b0;
    curr_state <= 6'd0;
    sbpsmc_start <= 1'b0;
    reg_block_rdy <= 1'b0;
    tmv_key <= {BLOCK_SIZE{1'b0}};
    int_key <= {BLOCK_SIZE{1'b0}};
    round_out <= {BLOCK_SIZE{1'b0}};
    add_one_in <= {BLOCK_SIZE{1'b0}};
    add_two_in <= {BLOCK_SIZE{1'b0}};
  end
  else begin
    if (reg_enc_start == 1'b0) begin
      rnd_num <= 5'd0;
      add_start <= 1'b0;
      xor_start <= 1'b0;
      curr_state <= 6'd0;
      sbpsmc_start <= 1'b0;
      reg_block_rdy <= 1'b0;
      tmv_key <= {BLOCK_SIZE{1'b0}};
      int_key <= {BLOCK_SIZE{1'b0}};
      round_out <= {BLOCK_SIZE{1'b0}};
      add_one_in <= {BLOCK_SIZE{1'b0}};
      add_two_in <= {BLOCK_SIZE{1'b0}};
    end
    else begin
      case (curr_state)
        //Intermediate key generattion starts here
        6'd0 : begin
          //ADD - INTKEY
          add_start <= 1'b1;
          add_one_in <= int_key_in;
          add_two_in <= key_alfa;

          curr_state <= 6'd1;
        end
        6'd1 : begin
          if (m2p64add_rdy == 1'b1) begin
            //ADD - INTKEY
            add_start <= 1'b0;
            //SPLT - INTKEY
            sbpsmc_start <= 1'b1;
            add_one_in <= m2p64add_out;

            curr_state <= 6'd2;
          end
        end
        6'd2 : begin
          if (sbpsmc_rdy == 1'b1) begin
            //SPLT - INTKEY
            sbpsmc_start <= 1'b0;
            //XOR - INTKEY
            xor_start <= 1'b1;
            add_one_in <= key_omega;
            add_two_in <= sbpsmc_out;

            curr_state <= 6'd3;
          end
        end
        6'd3 : begin
          if (m2add_rdy == 1'b1) begin
            //XOR - INTKEY
            xor_start <= 1'b0;
            //SPLT - INTKEY
            sbpsmc_start <= 1'b1;
            add_one_in <= m2add_out;
            
            curr_state <= 6'd4;
          end
        end
        6'd4 : begin
          if (sbpsmc_rdy == 1'b1) begin
            //SPLT - INTKEY
            sbpsmc_start <= 1'b0;
            //ADD - INTKEY
            add_start <= 1'b1;
            add_one_in <= key_alfa;
            add_two_in <= sbpsmc_out;

            curr_state <= 6'd5;
          end
        end
        6'd5 : begin
          if (m2p64add_rdy == 1'b1) begin
            //RND - KEY0
            rnd_num <= 5'd0;

            //ADD - INTKEY
            add_start <= 1'b0;
            //SPLT - INTKEY
            sbpsmc_start <= 1'b1;
            add_one_in <= m2p64add_out;
            
            curr_state <= 6'd6;
          end
        end
        //Intermediate key generation ends and round 0 key generation starts here
        6'd6 : begin
          if (sbpsmc_rdy == 1'b1) begin
            int_key <= sbpsmc_out;

            //SPLT - KEY0
            sbpsmc_start <= 1'b0;
            //ADD - KEY0
            add_start <= 1'b1;
            add_one_in <= sbpsmc_out;
            add_two_in <= shft_tmv;

            curr_state <= 6'd7;
          end
        end
        6'd7 : begin
          if (m2p64add_rdy == 1'b1) begin
            tmv_key <= m2p64add_out;

            //ADD - KEY0
            add_one_in <= m2p64add_out;
            add_two_in <= trans_key_in;

            curr_state <= 6'd8;
          end
        end
        6'd8 : begin
          if (m2p64add_rdy == 1'b1) begin
            //ADD - KEY0
            add_start <= 1'b0;
            //SPLT - KEY0
            sbpsmc_start <= 1'b1;
            add_one_in <= m2p64add_out;

            curr_state <= 6'd9;
          end
        end
        6'd9 : begin
          if (sbpsmc_rdy == 1'b1) begin
            //SPLT - KEY0
            sbpsmc_start <= 1'b0;
            //XOR - KEY0
            xor_start <= 1'b1;
            add_one_in <= tmv_key;
            add_two_in <= sbpsmc_out;

            curr_state <= 6'd10;
          end
        end
        6'd10 : begin
          if (m2add_rdy == 1'b1) begin
            //XOR - KEY0
            xor_start <= 1'b0;
            //SPLT - KEY0
            sbpsmc_start <= 1'b1;
            add_one_in <= m2add_out;

            curr_state <= 6'd11;
          end
        end
        6'd11 : begin
          if (sbpsmc_rdy == 1'b1) begin
            //SPLT - KEY0
            sbpsmc_start <= 1'b0;
            //ADD - KEY0
            add_start <= 1'b1;
            add_one_in <= tmv_key;
            add_two_in <= sbpsmc_out;

            curr_state <= 6'd12;
          end
        end
        //Round 0 key generation ends here and Round 0-1 operations start here
        6'd12 : begin
          if (m2p64add_rdy == 1'b1) begin
            tmv_key <= m2p64add_out;
            //ADD - RND0
            add_one_in <= m2p64add_out;
            add_two_in <= block_in;

            curr_state <= 6'd13;
          end
        end
        6'd13 : begin
          if (m2p64add_rdy == 1'b1) begin
            //ADD - RND0
            add_start <= 1'b0;
            //SPLT - RND1
            sbpsmc_start <= 1'b1;
            add_one_in <= m2p64add_out;

            curr_state <= 6'd14;
          end
        end
        6'd14 : begin
          if (sbpsmc_rdy == 1'b1) begin
            //RND - KEY2
            rnd_num <= rnd_num + 5'd2;
            //SPLT - RND1
            sbpsmc_start <= 1'b0;
            //XOR - RND1
            xor_start <= 1'b1;
            add_one_in <= sbpsmc_out;
            add_two_in <= {tmv_key[BLOCK_SIZE-1-the_lr:0], tmv_key[BLOCK_SIZE-1:BLOCK_SIZE-the_lr]};

            curr_state <= 6'd15;
          end
        end
        //Round 2 key generation starts here
        6'd15 : begin
          if (m2add_rdy == 1'b1) begin
            round_out <= m2add_out;
            //XOR - RND1
            xor_start <= 1'b0;
            //ADD - KEY2
            add_start <= 1'b1;
            add_one_in <= int_key;
            add_two_in <= shft_tmv;

            curr_state <= 6'd16;
          end
        end
        6'd16 : begin
          if (m2p64add_rdy == 1'b1) begin
            tmv_key <= m2p64add_out;

            //ADD - KEY2
            add_one_in <= m2p64add_out;
            add_two_in <= trans_key_in;

            curr_state <= 6'd17;
          end
        end
        6'd17 : begin
          if (m2p64add_rdy == 1'b1) begin
            //ADD - KEY2
            add_start <= 1'b0;
            //SPLT - KEY2
            sbpsmc_start <= 1'b1;
            add_one_in <= m2p64add_out;

            curr_state <= 6'd18;
          end
        end
        6'd18 : begin
          if (sbpsmc_rdy == 1'b1) begin
            //SPLT - KEY2
            sbpsmc_start <= 1'b0;
            //XOR - KEY2
            xor_start <= 1'b1;
            add_one_in <= tmv_key;
            add_two_in <= sbpsmc_out;

            curr_state <= 6'd19;
          end
        end
        6'd19 : begin
          if (m2add_rdy == 1'b1) begin
            //XOR - KEY2
            xor_start <= 1'b0;
            //SPLT - KEY2
            sbpsmc_start <= 1'b1;
            add_one_in <= m2add_out;

            curr_state <= 6'd20;
          end
        end
        6'd20 : begin
          if (sbpsmc_rdy == 1'b1) begin
            //SPLT - KEY2
            sbpsmc_start <= 1'b0;
            //ADD - KEY2
            add_start <= 1'b1;
            add_one_in <= tmv_key;
            add_two_in <= sbpsmc_out;

            curr_state <= 6'd21;
          end
        end
        //Round 2 key generation ends here and Round 2-3 operations start here
        6'd21 : begin
          if (m2p64add_rdy == 1'b1) begin
            tmv_key <= m2p64add_out;

            //ADD - KEY2
            add_start <= 1'b0;
            //SPLT - RND2
            sbpsmc_start <= 1'b1;
            add_one_in <= round_out;

            curr_state <= 6'd22;
          end
        end
        6'd22 : begin
          if (sbpsmc_rdy == 1'b1) begin
            //SPLT RND2
            sbpsmc_start <= 1'b0;
            //XOR - RND2
            xor_start <= 1'b1;
            add_one_in <= sbpsmc_out;
            add_two_in <= tmv_key;

            curr_state <= 6'd23;
          end
        end
        6'd23 : begin
          if (m2add_rdy == 1'b1) begin
            //XOR - RND2
            xor_start <= 1'b0;
            //SPLT -RND3
            sbpsmc_start <= 1'b1;
            add_one_in <= m2add_out;

            curr_state <= 6'd24;
          end
        end
        6'd24 : begin
          if (sbpsmc_rdy == 1'b1) begin
            //RND - KEY4
            rnd_num <= rnd_num + 5'd2;

            //SPLT RND3
            sbpsmc_start <= 1'b0;
            //XOR - RND3
            xor_start <= 1'b1;
            add_one_in <= sbpsmc_out;
            add_two_in <= {tmv_key[BLOCK_SIZE-1-the_lr:0], tmv_key[BLOCK_SIZE-1:BLOCK_SIZE-the_lr]};

            curr_state <= 6'd25;
          end
        end
        //Round 2-3 operations end here and Round 4 key generation starts here
        6'd25 : begin
          if (m2add_rdy == 1'b1) begin
            round_out <= m2add_out;
            //XOR - RND3
            xor_start <= 1'b0;
            //ADD - KEY4
            add_start <= 1'b1;
            add_one_in <= int_key;
            add_two_in <= shft_tmv;

            curr_state <= 6'd26;
          end
        end
        6'd26 : begin
          if (m2p64add_rdy == 1'b1) begin
            tmv_key <= m2p64add_out;

            //ADD - KEY4
            add_one_in <= m2p64add_out;
            add_two_in <= trans_key_in;

            curr_state <= 6'd27;
          end
        end
        6'd27 : begin
          if (m2p64add_rdy == 1'b1) begin
            //ADD - KEY4
            add_start <= 1'b0;
            //SPLT - KEY4
            sbpsmc_start <= 1'b1;
            add_one_in <= m2p64add_out;

            curr_state <= 6'd28;
          end
        end
        6'd28 : begin
          if (sbpsmc_rdy == 1'b1) begin
            //SPLT - KEY4
            sbpsmc_start <= 1'b0;
            //XOR - KEY4
            xor_start <= 1'b1;
            add_one_in <= tmv_key;
            add_two_in <= sbpsmc_out;

            curr_state <= 6'd29;
          end
        end
        6'd29 : begin
          if (m2add_rdy == 1'b1) begin
            //XOR - KEY4
            xor_start <= 1'b0;
            //SPLT - KEY4
            sbpsmc_start <= 1'b1;
            add_one_in <= m2add_out;

            curr_state <= 6'd30;
          end
        end
        6'd30 : begin
          if (sbpsmc_rdy == 1'b1) begin
            //SPLT - KEY4
            sbpsmc_start <= 1'b0;
            //ADD - KEY4
            add_start <= 1'b1;
            add_one_in <= tmv_key;
            add_two_in <= sbpsmc_out;

            curr_state <= 6'd31;
          end
        end
        //Round 4 key generation ends here and Round 4-5 operations start here
        6'd31 : begin
          if (m2p64add_rdy == 1'b1) begin
            tmv_key <= m2p64add_out;

            //ADD - KEY4
            add_start <= 1'b0;
            //SPLT - RND4
            sbpsmc_start <= 1'b1;
            add_one_in <= round_out;

            curr_state <= 6'd32;
          end
        end
        6'd32 : begin
          if (sbpsmc_rdy == 1'b1) begin
            //SPLT RND4
            sbpsmc_start <= 1'b0;
            //XOR - RND4
            xor_start <= 1'b1;
            add_one_in <= sbpsmc_out;
            add_two_in <= tmv_key;

            curr_state <= 6'd33;
          end
        end
        6'd33 : begin
          if (m2add_rdy == 1'b1) begin
            //XOR - RND4
            xor_start <= 1'b0;
            //SPLT -RND5
            sbpsmc_start <= 1'b1;
            add_one_in <= m2add_out;

            curr_state <= 6'd34;
          end
        end
        6'd34 : begin
          if (sbpsmc_rdy == 1'b1) begin
            //RND - KEY6
            rnd_num <= rnd_num + 5'd2;

            //SPLT RND5
            sbpsmc_start <= 1'b0;
            //XOR - RND5
            xor_start <= 1'b1;
            add_one_in <= sbpsmc_out;
            add_two_in <= {tmv_key[BLOCK_SIZE-1-the_lr:0], tmv_key[BLOCK_SIZE-1:BLOCK_SIZE-the_lr]};

            curr_state <= 6'd35;
          end
        end
        //Round 4-5 operations end here and Round 6 key generation starts here
        6'd35 : begin
          if (m2add_rdy == 1'b1) begin
            round_out <= m2add_out;
            //XOR - RND5
            xor_start <= 1'b0;
            //ADD - KEY6
            add_start <= 1'b1;
            add_one_in <= int_key;
            add_two_in <= shft_tmv;

            curr_state <= 6'd36;
          end
        end
        6'd36 : begin
          if (m2p64add_rdy == 1'b1) begin
            tmv_key <= m2p64add_out;

            //ADD - KEY6
            add_one_in <= m2p64add_out;
            add_two_in <= trans_key_in;

            curr_state <= 6'd37;
          end
        end
        6'd37 : begin
          if (m2p64add_rdy == 1'b1) begin
            //ADD - KEY6
            add_start <= 1'b0;
            //SPLT - KEY6
            sbpsmc_start <= 1'b1;
            add_one_in <= m2p64add_out;

            curr_state <= 6'd38;
          end
        end
        6'd38 : begin
          if (sbpsmc_rdy == 1'b1) begin
            //SPLT - KEY6
            sbpsmc_start <= 1'b0;
            //XOR - KEY6
            xor_start <= 1'b1;
            add_one_in <= tmv_key;
            add_two_in <= sbpsmc_out;

            curr_state <= 6'd39;
          end
        end
        6'd39 : begin
          if (m2add_rdy == 1'b1) begin
            //XOR - KEY6
            xor_start <= 1'b0;
            //SPLT - KEY6
            sbpsmc_start <= 1'b1;
            add_one_in <= m2add_out;

            curr_state <= 6'd40;
          end
        end
        6'd40 : begin
          if (sbpsmc_rdy == 1'b1) begin
            //SPLT - KEY6
            sbpsmc_start <= 1'b0;
            //ADD - KEY6
            add_start <= 1'b1;
            add_one_in <= tmv_key;
            add_two_in <= sbpsmc_out;

            curr_state <= 6'd41;
          end
        end
        //Round 6 key generation ends here and Round 6-7 operations start here
        6'd41 : begin
          if (m2p64add_rdy == 1'b1) begin
            tmv_key <= m2p64add_out;

            //ADD - KEY6
            add_start <= 1'b0;
            //SPLT - RND6
            sbpsmc_start <= 1'b1;
            add_one_in <= round_out;

            curr_state <= 6'd42;
          end
        end
        6'd42 : begin
          if (sbpsmc_rdy == 1'b1) begin
            //SPLT RND6
            sbpsmc_start <= 1'b0;
            //XOR - RND6
            xor_start <= 1'b1;
            add_one_in <= sbpsmc_out;
            add_two_in <= tmv_key;

            curr_state <= 6'd43;
          end
        end
        6'd43 : begin
          if (m2add_rdy == 1'b1) begin
            //XOR - RND6
            xor_start <= 1'b0;
            //SPLT -RND7
            sbpsmc_start <= 1'b1;
            add_one_in <= m2add_out;

            curr_state <= 6'd44;
          end
        end
        6'd44 : begin
          if (sbpsmc_rdy == 1'b1) begin
            //RND - KEY8
            rnd_num <= rnd_num + 5'd2;

            //SPLT RND7
            sbpsmc_start <= 1'b0;
            //XOR - RND7
            xor_start <= 1'b1;
            add_one_in <= sbpsmc_out;
            add_two_in <= {tmv_key[BLOCK_SIZE-1-the_lr:0], tmv_key[BLOCK_SIZE-1:BLOCK_SIZE-the_lr]};

            curr_state <= 6'd45;
          end
        end
        //Round 6-7 operations end here and Round 8 key generation starts here
        6'd45 : begin
          if (m2add_rdy == 1'b1) begin
            round_out <= m2add_out;
            //XOR - RND7
            xor_start <= 1'b0;
            //ADD - KEY8
            add_start <= 1'b1;
            add_one_in <= int_key;
            add_two_in <= shft_tmv;

            curr_state <= 6'd46;
          end
        end
        6'd46 : begin
          if (m2p64add_rdy == 1'b1) begin
            tmv_key <= m2p64add_out;

            //ADD - KEY8
            add_one_in <= m2p64add_out;
            add_two_in <= trans_key_in;

            curr_state <= 6'd47;
          end
        end
        6'd47 : begin
          if (m2p64add_rdy == 1'b1) begin
            //ADD - KEY8
            add_start <= 1'b0;
            //SPLT - KEY8
            sbpsmc_start <= 1'b1;
            add_one_in <= m2p64add_out;

            curr_state <= 6'd48;
          end
        end
        6'd48 : begin
          if (sbpsmc_rdy == 1'b1) begin
            //SPLT - KEY8
            sbpsmc_start <= 1'b0;
            //XOR - KEY8
            xor_start <= 1'b1;
            add_one_in <= tmv_key;
            add_two_in <= sbpsmc_out;

            curr_state <= 6'd49;
          end
        end
        6'd49 : begin
          if (m2add_rdy == 1'b1) begin
            //XOR - KEY8
            xor_start <= 1'b0;
            //SPLT - KEY8
            sbpsmc_start <= 1'b1;
            add_one_in <= m2add_out;

            curr_state <= 6'd50;
          end
        end
        6'd50 : begin
          if (sbpsmc_rdy == 1'b1) begin
            //SPLT - KEY8
            sbpsmc_start <= 1'b0;
            //ADD - KEY8
            add_start <= 1'b1;
            add_one_in <= tmv_key;
            add_two_in <= sbpsmc_out;

            curr_state <= 6'd51;
          end
        end
        //Round 8 key generation ends here and Round 8-9 operations start here
        6'd51 : begin
          if (m2p64add_rdy == 1'b1) begin
            tmv_key <= m2p64add_out;

            //ADD - KEY8
            add_start <= 1'b0;
            //SPLT - RND8
            sbpsmc_start <= 1'b1;
            add_one_in <= round_out;

            curr_state <= 6'd52;
          end
        end
        6'd52 : begin
          if (sbpsmc_rdy == 1'b1) begin
            //SPLT RND8
            sbpsmc_start <= 1'b0;
            //XOR - RND8
            xor_start <= 1'b1;
            add_one_in <= sbpsmc_out;
            add_two_in <= tmv_key;

            curr_state <= 6'd53;
          end
        end
        6'd53 : begin
          if (m2add_rdy == 1'b1) begin
            //XOR - RND8
            xor_start <= 1'b0;
            //SPLT -RND9
            sbpsmc_start <= 1'b1;
            add_one_in <= m2add_out;

            curr_state <= 6'd54;
          end
        end
        6'd54 : begin
          if (sbpsmc_rdy == 1'b1) begin
            //RND - KEY10
            rnd_num <= rnd_num + 5'd2;

            //SPLT RND9
            sbpsmc_start <= 1'b0;
            //XOR - RND9
            xor_start <= 1'b1;
            add_one_in <= sbpsmc_out;
            add_two_in <= {tmv_key[BLOCK_SIZE-1-the_lr:0], tmv_key[BLOCK_SIZE-1:BLOCK_SIZE-the_lr]};

            curr_state <= 6'd55;
          end
        end
        //Round 8-9 operations end here and Round 10 key generation starts here
        6'd55 : begin
          if (m2add_rdy == 1'b1) begin
            round_out <= m2add_out;
            //XOR - RND9
            xor_start <= 1'b0;
            //ADD - KEY10
            add_start <= 1'b1;
            add_one_in <= int_key;
            add_two_in <= shft_tmv;

            if (rnd_cnt == 5'd10) begin
              curr_state <= 6'd56;
            end
            else if (rnd_cnt == 5'd14) begin
              if (rnd_num  == 5'd14) begin
                curr_state <= 6'd56;
              end
              else begin
                curr_state <= 6'd36;
              end
            end
            else begin
              if (rnd_num  == 5'd18) begin
                curr_state <= 6'd56;
              end
              else begin
                curr_state <= 6'd16;
              end
            end
          end
        end
        6'd56 : begin
          if (m2p64add_rdy == 1'b1) begin
            tmv_key <= m2p64add_out;

            //ADD - KEY10
            add_one_in <= m2p64add_out;
            add_two_in <= trans_key_in;

            curr_state <= 6'd57;
          end
        end
        6'd57 : begin
          if (m2p64add_rdy == 1'b1) begin
            //ADD - KEY10
            add_start <= 1'b0;
            //SPLT - KEY10
            sbpsmc_start <= 1'b1;
            add_one_in <= m2p64add_out;

            curr_state <= 6'd58;
          end
        end
        6'd58 : begin
          if (sbpsmc_rdy == 1'b1) begin
            //SPLT - KEY10
            sbpsmc_start <= 1'b0;
            //XOR - KEY10
            xor_start <= 1'b1;
            add_one_in <= tmv_key;
            add_two_in <= sbpsmc_out;

            curr_state <= 6'd59;
          end
        end
        6'd59 : begin
          if (m2add_rdy == 1'b1) begin
            //XOR - KEY10
            xor_start <= 1'b0;
            //SPLT - KEY10
            sbpsmc_start <= 1'b1;
            add_one_in <= m2add_out;

            curr_state <= 6'd60;
          end
        end
        6'd60 : begin
          if (sbpsmc_rdy == 1'b1) begin
            //SPLT - KEY10
            sbpsmc_start <= 1'b0;
            //ADD - KEY10
            add_start <= 1'b1;
            add_one_in <= tmv_key;
            add_two_in <= sbpsmc_out;

            curr_state <= 6'd61;
          end
        end
        //Round 10 key generation ends here and Round 10 operation starts here
        6'd61 : begin
          if (m2p64add_rdy == 1'b1) begin
            tmv_key <= m2p64add_out;

            //ADD - KEY10
            add_start <= 1'b0;
            //SPLT - RND10
            sbpsmc_start <= 1'b1;
            add_one_in <= round_out;

            curr_state <= 6'd62;
          end
        end
        6'd62 : begin
          if (sbpsmc_rdy == 1'b1) begin
            //SPLT RND10
            sbpsmc_start <= 1'b0;
            //ADD - RND10
            add_start <= 1'b1;
            add_one_in <= sbpsmc_out;
            add_two_in <= tmv_key;

            curr_state <= 6'd63;
          end
        end
        6'd63 : begin
          if (m2p64add_rdy == 1'b1) begin
            round_out <= m2p64add_out;
            reg_block_rdy <= 1'b1;

            //ADD - RND10
            add_start <= 1'b0;

            curr_state <= 6'd0;
          end
        end
        default : begin
          rnd_num <= 5'd0;
          add_start <= 1'b0;
          xor_start <= 1'b0;
          curr_state <= 6'd0;
          sbpsmc_start <= 1'b0;
          reg_block_rdy <= 1'b0;
          tmv_key <= {BLOCK_SIZE{1'b0}};
          int_key <= {BLOCK_SIZE{1'b0}};
          round_out <= {BLOCK_SIZE{1'b0}};
          add_one_in <= {BLOCK_SIZE{1'b0}};
          add_two_in <= {BLOCK_SIZE{1'b0}};
        end
      endcase
    end
  end
end

//Additions
mod2_add_serial64b #(.BLOCK_SIZE(BLOCK_SIZE)) m2a_ins (.clk(clk), .rst(rst), .m2add_start(xor_start), .m2add_in_one(add_one_in), .m2add_in_two(add_two_in), .m2add_out(m2add_out), .m2add_rdy(m2add_rdy));
mod2p64_add_serial64b #(.BLOCK_SIZE(BLOCK_SIZE)) m2p64a_ins (.clk(clk), .rst(rst), .m2p64add_start(add_start), .m2p64add_in_one(add_one_in), .m2p64add_in_two(add_two_in), .m2p64add_out(m2p64add_out), .m2p64add_rdy(m2p64add_rdy));
//Substitution Permutation Mix-Column
sbpsmc_serial64b #(.BLOCK_SIZE(BLOCK_SIZE)) sbpsmc64b_ins (.clk(clk), .rst(rst), .sbpsmc_start(sbpsmc_start), .sbpsmc_in(add_one_in), .sbpsmc_out(sbpsmc_out), .sbpsmc_rdy(sbpsmc_rdy));

//Block Outputs
always @ (posedge clk) begin
  if (rst == 1'b1) begin
    block_rdy <= 1'b0;
    block_out <= {BLOCK_SIZE{1'b0}};
  end
  else begin
    if (reg_enc_start == 1'b0) begin
      block_rdy <= 1'b0;
      block_out <= {BLOCK_SIZE{1'b0}};
    end
    else begin
      if (reg_block_rdy == 1'b1) begin
        block_rdy <= 1'b1;
        block_out <= round_out;
      end
    end
  end
end

endmodule

//KALYNA ENCRYPTION BLOCK - SERIAL - ONE 64-bit OPERATION IN ONE CLOCK CYCLE - All the operations are on
module kalyna_enc_block_serial64b_oboc_allon #(parameter BLOCK_SIZE = 128, parameter KEY_LENGTH = 128) (clk, rst, start, block_in, key_in, block_out, block_rdy);

input clk, rst, start;
input [BLOCK_SIZE-1:0] block_in;
input [KEY_LENGTH-1:0] key_in;
output reg [BLOCK_SIZE-1:0] block_out;
output reg block_rdy;

//Local parameters
localparam bs_m8 = BLOCK_SIZE - 8;
localparam bs_d16 = BLOCK_SIZE/16;
localparam the_lr = (BLOCK_SIZE/4+24);
localparam rnd_cnt = (BLOCK_SIZE == KEY_LENGTH && BLOCK_SIZE == 128) ? 5'd10 : (BLOCK_SIZE == KEY_LENGTH && BLOCK_SIZE == 256) ? 5'd14 : (BLOCK_SIZE == KEY_LENGTH && BLOCK_SIZE == 512) ? 5'd18 : (BLOCK_SIZE != KEY_LENGTH && BLOCK_SIZE == 128) ? 5'd14 : 5'd18;

//Variables
reg [4:0] rnd_num;
reg [5:0] curr_state;
reg [KEY_LENGTH-1:0] trans_in;
reg xor_start, add_start, sbpsmc_start, reg_block_rdy, reg_enc_start;
reg [BLOCK_SIZE-1:0] key_alfa, key_omega, add_one_in, add_two_in, int_key, shft_tmv, trans_key_in, tmv_key, round_out;
wire m2add_rdy, m2p64add_rdy, sbpsmc_rdy;
wire [BLOCK_SIZE-1:0] int_key_in, the_tmv;
wire [7:0] the_const = (BLOCK_SIZE+KEY_LENGTH)/64 + 1;
wire [BLOCK_SIZE-1:0] m2add_out, m2p64add_out, sbpsmc_out;

//Input to the intermediate key transformation
assign int_key_in = {the_const, {bs_m8{1'b0}}};

//Alfa and Omega Keys for the intermediate key transformation
always @ (*) begin
  if (BLOCK_SIZE == KEY_LENGTH) begin
    key_alfa = key_in;
    key_omega = key_in;
  end
  else begin
    key_alfa = key_in[KEY_LENGTH-1:KEY_LENGTH/2];
    key_omega = key_in[KEY_LENGTH/2-1:0];
  end
end

//Generation of the TMV signal and its shifted version
assign the_tmv= {bs_d16{16'h0100}};
always @ (*) begin
  case (rnd_num)
    5'd0    : shft_tmv = the_tmv;
    5'd2    : shft_tmv = {the_tmv[BLOCK_SIZE-2:0],  1'd0};
    5'd4    : shft_tmv = {the_tmv[BLOCK_SIZE-3:0],  2'd0};
    5'd6    : shft_tmv = {the_tmv[BLOCK_SIZE-4:0],  3'd0};
    5'd8    : shft_tmv = {the_tmv[BLOCK_SIZE-5:0],  4'd0};
    5'd10   : shft_tmv = {the_tmv[BLOCK_SIZE-6:0],  5'd0};
    5'd12   : shft_tmv = {the_tmv[BLOCK_SIZE-7:0],  6'd0};
    5'd14   : shft_tmv = {the_tmv[BLOCK_SIZE-8:0],  7'd0};
    5'd16   : shft_tmv = {the_tmv[BLOCK_SIZE-9:0],  7'd0, 1'b1};
    5'd18   : shft_tmv = {the_tmv[BLOCK_SIZE-10:0], 7'd0, 1'b1, 1'b0}; //Last two lines are due to the conflict between rotate and shift
    default : shft_tmv = the_tmv;
  endcase
end

//Generation of the input to the transformations
always @ (*) begin
  if (BLOCK_SIZE == KEY_LENGTH) begin
    if (BLOCK_SIZE == 128) begin
      case (rnd_num) 
        5'd0    : trans_in = key_in;
        5'd2    : trans_in = {key_in[63:0], key_in[127:64]};
        5'd4    : trans_in = key_in;
        5'd6    : trans_in = {key_in[63:0], key_in[127:64]};
        5'd8    : trans_in = key_in;
        5'd10   : trans_in = {key_in[63:0], key_in[127:64]};
        default : trans_in = key_in;
      endcase
    end
    else if (BLOCK_SIZE == 256) begin
      case (rnd_num) 
        5'd0    : trans_in = key_in;
        5'd2    : trans_in = {key_in[191:0], key_in[255:192]};
        5'd4    : trans_in = {key_in[127:0], key_in[255:128]};
        5'd6    : trans_in = {key_in[63:0],  key_in[255:64]};
        5'd8    : trans_in = key_in;
        5'd10   : trans_in = {key_in[191:0], key_in[255:192]};
        5'd12   : trans_in = {key_in[127:0], key_in[255:128]};
        5'd14   : trans_in = {key_in[63:0],  key_in[255:64]};
        default : trans_in = key_in;
      endcase
    end
    else begin
      case (rnd_num) 
        5'd0    : trans_in = key_in;
        5'd2    : trans_in = {key_in[447:0], key_in[511:448]};
        5'd4    : trans_in = {key_in[383:0], key_in[511:384]};
        5'd6    : trans_in = {key_in[319:0], key_in[511:320]};
        5'd8    : trans_in = {key_in[255:0], key_in[511:256]};
        5'd10   : trans_in = {key_in[191:0], key_in[511:192]};
        5'd12   : trans_in = {key_in[127:0], key_in[511:128]};
        5'd14   : trans_in = {key_in[63:0],  key_in[511:64]};
        5'd16   : trans_in = key_in;
        5'd18   : trans_in = {key_in[447:0], key_in[511:448]};
        default : trans_in = key_in;
      endcase
    end
  end
  else begin
    if (BLOCK_SIZE == 128) begin
      case (rnd_num) 
        5'd0    : trans_in = key_in;
        5'd2    : trans_in = key_in;
        5'd4    : trans_in = {key_in[191:0], key_in[255:192]};
        5'd6    : trans_in = {key_in[191:0], key_in[255:192]};
        5'd8    : trans_in = {key_in[127:0], key_in[255:128]};
        5'd10   : trans_in = {key_in[127:0], key_in[255:128]};
        5'd12   : trans_in = {key_in[63:0],  key_in[255:64]};
        5'd14   : trans_in = {key_in[63:0],  key_in[255:64]};
        default : trans_in = key_in;
      endcase
    end
    else begin
      case (rnd_num) 
        5'd0    : trans_in = key_in;
        5'd2    : trans_in = key_in;
        5'd4    : trans_in = {key_in[447:0], key_in[511:448]};
        5'd6    : trans_in = {key_in[447:0], key_in[511:448]};
        5'd8    : trans_in = {key_in[383:0], key_in[511:384]};
        5'd10   : trans_in = {key_in[383:0], key_in[511:384]};
        5'd12   : trans_in = {key_in[319:0], key_in[511:320]};
        5'd14   : trans_in = {key_in[319:0], key_in[511:320]};
        5'd16   : trans_in = {key_in[255:0], key_in[511:256]};
        5'd18   : trans_in = {key_in[255:0], key_in[511:256]};
        default : trans_in = key_in;
      endcase
    end
  end
end
always @ (*) begin
  if (BLOCK_SIZE == KEY_LENGTH) begin
    trans_key_in = trans_in;
  end
  else begin
    case (rnd_num) 
      5'd0    : trans_key_in = trans_in[KEY_LENGTH-1:KEY_LENGTH-BLOCK_SIZE];
      5'd2    : trans_key_in = trans_in[BLOCK_SIZE-1:0];
      5'd4    : trans_key_in = trans_in[KEY_LENGTH-1:KEY_LENGTH-BLOCK_SIZE]; 
      5'd6    : trans_key_in = trans_in[BLOCK_SIZE-1:0]; 
      5'd8    : trans_key_in = trans_in[KEY_LENGTH-1:KEY_LENGTH-BLOCK_SIZE]; 
      5'd10   : trans_key_in = trans_in[BLOCK_SIZE-1:0]; 
      5'd12   : trans_key_in = trans_in[KEY_LENGTH-1:KEY_LENGTH-BLOCK_SIZE]; 
      5'd14   : trans_key_in = trans_in[BLOCK_SIZE-1:0]; 
      5'd16   : trans_key_in = trans_in[KEY_LENGTH-1:KEY_LENGTH-BLOCK_SIZE]; 
      5'd18   : trans_key_in = trans_in[BLOCK_SIZE-1:0]; 
      default : trans_key_in = trans_in[BLOCK_SIZE-1:0]; 
    endcase
  end
end

//The reg_enc_start signal indicates that the encryption process is started
always @ (posedge clk) begin
  if (rst == 1'b1) begin
    reg_enc_start <= 1'b0;
  end
  else begin
    if (block_rdy == 1'b1) begin
      reg_enc_start <= 1'b0;
