//KALYNA ENCRYPTION BLOCK - SERIAL - ONE 64-bit OPERATION IN ONE CLOCK CYCLE- REDUCED NUMBER of CLOCK CYCLES
module kalyna_enc_block_serial64b_oboc_redcyc #(parameter BLOCK_SIZE = 128, parameter KEY_LENGTH = 128) (clk, rst, start, block_in, key_in, block_out, block_rdy);

input clk, rst, start;
input [BLOCK_SIZE-1:0] block_in;
input [KEY_LENGTH-1:0] key_in;
output reg [BLOCK_SIZE-1:0] block_out;
output reg block_rdy;

//Local parameters
localparam bs_m8 = BLOCK_SIZE - 8;
localparam bs_d16 = BLOCK_SIZE/16;
localparam the_lr = (BLOCK_SIZE/4+24);
localparam rnd_cnt = (BLOCK_SIZE == KEY_LENGTH && BLOCK_SIZE == 128) ? 5'd10 : (BLOCK_SIZE == KEY_LENGTH && BLOCK_SIZE == 256) ? 5'd14 : (BLOCK_SIZE == KEY_LENGTH && BLOCK_SIZE == 512) ? 5'd18 : (BLOCK_SIZE != KEY_LENGTH && BLOCK_SIZE == 128) ? 5'd14 : 5'd18;

//Variables
reg [4:0] rnd_num;
reg [5:0] curr_state;
reg [KEY_LENGTH-1:0] trans_in;
reg xor_start, add_start, sbpsmc_start, reg_block_rdy, reg_enc_start;
reg [BLOCK_SIZE-1:0] key_alfa, key_omega, add_one_in, add_two_in, sbpsmc_in, xor_one_in, xor_two_in, int_key, shft_tmv, trans_key_in, rnd_tmv, rnd_key, round_out;
wire m2add_rdy, m2p64add_rdy, sbpsmc_rdy;
wire [BLOCK_SIZE-1:0] int_key_in, the_tmv;
wire [7:0] the_const = (BLOCK_SIZE+KEY_LENGTH)/64 + 1;
wire [BLOCK_SIZE-1:0] m2add_out, m2p64add_out, sbpsmc_out;

//Input to the intermediate key transformation
assign int_key_in = {the_const, {bs_m8{1'b0}}};

//Alfa and Omega Keys for the intermediate key transformation
always @ (*) begin
  if (BLOCK_SIZE == KEY_LENGTH) begin
    key_alfa = key_in;
    key_omega = key_in;
  end
  else begin
    key_alfa = key_in[KEY_LENGTH-1:KEY_LENGTH/2];
    key_omega = key_in[KEY_LENGTH/2-1:0];
  end
end

//Generation of the TMV signal and its shifted version
assign the_tmv= {bs_d16{16'h0100}};
always @ (*) begin
  case (rnd_num)
    5'd0    : shft_tmv = the_tmv;
    5'd2    : shft_tmv = {the_tmv[BLOCK_SIZE-2:0],  1'd0};
    5'd4    : shft_tmv = {the_tmv[BLOCK_SIZE-3:0],  2'd0};
    5'd6    : shft_tmv = {the_tmv[BLOCK_SIZE-4:0],  3'd0};
    5'd8    : shft_tmv = {the_tmv[BLOCK_SIZE-5:0],  4'd0};
    5'd10   : shft_tmv = {the_tmv[BLOCK_SIZE-6:0],  5'd0};
    5'd12   : shft_tmv = {the_tmv[BLOCK_SIZE-7:0],  6'd0};
    5'd14   : shft_tmv = {the_tmv[BLOCK_SIZE-8:0],  7'd0};
    5'd16   : shft_tmv = {the_tmv[BLOCK_SIZE-9:0],  7'd0, 1'b1};
    5'd18   : shft_tmv = {the_tmv[BLOCK_SIZE-10:0], 7'd0, 1'b1, 1'b0}; //Last two lines are due to the conflict between rotate and shift
    default : shft_tmv = the_tmv;
  endcase
end

//Generation of the input to the transformations
always @ (*) begin
  if (BLOCK_SIZE == KEY_LENGTH) begin
    if (BLOCK_SIZE == 128) begin
      case (rnd_num) 
        5'd0    : trans_in = key_in;
        5'd2    : trans_in = {key_in[63:0], key_in[127:64]};
        5'd4    : trans_in = key_in;
        5'd6    : trans_in = {key_in[63:0], key_in[127:64]};
        5'd8    : trans_in = key_in;
        5'd10   : trans_in = {key_in[63:0], key_in[127:64]};
        default : trans_in = key_in;
      endcase
    end
    else if (BLOCK_SIZE == 256) begin
      case (rnd_num) 
        5'd0    : trans_in = key_in;
        5'd2    : trans_in = {key_in[191:0], key_in[255:192]};
        5'd4    : trans_in = {key_in[127:0], key_in[255:128]};
        5'd6    : trans_in = {key_in[63:0],  key_in[255:64]};
        5'd8    : trans_in = key_in;
        5'd10   : trans_in = {key_in[191:0], key_in[255:192]};
        5'd12   : trans_in = {key_in[127:0], key_in[255:128]};
        5'd14   : trans_in = {key_in[63:0],  key_in[255:64]};
        default : trans_in = key_in;
      endcase
    end
    else begin
      case (rnd_num) 
        5'd0    : trans_in = key_in;
        5'd2    : trans_in = {key_in[447:0], key_in[511:448]};
        5'd4    : trans_in = {key_in[383:0], key_in[511:384]};
        5'd6    : trans_in = {key_in[319:0], key_in[511:320]};
        5'd8    : trans_in = {key_in[255:0], key_in[511:256]};
        5'd10   : trans_in = {key_in[191:0], key_in[511:192]};
        5'd12   : trans_in = {key_in[127:0], key_in[511:128]};
        5'd14   : trans_in = {key_in[63:0],  key_in[511:64]};
        5'd16   : trans_in = key_in;
        5'd18   : trans_in = {key_in[447:0], key_in[511:448]};
        default : trans_in = key_in;
      endcase
    end
  end
  else begin
    if (BLOCK_SIZE == 128) begin
      case (rnd_num) 
        5'd0    : trans_in = key_in;
        5'd2    : trans_in = key_in;
        5'd4    : trans_in = {key_in[191:0], key_in[255:192]};
        5'd6    : trans_in = {key_in[191:0], key_in[255:192]};
        5'd8    : trans_in = {key_in[127:0], key_in[255:128]};
        5'd10   : trans_in = {key_in[127:0], key_in[255:128]};
        5'd12   : trans_in = {key_in[63:0],  key_in[255:64]};
        5'd14   : trans_in = {key_in[63:0],  key_in[255:64]};
        default : trans_in = key_in;
      endcase
    end
    else begin
      case (rnd_num) 
        5'd0    : trans_in = key_in;
        5'd2    : trans_in = key_in;
        5'd4    : trans_in = {key_in[447:0], key_in[511:448]};
        5'd6    : trans_in = {key_in[447:0], key_in[511:448]};
        5'd8    : trans_in = {key_in[383:0], key_in[511:384]};
        5'd10   : trans_in = {key_in[383:0], key_in[511:384]};
        5'd12   : trans_in = {key_in[319:0], key_in[511:320]};
        5'd14   : trans_in = {key_in[319:0], key_in[511:320]};
        5'd16   : trans_in = {key_in[255:0], key_in[511:256]};
        5'd18   : trans_in = {key_in[255:0], key_in[511:256]};
        default : trans_in = key_in;
      endcase
    end
  end
end
always @ (*) begin
  if (BLOCK_SIZE == KEY_LENGTH) begin
    trans_key_in = trans_in;
  end
  else begin
    case (rnd_num) 
      5'd0    : trans_key_in = trans_in[KEY_LENGTH-1:KEY_LENGTH-BLOCK_SIZE];
      5'd2    : trans_key_in = trans_in[BLOCK_SIZE-1:0];
      5'd4    : trans_key_in = trans_in[KEY_LENGTH-1:KEY_LENGTH-BLOCK_SIZE]; 
      5'd6    : trans_key_in = trans_in[BLOCK_SIZE-1:0]; 
      5'd8    : trans_key_in = trans_in[KEY_LENGTH-1:KEY_LENGTH-BLOCK_SIZE]; 
      5'd10   : trans_key_in = trans_in[BLOCK_SIZE-1:0]; 
      5'd12   : trans_key_in = trans_in[KEY_LENGTH-1:KEY_LENGTH-BLOCK_SIZE]; 
      5'd14   : trans_key_in = trans_in[BLOCK_SIZE-1:0]; 
      5'd16   : trans_key_in = trans_in[KEY_LENGTH-1:KEY_LENGTH-BLOCK_SIZE]; 
      5'd18   : trans_key_in = trans_in[BLOCK_SIZE-1:0]; 
      default : trans_key_in = trans_in[BLOCK_SIZE-1:0]; 
    endcase
  end
end

//The reg_enc_start signal indicates that the encryption process is started
always @ (posedge clk) begin
  if (rst == 1'b1) begin
    reg_enc_start <= 1'b0;
  end
  else begin
    if (block_rdy == 1'b1) begin
      reg_enc_start <= 1'b0;
    end
    else begin
      if (start == 1'b1) begin
        reg_enc_start <= 1'b1;
      end
    end
  end
end

//Block inputs in each state  
always @ (posedge clk) begin
  if (rst == 1'b1) begin
    rnd_num <= 5'd0;
    add_start <= 1'b0;
    xor_start <= 1'b0;
    curr_state <= 6'd0;
    sbpsmc_start <= 1'b0;
    reg_block_rdy <= 1'b0;
    int_key <= {BLOCK_SIZE{1'b0}};
    rnd_tmv <= {BLOCK_SIZE{1'b0}};
    rnd_key <= {BLOCK_SIZE{1'b0}};
    round_out <= {BLOCK_SIZE{1'b0}};
    sbpsmc_in <= {BLOCK_SIZE{1'b0}};
    add_one_in <= {BLOCK_SIZE{1'b0}};
    add_two_in <= {BLOCK_SIZE{1'b0}};
    xor_one_in <= {BLOCK_SIZE{1'b0}};
    xor_two_in <= {BLOCK_SIZE{1'b0}};
  end
  else begin
    if (reg_enc_start == 1'b0) begin
      rnd_num <= 5'd0;
      add_start <= 1'b0;
      xor_start <= 1'b0;
      curr_state <= 6'd0;
      sbpsmc_start <= 1'b0;
      reg_block_rdy <= 1'b0;
      int_key <= {BLOCK_SIZE{1'b0}};
      rnd_tmv <= {BLOCK_SIZE{1'b0}};
      rnd_key <= {BLOCK_SIZE{1'b0}};
      round_out <= {BLOCK_SIZE{1'b0}};
      sbpsmc_in <= {BLOCK_SIZE{1'b0}};
      add_one_in <= {BLOCK_SIZE{1'b0}};
      add_two_in <= {BLOCK_SIZE{1'b0}};
      xor_one_in <= {BLOCK_SIZE{1'b0}};
      xor_two_in <= {BLOCK_SIZE{1'b0}};
    end
    else begin
      case (curr_state)
        //Intermediate key generattion starts here
        6'd0 : begin
          //ADD - INTKEY
          add_start <= 1'b1;
          add_one_in <= int_key_in;
          add_two_in <= key_alfa;

          curr_state <= 6'd1;
        end
        6'd1 : begin
          if (m2p64add_rdy == 1'b1) begin
            //ADD - INTKEY
            add_start <= 1'b0;
            //SPLT - INTKEY
            sbpsmc_start <= 1'b1;
            sbpsmc_in <= m2p64add_out;

            curr_state <= 6'd2;
          end
        end
        6'd2 : begin
          if (sbpsmc_rdy == 1'b1) begin
            //SPLT - INTKEY
            sbpsmc_start <= 1'b0;
            //XOR - INTKEY
            xor_start <= 1'b1;
            xor_one_in <= key_omega;
            xor_two_in <= sbpsmc_out;

            curr_state <= 6'd3;
          end
        end
        6'd3 : begin
          if (m2add_rdy == 1'b1) begin
            //XOR - INTKEY
            xor_start <= 1'b0;
            //SPLT - INTKEY
            sbpsmc_start <= 1'b1;
            sbpsmc_in <= m2add_out;
            
            curr_state <= 6'd4;
          end
        end
        6'd4 : begin
          if (sbpsmc_rdy == 1'b1) begin
            //SPLT - INTKEY
            sbpsmc_start <= 1'b0;
            //ADD - INTKEY
            add_start <= 1'b1;
            add_one_in <= key_alfa;
            add_two_in <= sbpsmc_out;

            curr_state <= 6'd5;
          end
        end
        6'd5 : begin
          if (m2p64add_rdy == 1'b1) begin
            //RND - KEY0
            rnd_num <= 5'd0;

            //ADD - INTKEY
            add_start <= 1'b0;
            //SPLT - INTKEY
            sbpsmc_start <= 1'b1;
            sbpsmc_in <= m2p64add_out;
            
            curr_state <= 6'd6;
          end
        end
        //Intermediate key generation ends and round 0 key generation starts here
        6'd6 : begin
          if (sbpsmc_rdy == 1'b1) begin
            int_key <= sbpsmc_out;

            //SPLT - KEY0
            sbpsmc_start <= 1'b0;
            //ADD - KEY0
            add_start <= 1'b1;
            add_one_in <= sbpsmc_out;
            add_two_in <= shft_tmv;

            curr_state <= 6'd7;
          end
        end
        6'd7 : begin
          if (m2p64add_rdy == 1'b1) begin
            rnd_tmv <= m2p64add_out;

            //ADD - KEY0
            add_one_in <= m2p64add_out;
            add_two_in <= trans_key_in;

            curr_state <= 6'd8;
          end
        end
        6'd8 : begin
          if (m2p64add_rdy == 1'b1) begin
            //ADD - KEY0
            add_start <= 1'b0;
            //SPLT - KEY0
            sbpsmc_start <= 1'b1;
            sbpsmc_in <= m2p64add_out;

            curr_state <= 6'd9;
          end
        end
        6'd9 : begin
          if (sbpsmc_rdy == 1'b1) begin
            //SPLT - KEY0
            sbpsmc_start <= 1'b0;
            //XOR - KEY0
            xor_start <= 1'b1;
            xor_one_in <= rnd_tmv;
            xor_two_in <= sbpsmc_out;

            curr_state <= 6'd10;
          end
        end
        6'd10 : begin
          if (m2add_rdy == 1'b1) begin
            //XOR - KEY0
            xor_start <= 1'b0;
            //SPLT - KEY0
            sbpsmc_start <= 1'b1;
            sbpsmc_in <= m2add_out;

            curr_state <= 6'd11;
          end
        end
        6'd11 : begin
          if (sbpsmc_rdy == 1'b1) begin
            //SPLT - KEY0
            sbpsmc_start <= 1'b0;
            //ADD - KEY0
            add_start <= 1'b1;
            add_one_in <= rnd_tmv;
            add_two_in <= sbpsmc_out;

            curr_state <= 6'd12;
          end
        end
        //Round 0 key generation ends here and Round 0-1 operations start here
        6'd12 : begin
          if (m2p64add_rdy == 1'b1) begin
            rnd_key <= m2p64add_out;
            //RND - KEY2
            rnd_num <= rnd_num + 5'd2;
            //ADD - RND0
            add_one_in <= m2p64add_out;
            add_two_in <= block_in;

            curr_state <= 6'd13;
          end
        end
        //Round 2-3 key generation starts here
        6'd13 : begin
          if (m2p64add_rdy == 1'b1) begin
            //SPLT - RND1
            sbpsmc_start <= 1'b1;
            sbpsmc_in <= m2p64add_out;
            //ADD - KEY2
            add_start <= 1'b1;
            add_one_in <= int_key;
            add_two_in <= shft_tmv;

            curr_state <= 6'd14;
          end
        end
        6'd14 : begin
          if (sbpsmc_rdy == 1'b1 & m2p64add_rdy == 1'b1) begin
            rnd_tmv <= m2p64add_out;
            //XOR - RND1
            xor_start <= 1'b1;
            xor_one_in <= sbpsmc_out;
            xor_two_in <= {rnd_key[BLOCK_SIZE-1-the_lr:0], rnd_key[BLOCK_SIZE-1:BLOCK_SIZE-the_lr]};
            //ADD - KEY2
            add_one_in <= m2p64add_out;
            add_two_in <= trans_key_in;

            curr_state <= 6'd15;
          end
        end
        6'd15 : begin
          if (m2p64add_rdy == 1'b1 & m2add_rdy == 1'b1) begin
            round_out <= m2add_out;
            //XOR - RND1
            xor_start <= 1'b0;
            //ADD - KEY2
            add_start <= 1'b0;
            //SPLT - KEY2
            sbpsmc_start <= 1'b1;
            sbpsmc_in <= m2p64add_out;

            curr_state <= 6'd16;
          end
        end
        6'd16 : begin
          if (sbpsmc_rdy == 1'b1) begin
            //SPLT - KEY2
            sbpsmc_start <= 1'b0;
            //XOR - KEY2
            xor_start <= 1'b1;
            xor_one_in <= rnd_tmv;
            xor_two_in <= sbpsmc_out;

            curr_state <= 6'd17;
          end
        end
        6'd17 : begin
          if (m2add_rdy == 1'b1) begin
            //XOR - KEY2
            xor_start <= 1'b0;
            //SPLT - KEY2
            sbpsmc_start <= 1'b1;
            sbpsmc_in <= m2add_out;

            curr_state <= 6'd18;
          end
        end
        6'd18 : begin
          if (sbpsmc_rdy == 1'b1) begin
            //SPLT - KEY2
            sbpsmc_start <= 1'b0;
            //ADD - KEY2
            add_start <= 1'b1;
            add_one_in <= rnd_tmv;
            add_two_in <= sbpsmc_out;

            curr_state <= 6'd19;
          end
        end
        //Round 2-3 key generation ends here and Round 2-3 operations start here
        6'd19 : begin
          if (m2p64add_rdy == 1'b1) begin
            rnd_key <= m2p64add_out;
            //RND - KEY4
            rnd_num <= rnd_num + 5'd2;
            //ADD - KEY2
            add_start <= 1'b0;
            //SPLT - RND2
            sbpsmc_start <= 1'b1;
            sbpsmc_in <= round_out;

            curr_state <= 6'd20;
          end
        end
        //Round 4-5 key generation starts here
        6'd20 : begin
          if (sbpsmc_rdy == 1'b1) begin
            //SPLT RND2
            sbpsmc_start <= 1'b0;
            //XOR - RND2
            xor_start <= 1'b1;
            xor_one_in <= sbpsmc_out;
            xor_two_in <= rnd_key;
            //ADD - KEY4
            add_start <= 1'b1;
            add_one_in <= int_key;
            add_two_in <= shft_tmv;

            curr_state <= 6'd21;
          end
        end
        6'd21 : begin
          if (m2add_rdy == 1'b1 & m2p64add_rdy == 1'b1) begin
            rnd_tmv <= m2p64add_out;
            //XOR - RND2
            xor_start <= 1'b0;
            //SPLT - RND3
            sbpsmc_start <= 1'b1;
            sbpsmc_in <= m2add_out;
            //ADD - KEY4
            add_one_in <= m2p64add_out;
            add_two_in <= trans_key_in;

            curr_state <= 6'd22;
          end
        end
        6'd22 : begin
          if (sbpsmc_rdy == 1'b1 & m2p64add_rdy == 1'b1) begin
            //XOR - RND3
            xor_start <= 1'b1;
            xor_one_in <= sbpsmc_out;
            xor_two_in <= {rnd_key[BLOCK_SIZE-1-the_lr:0], rnd_key[BLOCK_SIZE-1:BLOCK_SIZE-the_lr]};
            //ADD - KEY4
            sbpsmc_in <= m2p64add_out;

            curr_state <= 6'd23;
          end
        end
        6'd23 : begin
          if (m2add_rdy == 1'b1 & sbpsmc_rdy == 1'b1) begin
            round_out <= m2add_out;
            //SPLT - KEY4
            sbpsmc_start <= 1'b0;
            //XOR - KEY4
            xor_start <= 1'b1;
            xor_one_in <= rnd_tmv;
            xor_two_in <= sbpsmc_out;

            curr_state <= 6'd24;
          end
        end
        6'd24 : begin
          if (m2add_rdy == 1'b1) begin
            //XOR - KEY4
            xor_start <= 1'b0;
            //SPLT - KEY4
            sbpsmc_start <= 1'b1;
            sbpsmc_in <= m2add_out;

            curr_state <= 6'd25;
          end
        end
        6'd25 : begin
          if (sbpsmc_rdy == 1'b1) begin
            //SPLT - KEY4
            sbpsmc_start <= 1'b0;
            //ADD - KEY4
            add_start <= 1'b1;
            add_one_in <= rnd_tmv;
            add_two_in <= sbpsmc_out;

            curr_state <= 6'd26;
          end
        end
        //Round 4-5 key generation ends here and Round 4-5 operations start here
        6'd26 : begin
          if (m2p64add_rdy == 1'b1) begin
            rnd_key <= m2p64add_out;
            //RND - KEY6
            rnd_num <= rnd_num + 5'd2;
            //ADD - KEY4
            add_start <= 1'b0;
            //SPLT - RND4
            sbpsmc_start <= 1'b1;
            sbpsmc_in <= round_out;

            curr_state <= 6'd27;
          end
        end
        //Round 6-7 key generation starts here
        6'd27 : begin
          if (sbpsmc_rdy == 1'b1) begin
            //SPLT RND4
            sbpsmc_start <= 1'b0;
            //XOR - RND4
            xor_start <= 1'b1;
            xor_one_in <= sbpsmc_out;
            xor_two_in <= rnd_key;
            //ADD - KEY6
            add_start <= 1'b1;
            add_one_in <= int_key;
            add_two_in <= shft_tmv;

            curr_state <= 6'd28;
          end
        end
        6'd28 : begin
          if (m2add_rdy == 1'b1 & m2p64add_rdy == 1'b1) begin
            rnd_tmv <= m2p64add_out;
            //XOR - RND4
            xor_start <= 1'b0;
            //SPLT - RND5
            sbpsmc_start <= 1'b1;
            sbpsmc_in <= m2add_out;
            //ADD - KEY6
            add_one_in <= m2p64add_out;
            add_two_in <= trans_key_in;

            curr_state <= 6'd29;
          end
        end
        6'd29 : begin
          if (sbpsmc_rdy == 1'b1 & m2p64add_rdy == 1'b1) begin
            //XOR - RND5
            xor_start <= 1'b1;
            xor_one_in <= sbpsmc_out;
            xor_two_in <= {rnd_key[BLOCK_SIZE-1-the_lr:0], rnd_key[BLOCK_SIZE-1:BLOCK_SIZE-the_lr]};
            //ADD - KEY6
            sbpsmc_in <= m2p64add_out;

            curr_state <= 6'd30;
          end
        end
        6'd30 : begin
          if (m2add_rdy == 1'b1 & sbpsmc_rdy == 1'b1) begin
            round_out <= m2add_out;
            //SPLT - KEY6
            sbpsmc_start <= 1'b0;
            //XOR - KEY6
            xor_start <= 1'b1;
            xor_one_in <= rnd_tmv;
            xor_two_in <= sbpsmc_out;

            curr_state <= 6'd31;
          end
        end
        6'd31 : begin
          if (m2add_rdy == 1'b1) begin
            //XOR - KEY6
            xor_start <= 1'b0;
            //SPLT - KEY6
            sbpsmc_start <= 1'b1;
            sbpsmc_in <= m2add_out;

            curr_state <= 6'd32;
          end
        end
        6'd32 : begin
          if (sbpsmc_rdy == 1'b1) begin
            //SPLT - KEY6
            sbpsmc_start <= 1'b0;
            //ADD - KEY6
            add_start <= 1'b1;
            add_one_in <= rnd_tmv;
            add_two_in <= sbpsmc_out;

            curr_state <= 6'd33;
          end
        end
        //Round 6-7 key generation ends here and Round 6-7 operations start here
        6'd33 : begin
          if (m2p64add_rdy == 1'b1) begin
            rnd_key <= m2p64add_out;
            //RND - KEY8
            rnd_num <= rnd_num + 5'd2;
            //ADD - KEY6
            add_start <= 1'b0;
            //SPLT - RND6
            sbpsmc_start <= 1'b1;
            sbpsmc_in <= round_out;

            curr_state <= 6'd34;
          end
        end
        //Round 8-9 key generation starts here
        6'd34 : begin
          if (sbpsmc_rdy == 1'b1) begin
            //SPLT RND6
            sbpsmc_start <= 1'b0;
            //XOR - RND6
            xor_start <= 1'b1;
            xor_one_in <= sbpsmc_out;
            xor_two_in <= rnd_key;
            //ADD - KEY8
            add_start <= 1'b1;
            add_one_in <= int_key;
            add_two_in <= shft_tmv;

            curr_state <= 6'd35;
          end
        end
        6'd35 : begin
          if (m2add_rdy == 1'b1 & m2p64add_rdy == 1'b1) begin
            rnd_tmv <= m2p64add_out;
            //XOR - RND6
            xor_start <= 1'b0;
            //SPLT - RND7
            sbpsmc_start <= 1'b1;
            sbpsmc_in <= m2add_out;
            //ADD - KEY8
            add_one_in <= m2p64add_out;
            add_two_in <= trans_key_in;

            curr_state <= 6'd36;
          end
        end
        6'd36 : begin
          if (sbpsmc_rdy == 1'b1 & m2p64add_rdy == 1'b1) begin
            //XOR - RND7
            xor_start <= 1'b1;
            xor_one_in <= sbpsmc_out;
            xor_two_in <= {rnd_key[BLOCK_SIZE-1-the_lr:0], rnd_key[BLOCK_SIZE-1:BLOCK_SIZE-the_lr]};
            //ADD - KEY8
            sbpsmc_in <= m2p64add_out;

            curr_state <= 6'd37;
          end
        end
        6'd37 : begin
          if (m2add_rdy == 1'b1 & sbpsmc_rdy == 1'b1) begin
            round_out <= m2add_out;
            //SPLT - KEY8
            sbpsmc_start <= 1'b0;
            //XOR - KEY8
            xor_start <= 1'b1;
            xor_one_in <= rnd_tmv;
            xor_two_in <= sbpsmc_out;

            curr_state <= 6'd38;
          end
        end
        6'd38 : begin
          if (m2add_rdy == 1'b1) begin
            //XOR - KEY8
            xor_start <= 1'b0;
            //SPLT - KEY8
            sbpsmc_start <= 1'b1;
            sbpsmc_in <= m2add_out;

            curr_state <= 6'd39;
          end
        end
        6'd39 : begin
          if (sbpsmc_rdy == 1'b1) begin
            //SPLT - KEY8
            sbpsmc_start <= 1'b0;
            //ADD - KEY8
            add_start <= 1'b1;
            add_one_in <= rnd_tmv;
            add_two_in <= sbpsmc_out;

            curr_state <= 6'd40;
          end
        end
        //Round 8-9 key generation ends here and Round 8-9 operations start here
        6'd40 : begin
          if (m2p64add_rdy == 1'b1) begin
            rnd_key <= m2p64add_out;
            //RND - KEY10
            rnd_num <= rnd_num + 5'd2;
            //ADD - KEY8
            add_start <= 1'b0;
            //SPLT - RND8
            sbpsmc_start <= 1'b1;
            sbpsmc_in <= round_out;

            curr_state <= 6'd41;
          end
        end
        //Round 10 key generation starts here
        6'd41 : begin
          if (sbpsmc_rdy == 1'b1) begin
            //SPLT RND8
            sbpsmc_start <= 1'b0;
            //XOR - RND8
            xor_start <= 1'b1;
            xor_one_in <= sbpsmc_out;
            xor_two_in <= rnd_key;
            //ADD - KEY10
            add_start <= 1'b1;
            add_one_in <= int_key;
            add_two_in <= shft_tmv;

            if (rnd_cnt == 5'd10) begin
              curr_state <= 6'd42;
            end
            else if (rnd_cnt == 5'd14) begin
              if (rnd_num  == 5'd14) begin
                curr_state <= 6'd42;
              end
              else begin
                curr_state <= 6'd28;
              end
            end
            else begin
              if (rnd_num  == 5'd18) begin
                curr_state <= 6'd42;
              end
              else begin
                curr_state <= 6'd28;
              end
            end
          end
        end
        6'd42 : begin
          if (m2add_rdy == 1'b1 & m2p64add_rdy == 1'b1) begin
            rnd_tmv <= m2p64add_out;
            //XOR - RND8
            xor_start <= 1'b0;
            //SPLT - RND9
            sbpsmc_start <= 1'b1;
            sbpsmc_in <= m2add_out;
            //ADD - KEY10
            add_one_in <= m2p64add_out;
            add_two_in <= trans_key_in;

            curr_state <= 6'd43;
          end
        end
        6'd43 : begin
          if (sbpsmc_rdy == 1'b1 & m2p64add_rdy == 1'b1) begin
            //XOR - RND9
            xor_start <= 1'b1;
            xor_one_in <= sbpsmc_out;
            xor_two_in <= {rnd_key[BLOCK_SIZE-1-the_lr:0], rnd_key[BLOCK_SIZE-1:BLOCK_SIZE-the_lr]};
            //ADD - KEY10
            sbpsmc_in <= m2p64add_out;

            curr_state <= 6'd44;
          end
        end
        6'd44 : begin
          if (m2add_rdy == 1'b1 & sbpsmc_rdy == 1'b1) begin
            round_out <= m2add_out;
            //SPLT - KEY10
            sbpsmc_start <= 1'b0;
            //XOR - KEY10
            xor_start <= 1'b1;
            xor_one_in <= rnd_tmv;
            xor_two_in <= sbpsmc_out;

            curr_state <= 6'd45;
          end
        end
        6'd45 : begin
          if (m2add_rdy == 1'b1) begin
            //XOR - KEY10
            xor_start <= 1'b0;
            //SPLT - KEY10
            sbpsmc_start <= 1'b1;
            sbpsmc_in <= m2add_out;

            curr_state <= 6'd46;
          end
        end
        6'd46 : begin
          if (sbpsmc_rdy == 1'b1) begin
            //SPLT - KEY10
            sbpsmc_start <= 1'b0;
            //ADD - KEY10
            add_start <= 1'b1;
            add_one_in <= rnd_tmv;
            add_two_in <= sbpsmc_out;

            curr_state <= 6'd47;
          end
        end
        //Last round key generation ends here and last round operations start here
        6'd47 : begin
          if (m2p64add_rdy == 1'b1) begin
            rnd_key <= m2p64add_out;
            //ADD - KEY10
            add_start <= 1'b0;
            //SPLT - RND10
            sbpsmc_start <= 1'b1;
            sbpsmc_in <= round_out;

            curr_state <= 6'd48;
          end
        end
        6'd48 : begin
          if (sbpsmc_rdy == 1'b1) begin
            //SPLT RND10
            sbpsmc_start <= 1'b0;
            //ADD - RND10
            add_start <= 1'b1;
            add_one_in <= sbpsmc_out;
            add_two_in <= rnd_key;

            curr_state <= 6'd49;
          end
        end
        6'd49 : begin
          if (m2p64add_rdy == 1'b1) begin
            round_out <= m2p64add_out;
            reg_block_rdy <= 1'b1;

            //ADD - RND10
            add_start <= 1'b0;

            curr_state <= 6'd0;
          end
        end
        default : begin
          rnd_num <= 5'd0;
          add_start <= 1'b0;
          xor_start <= 1'b0;
          curr_state <= 6'd0;
          sbpsmc_start <= 1'b0;
          reg_block_rdy <= 1'b0;
          int_key <= {BLOCK_SIZE{1'b0}};
          rnd_tmv <= {BLOCK_SIZE{1'b0}};
          rnd_key <= {BLOCK_SIZE{1'b0}};
          round_out <= {BLOCK_SIZE{1'b0}};
          sbpsmc_in <= {BLOCK_SIZE{1'b0}};
          add_one_in <= {BLOCK_SIZE{1'b0}};
          add_two_in <= {BLOCK_SIZE{1'b0}};
          xor_one_in <= {BLOCK_SIZE{1'b0}};
          xor_two_in <= {BLOCK_SIZE{1'b0}};
        end
      endcase
    end
  end
end

//Additions
mod2_add_serial64b #(.BLOCK_SIZE(BLOCK_SIZE)) m2a_ins (.clk(clk), .rst(rst), .m2add_start(xor_start), .m2add_in_one(xor_one_in), .m2add_in_two(xor_two_in), .m2add_out(m2add_out), .m2add_rdy(m2add_rdy));
mod2p64_add_serial64b #(.BLOCK_SIZE(BLOCK_SIZE)) m2p64a_ins (.clk(clk), .rst(rst), .m2p64add_start(add_start), .m2p64add_in_one(add_one_in), .m2p64add_in_two(add_two_in), .m2p64add_out(m2p64add_out), .m2p64add_rdy(m2p64add_rdy));
//Substitution Permutation Mix-Column
sbpsmc_serial64b #(.BLOCK_SIZE(BLOCK_SIZE)) sbpsmc64b_ins (.clk(clk), .rst(rst), .sbpsmc_start(sbpsmc_start), .sbpsmc_in(sbpsmc_in), .sbpsmc_out(sbpsmc_out), .sbpsmc_rdy(sbpsmc_rdy));

//Block Outputs
always @ (posedge clk) begin
  if (rst == 1'b1) begin
    block_rdy <= 1'b0;
    block_out <= {BLOCK_SIZE{1'b0}};
  end
  else begin
    if (reg_enc_start == 1'b0) begin
      block_rdy <= 1'b0;
      block_out <= {BLOCK_SIZE{1'b0}};
    end
    else begin
      if (reg_block_rdy == 1'b1) begin
        block_rdy <= 1'b1;
        block_out <= round_out;
      end
    end
  end
end

endmodule

//KALYNA ENCRYPTION BLOCK - SERIAL - TWO ROUNDS IN ONE CLOCK CYCLE
module kalyna_enc_block_serial_2rnd # (parameter BLOCK_SIZE = 512, KEY_LENGTH = 512) (clk, rst, start, block_in, key_in, block_out, block_rdy);

input clk, rst, start;
input [BLOCK_SIZE-1:0] block_in;
input [KEY_LENGTH-1:0] key_in;
output reg [BLOCK_SIZE-1:0] block_out;
output reg block_rdy;

localparam rnd_cnt = (BLOCK_SIZE == KEY_LENGTH && BLOCK_SIZE == 128) ? 5'd10 : (BLOCK_SIZE == KEY_LENGTH && BLOCK_SIZE == 256) ? 5'd14 : (BLOCK_SIZE == KEY_LENGTH && BLOCK_SIZE == 512) ? 5'd18 : (BLOCK_SIZE != KEY_LENGTH && BLOCK_SIZE == 128) ? 5'd14 : 5'd18;

//Variables
reg [4:0] rnd_counter, rnd_index;
wire [BLOCK_SIZE-1:0] int_key, even_key, odd_key;
wire [BLOCK_SIZE-1:0] m2p64a_out, m2a0_out, m2a1_out, sb0_out, sb1_out, ps0_out, ps1_out, mc0_out, mc1_out;
reg [BLOCK_SIZE-1:0] rnd_key, fal_block_in, rnd_block_in, m2a0_reg;

//Counter
always @ (posedge clk) begin
  if (rst == 1'b1) begin
    rnd_counter <= 5'd0;
  end
  else begin
    if (start == 1'b0) begin
      rnd_counter <= 5'd0;
    end
    else begin
      if (rnd_counter <= rnd_cnt + 2'd2) begin
        rnd_counter <= rnd_counter + 2'd2;
      end
    end
  end
end
//rnd_index
always @ (*) begin
  if (rnd_counter > 5'd0) begin
    rnd_index = rnd_counter - 2'd2;
  end
  else begin
    rnd_index = 5'd0;
  end
end

//Registers
always @ (posedge clk) begin
  if (rst == 1'b1) begin
    block_rdy <= 1'b0;
    block_out <= {BLOCK_SIZE{1'b0}};
    m2a0_reg <= {{BLOCK_SIZE}{1'b0}};
  end
  else begin
    if (start == 1'b0) begin
      block_rdy <= 1'b0;
      block_out <= {BLOCK_SIZE{1'b0}};
      m2a0_reg <= {{BLOCK_SIZE}{1'b0}};
    end
    else begin
      m2a0_reg <= m2a0_out;
      if (rnd_index == rnd_cnt) begin
        block_out <= m2p64a_out;
        block_rdy <= 1'b1;
      end
      else begin
        block_out <= {BLOCK_SIZE{1'b0}};
        block_rdy <= 1'b0;
      end
    end
  end
end

//rnd_key and fal_block_in
always @ (*) begin
  if (rnd_index == 5'd0) begin
    rnd_key = even_key;
    fal_block_in = block_in;
  end
  else if (rnd_index == rnd_cnt) begin
    rnd_key = even_key;
    fal_block_in = mc1_out;
  end
  else begin
    rnd_key = {BLOCK_SIZE{1'b0}};
    fal_block_in = {BLOCK_SIZE{1'b0}};
  end
end

//rnd_block_in
always @ (*) begin
  if (rnd_index == 5'd0) begin
    rnd_block_in = m2p64a_out;
  end
  else begin
    rnd_block_in = m2a1_out;
  end
end

//Intermediate and Round Key
gen_int_key #(.BLOCK_SIZE(BLOCK_SIZE), .KEY_LENGTH(KEY_LENGTH)) gik_ins (.key_in(key_in), .int_key_out(int_key));
gen_even_rnd_key # (.BLOCK_SIZE(BLOCK_SIZE), .KEY_LENGTH(KEY_LENGTH)) gerk_ins (.key_in(key_in), .int_key_in(int_key), .rnd_num_in(rnd_index), .even_key_out(even_key));
gen_odd_rnd_key # (.BLOCK_SIZE(BLOCK_SIZE)) gork_ins (.even_key_in(even_key), .odd_key_out(odd_key));

//Transformations
mod2p64_add #(.BLOCK_SIZE(BLOCK_SIZE)) m2p64a_ins (.m2p64add_in_one(rnd_key), .m2p64add_in_two(fal_block_in), .m2p64add_out(m2p64a_out));
substitute_byte_foursbox #(.BLOCK_SIZE(BLOCK_SIZE)) sb_ins0 (.sb_in(rnd_block_in), .sb_out(sb0_out));
permute_state #(.BLOCK_SIZE(BLOCK_SIZE)) ps_ins0 (.ps_in(sb0_out), .ps_out(ps0_out));
mix_column #(.BLOCK_SIZE(BLOCK_SIZE)) mx_ins0 (.mc_in(ps0_out), .mc_out(mc0_out));
mod2_add #(.BLOCK_SIZE(BLOCK_SIZE)) m2a_ins0 (.m2add_in_one(odd_key), .m2add_in_two(mc0_out), .m2add_out(m2a0_out));
substitute_byte_foursbox #(.BLOCK_SIZE(BLOCK_SIZE)) sb_ins1 (.sb_in(m2a0_reg), .sb_out(sb1_out));
permute_state #(.BLOCK_SIZE(BLOCK_SIZE)) ps_ins1 (.ps_in(sb1_out), .ps_out(ps1_out));
mix_column #(.BLOCK_SIZE(BLOCK_SIZE)) mx_ins1 (.mc_in(ps1_out), .mc_out(mc1_out));
mod2_add #(.BLOCK_SIZE(BLOCK_SIZE)) m2a_ins1 (.m2add_in_one(even_key), .m2add_in_two(mc1_out), .m2add_out(m2a1_out));

endmodule

//KALYNA DECRYPTION BLOCK - PARALLEL
module kalyna_dec_block_parallel #(parameter BLOCK_SIZE = 512, parameter KEY_LENGTH = 512) (block_in, key_in, block_out);

input [BLOCK_SIZE-1:0] block_in;
input [KEY_LENGTH-1:0] key_in;
output [BLOCK_SIZE-1:0] block_out;

localparam rnd_cnt = (BLOCK_SIZE == KEY_LENGTH && BLOCK_SIZE == 128) ? 5'd10 : (BLOCK_SIZE == KEY_LENGTH && BLOCK_SIZE == 256) ? 5'd14 : (BLOCK_SIZE == KEY_LENGTH && BLOCK_SIZE == 512) ? 5'd18 : (BLOCK_SIZE != KEY_LENGTH && BLOCK_SIZE == 128) ? 5'd14 : 5'd18;

//Variables
wire [BLOCK_SIZE-1:0] int_key;
wire [BLOCK_SIZE-1:0] key_rnd_arr [rnd_cnt:0];
wire [BLOCK_SIZE-1:0] sb_rnd_arr [rnd_cnt:0];
wire [BLOCK_SIZE-1:0] pr_rnd_arr [rnd_cnt:0];
wire [BLOCK_SIZE-1:0] mx_rnd_arr [rnd_cnt:0];
wire [BLOCK_SIZE-1:0] a2_rnd_arr [rnd_cnt:0];
wire [BLOCK_SIZE-1:0] m2p64a_lrnd;

//Generate Intermediate Key
gen_int_key #(.BLOCK_SIZE(BLOCK_SIZE), .KEY_LENGTH(KEY_LENGTH)) gik_ins (.key_in(key_in), .int_key_out(int_key));

//Transformations
//Last Round
gen_even_rnd_key # (.BLOCK_SIZE(BLOCK_SIZE), .KEY_LENGTH(KEY_LENGTH)) gerk_ins_lr (.key_in(key_in), .int_key_in(int_key), .rnd_num_in(rnd_cnt), .even_key_out(key_rnd_arr[rnd_cnt]));
mod2p64_sub #(.BLOCK_SIZE(BLOCK_SIZE)) m2p64sub_ins_lr (.m2p64sub_in_one(block_in), .m2p64sub_in_two(key_rnd_arr[rnd_cnt]), .m2p64sub_out(a2_rnd_arr[rnd_cnt]));
inv_mix_column #(.BLOCK_SIZE(BLOCK_SIZE)) mx_ins_lr (.mc_in(a2_rnd_arr[rnd_cnt]), .mc_out(mx_rnd_arr[rnd_cnt]));
inv_permute_state #(.BLOCK_SIZE(BLOCK_SIZE)) ps_ins_lr (.ps_in(mx_rnd_arr[rnd_cnt]), .ps_out(pr_rnd_arr[rnd_cnt]));
inv_substitute_byte_foursbox #(.BLOCK_SIZE(BLOCK_SIZE)) sb_ins_lr (.sb_in(pr_rnd_arr[rnd_cnt]), .sb_out(sb_rnd_arr[rnd_cnt]));

//Round rnd_cnt-1 --- 2
genvar i;
generate
  for (i=rnd_cnt-2; i>0; i=i-2) begin
    parameter [4:0] NR = i;

    gen_even_rnd_key # (.BLOCK_SIZE(BLOCK_SIZE), .KEY_LENGTH(KEY_LENGTH)) gerk_ins (.key_in(key_in), .int_key_in(int_key), .rnd_num_in(NR), .even_key_out(key_rnd_arr[i]));
    gen_odd_rnd_key # (.BLOCK_SIZE(BLOCK_SIZE)) gork_ins (.even_key_in(key_rnd_arr[i]), .odd_key_out(key_rnd_arr[i+1]));
    
    mod2_add #(.BLOCK_SIZE(BLOCK_SIZE)) m2a_ins_odd (.m2add_in_one(key_rnd_arr[i+1]), .m2add_in_two(sb_rnd_arr[i+2]), .m2add_out(a2_rnd_arr[i+1]));
    inv_mix_column #(.BLOCK_SIZE(BLOCK_SIZE)) mx_ins_odd (.mc_in(a2_rnd_arr[i+1]), .mc_out(mx_rnd_arr[i+1]));
    inv_permute_state #(.BLOCK_SIZE(BLOCK_SIZE)) ps_ins_odd (.ps_in(mx_rnd_arr[i+1]), .ps_out(pr_rnd_arr[i+1]));
    inv_substitute_byte_foursbox #(.BLOCK_SIZE(BLOCK_SIZE)) sb_ins_odd (.sb_in(pr_rnd_arr[i+1]), .sb_out(sb_rnd_arr[i+1]));

    mod2_add #(.BLOCK_SIZE(BLOCK_SIZE)) m2a_ins_even (.m2add_in_one(key_rnd_arr[i]), .m2add_in_two(sb_rnd_arr[i+1]), .m2add_out(a2_rnd_arr[i]));
    inv_mix_column #(.BLOCK_SIZE(BLOCK_SIZE)) mx_ins_even (.mc_in(a2_rnd_arr[i]), .mc_out(mx_rnd_arr[i]));
    inv_permute_state #(.BLOCK_SIZE(BLOCK_SIZE)) ps_ins_even (.ps_in(mx_rnd_arr[i]), .ps_out(pr_rnd_arr[i]));
    inv_substitute_byte_foursbox #(.BLOCK_SIZE(BLOCK_SIZE)) sb_ins_even (.sb_in(pr_rnd_arr[i]), .sb_out(sb_rnd_arr[i]));
  end  
endgenerate

//Round 1-0
gen_even_rnd_key # (.BLOCK_SIZE(BLOCK_SIZE), .KEY_LENGTH(KEY_LENGTH)) gerk_ins0 (.key_in(key_in), .int_key_in(int_key), .rnd_num_in(5'd0), .even_key_out(key_rnd_arr[0]));
gen_odd_rnd_key # (.BLOCK_SIZE(BLOCK_SIZE)) gork_ins1 (.even_key_in(key_rnd_arr[0]), .odd_key_out(key_rnd_arr[1]));
    
mod2_add #(.BLOCK_SIZE(BLOCK_SIZE)) m2a_ins1 (.m2add_in_one(key_rnd_arr[1]), .m2add_in_two(sb_rnd_arr[2]), .m2add_out(a2_rnd_arr[1]));
inv_mix_column #(.BLOCK_SIZE(BLOCK_SIZE)) mx_ins1 (.mc_in(a2_rnd_arr[1]), .mc_out(mx_rnd_arr[1]));
inv_permute_state #(.BLOCK_SIZE(BLOCK_SIZE)) ps_ins1 (.ps_in(mx_rnd_arr[1]), .ps_out(pr_rnd_arr[1]));
inv_substitute_byte_foursbox #(.BLOCK_SIZE(BLOCK_SIZE)) sb_ins1 (.sb_in(pr_rnd_arr[1]), .sb_out(sb_rnd_arr[1]));

mod2p64_sub #(.BLOCK_SIZE(BLOCK_SIZE)) m2p64sub_ins0 (.m2p64sub_in_one(sb_rnd_arr[1]), .m2p64sub_in_two(key_rnd_arr[0]), .m2p64sub_out(m2p64a_lrnd));

assign block_out = m2p64a_lrnd;

endmodule

//KALYNA DECRYPTION BLOCK - SERIAL - ONE OPERATION in ONE CLOCK CYCLE 
module kalyna_dec_block_serial_oboc #(parameter BLOCK_SIZE = 128, parameter KEY_LENGTH = 128) (clk, rst, start, block_in, key_in, block_out, block_rdy);

input clk, rst, start;
input [BLOCK_SIZE-1:0] block_in;
input [KEY_LENGTH-1:0] key_in;
output reg [BLOCK_SIZE-1:0] block_out;
output reg block_rdy;

//Local parameters
localparam bs_m8 = BLOCK_SIZE - 8;
localparam bs_d16 = BLOCK_SIZE/16;
localparam the_lr = (BLOCK_SIZE/4+24);
localparam rnd_cnt = (BLOCK_SIZE == KEY_LENGTH && BLOCK_SIZE == 128) ? 5'd10 : (BLOCK_SIZE == KEY_LENGTH && BLOCK_SIZE == 256) ? 5'd14 : (BLOCK_SIZE == KEY_LENGTH && BLOCK_SIZE == 512) ? 5'd18 : (BLOCK_SIZE != KEY_LENGTH && BLOCK_SIZE == 128) ? 5'd14 : 5'd18;

//Variables
reg [4:0] rnd_num;
reg [5:0] curr_state;
reg [KEY_LENGTH-1:0] trans_in;
reg reg_block_rdy, reg_dec_start;
reg [BLOCK_SIZE-1:0] key_alfa, key_omega, add_one_in, add_two_in, int_key, shft_tmv, trans_key_in, tmv_key, round_out;
wire [BLOCK_SIZE-1:0] int_key_in, the_tmv;
wire [7:0] the_const = (BLOCK_SIZE+KEY_LENGTH)/64 + 1;
wire [BLOCK_SIZE-1:0] m2add_out, m2p64add_out, sbpsmc_out, m2p64sub_out, inv_sbpsmc_out;

//Input to the intermediate key transformation
assign int_key_in = {the_const, {bs_m8{1'b0}}};

//Alfa and Omega Keys for the intermediate key transformation
always @ (*) begin
  if (BLOCK_SIZE == KEY_LENGTH) begin
    key_alfa = key_in;
    key_omega = key_in;
  end
  else begin
    key_alfa = key_in[KEY_LENGTH-1:KEY_LENGTH/2];
    key_omega = key_in[KEY_LENGTH/2-1:0];
  end
end

//Generation of the TMV signal and its shifted version
assign the_tmv= {bs_d16{16'h0100}};
always @ (*) begin
  case (rnd_num)
    5'd0    : shft_tmv = the_tmv;
    5'd2    : shft_tmv = {the_tmv[BLOCK_SIZE-2:0],  1'd0};
    5'd4    : shft_tmv = {the_tmv[BLOCK_SIZE-3:0],  2'd0};
    5'd6    : shft_tmv = {the_tmv[BLOCK_SIZE-4:0],  3'd0};
    5'd8    : shft_tmv = {the_tmv[BLOCK_SIZE-5:0],  4'd0};
    5'd10   : shft_tmv = {the_tmv[BLOCK_SIZE-6:0],  5'd0};
    5'd12   : shft_tmv = {the_tmv[BLOCK_SIZE-7:0],  6'd0};
    5'd14   : shft_tmv = {the_tmv[BLOCK_SIZE-8:0],  7'd0};
    5'd16   : shft_tmv = {the_tmv[BLOCK_SIZE-9:0],  7'd0, 1'b1};
    5'd18   : shft_tmv = {the_tmv[BLOCK_SIZE-10:0], 7'd0, 1'b1, 1'b0}; //Last two lines are due to the conflict between rotate and shift
    default : shft_tmv = the_tmv;
  endcase
end

//Generation of the input to the transformations
always @ (*) begin
  if (BLOCK_SIZE == KEY_LENGTH) begin
    if (BLOCK_SIZE == 128) begin
      case (rnd_num) 
        5'd0    : trans_in = key_in;
        5'd2    : trans_in = {key_in[63:0], key_in[127:64]};
        5'd4    : trans_in = key_in;
        5'd6    : trans_in = {key_in[63:0], key_in[127:64]};
        5'd8    : trans_in = key_in;
        5'd10   : trans_in = {key_in[63:0], key_in[127:64]};
        default : trans_in = key_in;
      endcase
    end
    else if (BLOCK_SIZE == 256) begin
      case (rnd_num) 
        5'd0    : trans_in = key_in;
        5'd2    : trans_in = {key_in[191:0], key_in[255:192]};
        5'd4    : trans_in = {key_in[127:0], key_in[255:128]};
        5'd6    : trans_in = {key_in[63:0],  key_in[255:64]};
        5'd8    : trans_in = key_in;
        5'd10   : trans_in = {key_in[191:0], key_in[255:192]};
        5'd12   : trans_in = {key_in[127:0], key_in[255:128]};
        5'd14   : trans_in = {key_in[63:0],  key_in[255:64]};
        default : trans_in = key_in;
      endcase
    end
    else begin
      case (rnd_num) 
        5'd0    : trans_in = key_in;
        5'd2    : trans_in = {key_in[447:0], key_in[511:448]};
        5'd4    : trans_in = {key_in[383:0], key_in[511:384]};
        5'd6    : trans_in = {key_in[319:0], key_in[511:320]};
        5'd8    : trans_in = {key_in[255:0], key_in[511:256]};
        5'd10   : trans_in = {key_in[191:0], key_in[511:192]};
        5'd12   : trans_in = {key_in[127:0], key_in[511:128]};
        5'd14   : trans_in = {key_in[63:0],  key_in[511:64]};
        5'd16   : trans_in = key_in;
        5'd18   : trans_in = {key_in[447:0], key_in[511:448]};
        default : trans_in = key_in;
      endcase
    end
  end
  else begin
    if (BLOCK_SIZE == 128) begin
      case (rnd_num) 
        5'd0    : trans_in = key_in;
        5'd2    : trans_in = key_in;
        5'd4    : trans_in = {key_in[191:0], key_in[255:192]};
        5'd6    : trans_in = {key_in[191:0], key_in[255:192]};
        5'd8    : trans_in = {key_in[127:0], key_in[255:128]};
        5'd10   : trans_in = {key_in[127:0], key_in[255:128]};
        5'd12   : trans_in = {key_in[63:0],  key_in[255:64]};
        5'd14   : trans_in = {key_in[63:0],  key_in[255:64]};
        default : trans_in = key_in;
      endcase
    end
    else begin
      case (rnd_num) 
        5'd0    : trans_in = key_in;
        5'd2    : trans_in = key_in;
        5'd4    : trans_in = {key_in[447:0], key_in[511:448]};
        5'd6    : trans_in = {key_in[447:0], key_in[511:448]};
        5'd8    : trans_in = {key_in[383:0], key_in[511:384]};
        5'd10   : trans_in = {key_in[383:0], key_in[511:384]};
        5'd12   : trans_in = {key_in[319:0], key_in[511:320]};
        5'd14   : trans_in = {key_in[319:0], key_in[511:320]};
        5'd16   : trans_in = {key_in[255:0], key_in[511:256]};
        5'd18   : trans_in = {key_in[255:0], key_in[511:256]};
        default : trans_in = key_in;
      endcase
    end
  end
end
always @ (*) begin
  if (BLOCK_SIZE == KEY_LENGTH) begin
    trans_key_in = trans_in;
  end
  else begin
    case (rnd_num) 
      5'd0    : trans_key_in = trans_in[KEY_LENGTH-1:KEY_LENGTH-BLOCK_SIZE];
      5'd2    : trans_key_in = trans_in[BLOCK_SIZE-1:0];
      5'd4    : trans_key_in = trans_in[KEY_LENGTH-1:KEY_LENGTH-BLOCK_SIZE]; 
      5'd6    : trans_key_in = trans_in[BLOCK_SIZE-1:0]; 
      5'd8    : trans_key_in = trans_in[KEY_LENGTH-1:KEY_LENGTH-BLOCK_SIZE]; 
      5'd10   : trans_key_in = trans_in[BLOCK_SIZE-1:0]; 
      5'd12   : trans_key_in = trans_in[KEY_LENGTH-1:KEY_LENGTH-BLOCK_SIZE]; 
      5'd14   : trans_key_in = trans_in[BLOCK_SIZE-1:0]; 
      5'd16   : trans_key_in = trans_in[KEY_LENGTH-1:KEY_LENGTH-BLOCK_SIZE]; 
      5'd18   : trans_key_in = trans_in[BLOCK_SIZE-1:0]; 
      default : trans_key_in = trans_in[BLOCK_SIZE-1:0]; 
    endcase
  end
end

//The reg_dec_start signal indicates that the encryption process is started
always @ (posedge clk) begin
  if (rst == 1'b1) begin
    reg_dec_start <= 1'b0;
  end
  else begin
    if (block_rdy == 1'b1) begin
      reg_dec_start <= 1'b0;
    end
    else begin
      if (start == 1'b1) begin
        reg_dec_start <= 1'b1;
      end
    end
  end
end

//Block inputs in each state  
always @ (posedge clk) begin
  if (rst == 1'b1) begin
    rnd_num <= 5'd0;
    curr_state <= 6'd0;
    reg_block_rdy <= 1'b0;
    tmv_key <= {BLOCK_SIZE{1'b0}};
    int_key <= {BLOCK_SIZE{1'b0}};
    round_out <= {BLOCK_SIZE{1'b0}};
    add_one_in <= {BLOCK_SIZE{1'b0}};
    add_two_in <= {BLOCK_SIZE{1'b0}};
  end
  else begin
    if (reg_dec_start == 1'b0) begin
      rnd_num <= 5'd0;
      curr_state <= 6'd0;
      reg_block_rdy <= 1'b0;
      tmv_key <= {BLOCK_SIZE{1'b0}};
      int_key <= {BLOCK_SIZE{1'b0}};
      round_out <= {BLOCK_SIZE{1'b0}};
      add_one_in <= {BLOCK_SIZE{1'b0}};
      add_two_in <= {BLOCK_SIZE{1'b0}};
    end
    else begin
      case (curr_state)
        //Intermediate key generattion starts here
        6'd0 : begin
          //ADD - INTKEY
          add_one_in <= int_key_in;
          add_two_in <= key_alfa;

          curr_state <= 6'd1;
        end
        6'd1 : begin
          //SPLT - INTKEY
          add_one_in <= m2p64add_out;

          curr_state <= 6'd2;
        end
        6'd2 : begin
          //XOR - INTKEY
          add_one_in <= key_omega;
          add_two_in <= sbpsmc_out;

          curr_state <= 6'd3;
        end
        6'd3 : begin
          //SPLT - INTKEY
          add_one_in <= m2add_out;
          
          curr_state <= 6'd4;
        end
        6'd4 : begin
          //ADD - INTKEY
          add_one_in <= key_alfa;
          add_two_in <= sbpsmc_out;

          curr_state <= 6'd5;
        end
        6'd5 : begin
          //RND - KEY10
          rnd_num <= rnd_cnt;

          //SPLT - INTKEY
          add_one_in <= m2p64add_out;
          
          curr_state <= 6'd6;
        end
        //Intermediate key generation ends and round 10 key generation starts here
        6'd6 : begin
          int_key <= sbpsmc_out;

          //ADD - KEY10
          add_one_in <= sbpsmc_out;
          add_two_in <= shft_tmv;

          curr_state <= 6'd7;
        end
        6'd7 : begin
          tmv_key <= m2p64add_out;

          //ADD - KEY10
          add_one_in <= m2p64add_out;
          add_two_in <= trans_key_in;

          curr_state <= 6'd8;
        end
        6'd8 : begin
          //SPLT - KEY10
          add_one_in <= m2p64add_out;

          curr_state <= 6'd9;
        end
        6'd9 : begin
          //XOR - KEY10
          add_one_in <= tmv_key;
          add_two_in <= sbpsmc_out;

          curr_state <= 6'd10;
        end
        6'd10 : begin
          //SPLT - KEY10
          add_one_in <= m2add_out;

          curr_state <= 6'd11;
        end
        6'd11 : begin
          //ADD - KEY10
          add_one_in <= tmv_key;
          add_two_in <= sbpsmc_out;

          curr_state <= 6'd12;
        end
        //Round 10 key generation ends here and Round 10 operations start here
        6'd12 : begin
          tmv_key <= m2p64add_out;
          //SUB - RND10
          add_one_in <= block_in;
          add_two_in <= m2p64add_out;

          curr_state <= 6'd13;
        end
        6'd13 : begin
          //RND - KEY8
          rnd_num <= rnd_num - 5'd2;
          //INV SPLT - RND10
          add_one_in <= m2p64sub_out;

          curr_state <= 6'd14;
        end
        //Round 10 operations end here and Round 8 key operations start here
        6'd14 : begin
          round_out <= inv_sbpsmc_out;
          //ADD - KEY8
          add_one_in <= int_key;
          add_two_in <= shft_tmv;

          curr_state <= 6'd15;
        end
        6'd15 : begin
          tmv_key <= m2p64add_out;

          //ADD - KEY8
          add_one_in <= m2p64add_out;
          add_two_in <= trans_key_in;

          curr_state <= 6'd16;
        end
        6'd16 : begin
          //SPLT - KEY8
          add_one_in <= m2p64add_out;

          curr_state <= 6'd17;
        end
        6'd17 : begin
          //XOR - KEY8
          add_one_in <= tmv_key;
          add_two_in <= sbpsmc_out;

          curr_state <= 6'd18;
        end
        6'd18 : begin
          //SPLT - KEY8
          add_one_in <= m2add_out;

          curr_state <= 6'd19;
        end
        6'd19 : begin
          //ADD - KEY8
          add_one_in <= tmv_key;
          add_two_in <= sbpsmc_out;

          curr_state <= 6'd20;
        end
        //Round 8 key generation ends here and Round 9-8 operations start here
        6'd20 : begin
          tmv_key <= m2p64add_out;
          //XOR - RND9
          add_one_in <= round_out;
          add_two_in <= {m2p64add_out[BLOCK_SIZE-1-the_lr:0], m2p64add_out[BLOCK_SIZE-1:BLOCK_SIZE-the_lr]};

          curr_state <= 6'd21;
        end
        6'd21 : begin
          //INV SPLT - RND9
          add_one_in <= m2add_out;

          curr_state <= 6'd22;
        end
        6'd22 : begin
          //XOR - RND8
          add_one_in <= inv_sbpsmc_out;
          add_two_in <= tmv_key;

          curr_state <= 6'd23;
        end
        6'd23 : begin
          //RND - KEY6
          rnd_num <= rnd_num - 5'd2;
          //INV SPLT - RND8
          add_one_in <= m2add_out;

          curr_state <= 6'd24;
        end
        //Round 9-8 operations end here and Round 6 key operations start here
        6'd24 : begin
          round_out <= inv_sbpsmc_out;
          //ADD - KEY6
          add_one_in <= int_key;
          add_two_in <= shft_tmv;

          curr_state <= 6'd25;
        end
        6'd25 : begin
          tmv_key <= m2p64add_out;

          //ADD - KEY6
          add_one_in <= m2p64add_out;
          add_two_in <= trans_key_in;

          curr_state <= 6'd26;
        end
        6'd26 : begin
          //SPLT - KEY6
          add_one_in <= m2p64add_out;

          curr_state <= 6'd27;
        end
        6'd27 : begin
          //XOR - KEY6
          add_one_in <= tmv_key;
          add_two_in <= sbpsmc_out;

          curr_state <= 6'd28;
        end
        6'd28 : begin
          //SPLT - KEY6
          add_one_in <= m2add_out;

          curr_state <= 6'd29;
        end
        6'd29 : begin
          //ADD - KEY6
          add_one_in <= tmv_key;
          add_two_in <= sbpsmc_out;

          curr_state <= 6'd30;
        end
        //Round 6 key generation ends here and Round 7-6 operations start here
        6'd30 : begin
          tmv_key <= m2p64add_out;
          //XOR - RND7
          add_one_in <= round_out;
          add_two_in <= {m2p64add_out[BLOCK_SIZE-1-the_lr:0], m2p64add_out[BLOCK_SIZE-1:BLOCK_SIZE-the_lr]};

          curr_state <= 6'd31;
        end
        6'd31 : begin
          //INV SPLT - RND7
          add_one_in <= m2add_out;

          curr_state <= 6'd32;
        end
        6'd32 : begin
          //XOR - RND6
          add_one_in <= inv_sbpsmc_out;
          add_two_in <= tmv_key;

          curr_state <= 6'd33;
        end
        6'd33 : begin
          //RND - KEY4
          rnd_num <= rnd_num - 5'd2;
          //INV SPLT - RND6
          add_one_in <= m2add_out;

          curr_state <= 6'd34;
        end
        //Round 7-6 operations end here and Round 4 key operations start here
        6'd34 : begin
          round_out <= inv_sbpsmc_out;
          //ADD - KEY4
          add_one_in <= int_key;
          add_two_in <= shft_tmv;

          curr_state <= 6'd35;
        end
        6'd35 : begin
          tmv_key <= m2p64add_out;

          //ADD - KEY4
          add_one_in <= m2p64add_out;
          add_two_in <= trans_key_in;

          curr_state <= 6'd36;
        end
        6'd36 : begin
          //SPLT - KEY4
          add_one_in <= m2p64add_out;

          curr_state <= 6'd37;
        end
        6'd37 : begin
          //XOR - KEY4
          add_one_in <= tmv_key;
          add_two_in <= sbpsmc_out;

          curr_state <= 6'd38;
        end
        6'd38 : begin
          //SPLT - KEY4
          add_one_in <= m2add_out;

          curr_state <= 6'd39;
        end
        6'd39 : begin
          //ADD - KEY4
          add_one_in <= tmv_key;
          add_two_in <= sbpsmc_out;

          curr_state <= 6'd40;
        end
        //Round 4 key generation ends here and Round 5-4 operations start here
        6'd40 : begin
          tmv_key <= m2p64add_out;
          //XOR - RND5
          add_one_in <= round_out;
          add_two_in <= {m2p64add_out[BLOCK_SIZE-1-the_lr:0], m2p64add_out[BLOCK_SIZE-1:BLOCK_SIZE-the_lr]};

          curr_state <= 6'd41;
        end
        6'd41 : begin
          //INV SPLT - RND5
          add_one_in <= m2add_out;

          curr_state <= 6'd42;
        end
        6'd42 : begin
          //XOR - RND4
          add_one_in <= inv_sbpsmc_out;
          add_two_in <= tmv_key;

          curr_state <= 6'd43;
        end
        6'd43 : begin
          //RND - KEY2
          rnd_num <= rnd_num - 5'd2;
          //INV SPLT - RND4
          add_one_in <= m2add_out;

          curr_state <= 6'd44;
        end
        //Round 5-4 operations end here and Round 2 key operations start here
        6'd44 : begin
          round_out <= inv_sbpsmc_out;
          //ADD - KEY2
          add_one_in <= int_key;
          add_two_in <= shft_tmv;

          curr_state <= 6'd45;
        end
        6'd45 : begin
          tmv_key <= m2p64add_out;

          //ADD - KEY2
          add_one_in <= m2p64add_out;
          add_two_in <= trans_key_in;

          curr_state <= 6'd46;
        end
        6'd46 : begin
          //SPLT - KEY2
          add_one_in <= m2p64add_out;

          curr_state <= 6'd47;
        end
        6'd47 : begin
          //XOR - KEY2
          add_one_in <= tmv_key;
          add_two_in <= sbpsmc_out;

          curr_state <= 6'd48;
        end
        6'd48 : begin
          //SPLT - KEY2
          add_one_in <= m2add_out;

          curr_state <= 6'd49;
        end
        6'd49 : begin
          //ADD - KEY2
          add_one_in <= tmv_key;
          add_two_in <= sbpsmc_out;

          curr_state <= 6'd50;
        end
        //Round 2 key generation ends here and Round 3-2 operations start here
        6'd50 : begin
          tmv_key <= m2p64add_out;
          //XOR - RND3
          add_one_in <= round_out;
          add_two_in <= {m2p64add_out[BLOCK_SIZE-1-the_lr:0], m2p64add_out[BLOCK_SIZE-1:BLOCK_SIZE-the_lr]};

          curr_state <= 6'd51;
        end
        6'd51 : begin
          //INV SPLT - RND3
          add_one_in <= m2add_out;

          curr_state <= 6'd52;
        end
        6'd52 : begin
          //XOR - RND2
          add_one_in <= inv_sbpsmc_out;
          add_two_in <= tmv_key;

          curr_state <= 6'd53;
        end
        6'd53 : begin
          //RND - KEY0
          rnd_num <= rnd_num - 5'd2;
          //INV SPLT - RND2
          add_one_in <= m2add_out;

          curr_state <= 6'd54;
        end
        //Round 3-2 operations end here and Round 0 key operations start here
        6'd54 : begin
          round_out <= inv_sbpsmc_out;
          //ADD - KEY0
          add_one_in <= int_key;
          add_two_in <= shft_tmv;

          if (rnd_cnt == 5'd10) begin
            curr_state <= 6'd55;
          end
          else if (rnd_cnt == 5'd14) begin
            if (rnd_num == 5'd0) begin
              curr_state <= 6'd55;
            end
            else begin
              curr_state <= 6'd35;
            end
          end
          else begin
            if (rnd_num == 5'd0) begin
              curr_state <= 6'd55;
            end
            else begin
              curr_state <= 6'd15;
            end
          end
        end
        6'd55 : begin
          tmv_key <= m2p64add_out;

          //ADD - KEY0
          add_one_in <= m2p64add_out;
          add_two_in <= trans_key_in;

          curr_state <= 6'd56;
        end
        6'd56 : begin
          //SPLT - KEY0
          add_one_in <= m2p64add_out;

          curr_state <= 6'd57;
        end
        6'd57 : begin
          //XOR - KEY0
          add_one_in <= tmv_key;
          add_two_in <= sbpsmc_out;

          curr_state <= 6'd58;
        end
        6'd58 : begin
          //SPLT - KEY0
          add_one_in <= m2add_out;

          curr_state <= 6'd59;
        end
        6'd59 : begin
          //ADD - KEY0
          add_one_in <= tmv_key;
          add_two_in <= sbpsmc_out;

          curr_state <= 6'd60;
        end
        //Round 0 key generation ends here and Round 1-0 operations start here
        6'd60 : begin
          tmv_key <= m2p64add_out;
          //XOR - RND1
          add_one_in <= round_out;
          add_two_in <= {m2p64add_out[BLOCK_SIZE-1-the_lr:0], m2p64add_out[BLOCK_SIZE-1:BLOCK_SIZE-the_lr]};

          curr_state <= 6'd61;
        end
        6'd61 : begin
          //INV SPLT - RND1
          add_one_in <= m2add_out;

          curr_state <= 6'd62;
        end
        6'd62 : begin
          //SUB - RND0
          add_one_in <= inv_sbpsmc_out;
          add_two_in <= tmv_key;

          curr_state <= 6'd63;
        end
        6'd63 : begin
          round_out <= m2p64sub_out;
          reg_block_rdy <= 1'b1;

          curr_state <= 6'd0;
        end
        default : begin
          rnd_num <= 5'd0;
          curr_state <= 6'd0;
          reg_block_rdy <= 1'b0;
          tmv_key <= {BLOCK_SIZE{1'b0}};
          int_key <= {BLOCK_SIZE{1'b0}};
          round_out <= {BLOCK_SIZE{1'b0}};
          add_one_in <= {BLOCK_SIZE{1'b0}};
          add_two_in <= {BLOCK_SIZE{1'b0}};
        end
      endcase
    end
  end
end

//Additions
mod2_add #(.BLOCK_SIZE(BLOCK_SIZE)) m2a_ins (.m2add_in_one(add_one_in), .m2add_in_two(add_two_in), .m2add_out(m2add_out));
mod2p64_add #(.BLOCK_SIZE(BLOCK_SIZE)) m2p64a_ins (.m2p64add_in_one(add_one_in), .m2p64add_in_two(add_two_in), .m2p64add_out(m2p64add_out));
//Substitution Permutation Mix-Column
sbpsmc #(.BLOCK_SIZE(BLOCK_SIZE)) sbpsmc64b_ins (.sbpsmc_in(add_one_in), .sbpsmc_out(sbpsmc_out));
//Inverse Addition
mod2p64_sub #(.BLOCK_SIZE(BLOCK_SIZE)) inv_m2p64a_ins (.m2p64sub_in_one(add_one_in), .m2p64sub_in_two(add_two_in), .m2p64sub_out(m2p64sub_out));
//Inverse Substitution Permutation Mix-Column
inv_sbpsmc #(.BLOCK_SIZE(BLOCK_SIZE)) inv_sbpsmc64b_ins (.sbpsmc_in(add_one_in), .sbpsmc_out(inv_sbpsmc_out));

//Block Outputs
always @ (posedge clk) begin
  if (rst == 1'b1) begin
    block_rdy <= 1'b0;
    block_out <= {BLOCK_SIZE{1'b0}};
  end
  else begin
    if (reg_dec_start == 1'b0) begin
      block_rdy <= 1'b0;
      block_out <= {BLOCK_SIZE{1'b0}};
    end
    else begin
      if (reg_block_rdy == 1'b1) begin
        block_rdy <= 1'b1;
        block_out <= round_out;
      end
    end
  end
end

endmodule

//KALYNA DECRYPTION BLOCK - SERIAL - ONE 64-bit OPERATION in ONE CLOCK CYCLE 
module kalyna_dec_block_serial64b_oboc #(parameter BLOCK_SIZE = 128, parameter KEY_LENGTH = 128) (clk, rst, start, block_in, key_in, block_out, block_rdy);

input clk, rst, start;
input [BLOCK_SIZE-1:0] block_in;
input [KEY_LENGTH-1:0] key_in;
output reg [BLOCK_SIZE-1:0] block_out;
output reg block_rdy;

//Local parameters
localparam bs_m8 = BLOCK_SIZE - 8;
localparam bs_d16 = BLOCK_SIZE/16;
localparam the_lr = (BLOCK_SIZE/4+24);
localparam rnd_cnt = (BLOCK_SIZE == KEY_LENGTH && BLOCK_SIZE == 128) ? 5'd10 : (BLOCK_SIZE == KEY_LENGTH && BLOCK_SIZE == 256) ? 5'd14 : (BLOCK_SIZE == KEY_LENGTH && BLOCK_SIZE == 512) ? 5'd18 : (BLOCK_SIZE != KEY_LENGTH && BLOCK_SIZE == 128) ? 5'd14 : 5'd18;

//Variables
reg [4:0] rnd_num;
reg [5:0] curr_state;
reg [KEY_LENGTH-1:0] trans_in;
reg xor_start, add_start, sbpsmc_start, reg_block_rdy, reg_dec_start;
reg [BLOCK_SIZE-1:0] key_alfa, key_omega, add_one_in, add_two_in, int_key, shft_tmv, trans_key_in, tmv_key, round_out;
wire [BLOCK_SIZE-1:0] int_key_in, the_tmv;
wire [7:0] the_const = (BLOCK_SIZE+KEY_LENGTH)/64 + 1;
wire m2add_rdy, m2p64add_rdy, sbpsmc_rdy, m2p64sub_rdy, inv_sbpsmc_rdy;
wire [BLOCK_SIZE-1:0] m2add_out, m2p64add_out, sbpsmc_out, m2p64sub_out, inv_sbpsmc_out;

//Input to the intermediate key transformation
assign int_key_in = {the_const, {bs_m8{1'b0}}};

//Alfa and Omega Keys for the intermediate key transformation
always @ (*) begin
  if (BLOCK_SIZE == KEY_LENGTH) begin
    key_alfa = key_in;
    key_omega = key_in;
  end
  else begin
    key_alfa = key_in[KEY_LENGTH-1:KEY_LENGTH/2];
    key_omega = key_in[KEY_LENGTH/2-1:0];
  end
end

//Generation of the TMV signal and its shifted version
assign the_tmv= {bs_d16{16'h0100}};
always @ (*) begin
  case (rnd_num)
    5'd0    : shft_tmv = the_tmv;
    5'd2    : shft_tmv = {the_tmv[BLOCK_SIZE-2:0],  1'd0};
    5'd4    : shft_tmv = {the_tmv[BLOCK_SIZE-3:0],  2'd0};
    5'd6    : shft_tmv = {the_tmv[BLOCK_SIZE-4:0],  3'd0};
    5'd8    : shft_tmv = {the_tmv[BLOCK_SIZE-5:0],  4'd0};
    5'd10   : shft_tmv = {the_tmv[BLOCK_SIZE-6:0],  5'd0};
    5'd12   : shft_tmv = {the_tmv[BLOCK_SIZE-7:0],  6'd0};
    5'd14   : shft_tmv = {the_tmv[BLOCK_SIZE-8:0],  7'd0};
    5'd16   : shft_tmv = {the_tmv[BLOCK_SIZE-9:0],  7'd0, 1'b1};
    5'd18   : shft_tmv = {the_tmv[BLOCK_SIZE-10:0], 7'd0, 1'b1, 1'b0}; //Last two lines are due to the conflict between rotate and shift
    default : shft_tmv = the_tmv;
  endcase
end

//Generation of the input to the transformations
always @ (*) begin
  if (BLOCK_SIZE == KEY_LENGTH) begin
    if (BLOCK_SIZE == 128) begin
      case (rnd_num) 
        5'd0    : trans_in = key_in;
        5'd2    : trans_in = {key_in[63:0], key_in[127:64]};
        5'd4    : trans_in = key_in;
        5'd6    : trans_in = {key_in[63:0], key_in[127:64]};
        5'd8    : trans_in = key_in;
        5'd10   : trans_in = {key_in[63:0], key_in[127:64]};
        default : trans_in = key_in;
      endcase
    end
    else if (BLOCK_SIZE == 256) begin
      case (rnd_num) 
        5'd0    : trans_in = key_in;
        5'd2    : trans_in = {key_in[191:0], key_in[255:192]};
        5'd4    : trans_in = {key_in[127:0], key_in[255:128]};
        5'd6    : trans_in = {key_in[63:0],  key_in[255:64]};
        5'd8    : trans_in = key_in;
        5'd10   : trans_in = {key_in[191:0], key_in[255:192]};
        5'd12   : trans_in = {key_in[127:0], key_in[255:128]};
        5'd14   : trans_in = {key_in[63:0],  key_in[255:64]};
        default : trans_in = key_in;
      endcase
    end
    else begin
      case (rnd_num) 
        5'd0    : trans_in = key_in;
        5'd2    : trans_in = {key_in[447:0], key_in[511:448]};
        5'd4    : trans_in = {key_in[383:0], key_in[511:384]};
        5'd6    : trans_in = {key_in[319:0], key_in[511:320]};
        5'd8    : trans_in = {key_in[255:0], key_in[511:256]};
        5'd10   : trans_in = {key_in[191:0], key_in[511:192]};
        5'd12   : trans_in = {key_in[127:0], key_in[511:128]};
        5'd14   : trans_in = {key_in[63:0],  key_in[511:64]};
        5'd16   : trans_in = key_in;
        5'd18   : trans_in = {key_in[447:0], key_in[511:448]};
        default : trans_in = key_in;
      endcase
    end
  end
  else begin
    if (BLOCK_SIZE == 128) begin
      case (rnd_num) 
        5'd0    : trans_in = key_in;
        5'd2    : trans_in = key_in;
        5'd4    : trans_in = {key_in[191:0], key_in[255:192]};
        5'd6    : trans_in = {key_in[191:0], key_in[255:192]};
        5'd8    : trans_in = {key_in[127:0], key_in[255:128]};
        5'd10   : trans_in = {key_in[127:0], key_in[255:128]};
        5'd12   : trans_in = {key_in[63:0],  key_in[255:64]};
        5'd14   : trans_in = {key_in[63:0],  key_in[255:64]};
        default : trans_in = key_in;
      endcase
    end
    else begin
      case (rnd_num) 
        5'd0    : trans_in = key_in;
        5'd2    : trans_in = key_in;
        5'd4    : trans_in = {key_in[447:0], key_in[511:448]};
        5'd6    : trans_in = {key_in[447:0], key_in[511:448]};
        5'd8    : trans_in = {key_in[383:0], key_in[511:384]};
        5'd10   : trans_in = {key_in[383:0], key_in[511:384]};
        5'd12   : trans_in = {key_in[319:0], key_in[511:320]};
        5'd14   : trans_in = {key_in[319:0], key_in[511:320]};
        5'd16   : trans_in = {key_in[255:0], key_in[511:256]};
        5'd18   : trans_in = {key_in[255:0], key_in[511:256]};
        default : trans_in = key_in;
      endcase
    end
  end
end
always @ (*) begin
  if (BLOCK_SIZE == KEY_LENGTH) begin
    trans_key_in = trans_in;
  end
  else begin
    case (rnd_num) 
      5'd0    : trans_key_in = trans_in[KEY_LENGTH-1:KEY_LENGTH-BLOCK_SIZE];
      5'd2    : trans_key_in = trans_in[BLOCK_SIZE-1:0];
      5'd4    : trans_key_in = trans_in[KEY_LENGTH-1:KEY_LENGTH-BLOCK_SIZE]; 
      5'd6    : trans_key_in = trans_in[BLOCK_SIZE-1:0]; 
      5'd8    : trans_key_in = trans_in[KEY_LENGTH-1:KEY_LENGTH-BLOCK_SIZE]; 
      5'd10   : trans_key_in = trans_in[BLOCK_SIZE-1:0]; 
      5'd12   : trans_key_in = trans_in[KEY_LENGTH-1:KEY_LENGTH-BLOCK_SIZE]; 
      5'd14   : trans_key_in = trans_in[BLOCK_SIZE-1:0]; 
      5'd16   : trans_key_in = trans_in[KEY_LENGTH-1:KEY_LENGTH-BLOCK_SIZE]; 
      5'd18   : trans_key_in = trans_in[BLOCK_SIZE-1:0]; 
      default : trans_key_in = trans_in[BLOCK_SIZE-1:0]; 
    endcase
  end
end

//The reg_dec_start signal indicates that the encryption process is started
always @ (posedge clk) begin
  if (rst == 1'b1) begin
    reg_dec_start <= 1'b0;
  end
  else begin
    if (block_rdy == 1'b1) begin
      reg_dec_start <= 1'b0;
    end
    else begin
      if (start == 1'b1) begin
        reg_dec_start <= 1'b1;
      end
    end
  end
end

//Block inputs in each state  
always @ (posedge clk) begin
  if (rst == 1'b1) begin
    rnd_num <= 5'd0;
    add_start <= 1'b0;
    xor_start <= 1'b0;
    curr_state <= 6'd0;
    sbpsmc_start <= 1'b0;
    reg_block_rdy <= 1'b0;
    tmv_key <= {BLOCK_SIZE{1'b0}};
    int_key <= {BLOCK_SIZE{1'b0}};
    round_out <= {BLOCK_SIZE{1'b0}};
    add_one_in <= {BLOCK_SIZE{1'b0}};
    add_two_in <= {BLOCK_SIZE{1'b0}};
  end
  else begin
    if (reg_dec_start == 1'b0) begin
      rnd_num <= 5'd0;
      add_start <= 1'b0;
      xor_start <= 1'b0;
      curr_state <= 6'd0;
      sbpsmc_start <= 1'b0;
      reg_block_rdy <= 1'b0;
      tmv_key <= {BLOCK_SIZE{1'b0}};
      int_key <= {BLOCK_SIZE{1'b0}};
      round_out <= {BLOCK_SIZE{1'b0}};
      add_one_in <= {BLOCK_SIZE{1'b0}};
      add_two_in <= {BLOCK_SIZE{1'b0}};
    end
    else begin
      case (curr_state)
        //Intermediate key generattion starts here
        6'd0 : begin
          //ADD - INTKEY
          add_start <= 1'b1;
          add_one_in <= int_key_in;
          add_two_in <= key_alfa;

          curr_state <= 6'd1;
        end
        6'd1 : begin
          if (m2p64add_rdy == 1'b1) begin
            //ADD - INTKEY
            add_start <= 1'b0;
            //SPLT - INTKEY
            sbpsmc_start <= 1'b1;
            add_one_in <= m2p64add_out;

            curr_state <= 6'd2;
          end
        end
        6'd2 : begin
          if (sbpsmc_rdy == 1'b1) begin
            //SPLT - INTKEY
            sbpsmc_start <= 1'b0;
            //XOR - INTKEY
            xor_start <= 1'b1;
            add_one_in <= key_omega;
            add_two_in <= sbpsmc_out;

            curr_state <= 6'd3;
          end
        end
        6'd3 : begin
          if (m2add_rdy == 1'b1) begin
            //XOR - INTKEY
            xor_start <= 1'b0;
            //SPLT - INTKEY
            sbpsmc_start <= 1'b1;
            add_one_in <= m2add_out;
            
            curr_state <= 6'd4;
          end
        end
        6'd4 : begin
          if (sbpsmc_rdy == 1'b1) begin
            //SPLT - INTKEY
            sbpsmc_start <= 1'b0;
            //ADD - INTKEY
            add_start <= 1'b1;
            add_one_in <= key_alfa;
            add_two_in <= sbpsmc_out;

            curr_state <= 6'd5;
          end
        end
        6'd5 : begin
          if (m2p64add_rdy == 1'b1) begin
            //RND - KEY10
            rnd_num <= rnd_cnt;

            //ADD - INTKEY
            add_start <= 1'b0;
            //SPLT - INTKEY
            sbpsmc_start <= 1'b1;
            add_one_in <= m2p64add_out;
            
            curr_state <= 6'd6;
          end
        end
        //Intermediate key generation ends and round 10 key generation starts here
        6'd6 : begin
          if (sbpsmc_rdy == 1'b1) begin
            int_key <= sbpsmc_out;

            //SPLT - KEY10
            sbpsmc_start <= 1'b0;
            //ADD - KEY10
            add_start <= 1'b1;
            add_one_in <= sbpsmc_out;
            add_two_in <= shft_tmv;

            curr_state <= 6'd7;
          end
        end
        6'd7 : begin
          if (m2p64add_rdy == 1'b1) begin
            tmv_key <= m2p64add_out;

            //ADD - KEY10
            add_one_in <= m2p64add_out;
            add_two_in <= trans_key_in;

            curr_state <= 6'd8;
          end
        end
        6'd8 : begin
          if (m2p64add_rdy == 1'b1) begin
            //ADD - KEY10
            add_start <= 1'b0;
            //SPLT - KEY10
            sbpsmc_start <= 1'b1;
            add_one_in <= m2p64add_out;

            curr_state <= 6'd9;
          end
        end
        6'd9 : begin
          if (sbpsmc_rdy == 1'b1) begin
            //SPLT - KEY10
            sbpsmc_start <= 1'b0;
            //XOR - KEY10
            xor_start <= 1'b1;
            add_one_in <= tmv_key;
            add_two_in <= sbpsmc_out;

            curr_state <= 6'd10;
          end
        end
        6'd10 : begin
          if (m2add_rdy == 1'b1) begin
            //XOR - KEY10
            xor_start <= 1'b0;
            //SPLT - KEY10
            sbpsmc_start <= 1'b1;
            add_one_in <= m2add_out;

            curr_state <= 6'd11;
          end
        end
        6'd11 : begin
          if (sbpsmc_rdy == 1'b1) begin
            //SPLT - KEY10
            sbpsmc_start <= 1'b0;
            //ADD - KEY10
            add_start <= 1'b1;
            add_one_in <= tmv_key;
            add_two_in <= sbpsmc_out;

            curr_state <= 6'd12;
          end
        end
        //Round 10 key generation ends here and Round 10 operations start here
        6'd12 : begin
          if (m2p64add_rdy == 1'b1) begin
            tmv_key <= m2p64add_out;
            //SUB - RND10
            add_one_in <= block_in;
            add_two_in <= m2p64add_out;

            curr_state <= 6'd13;
          end
        end
        6'd13 : begin
          if (m2p64sub_rdy == 1'b1) begin
            //RND - KEY8
            rnd_num <= rnd_num - 5'd2;
            //ADD - RND10
            add_start <= 1'b0;
            //INV SPLT - RND10
            sbpsmc_start <= 1'b1;
            add_one_in <= m2p64sub_out;

            curr_state <= 6'd14;
          end
        end
        //Round 10 operations end here and Round 8 key operations start here
        6'd14 : begin
          if (inv_sbpsmc_rdy == 1'b1) begin
            round_out <= inv_sbpsmc_out;
            //INV SPLT - RND10
            sbpsmc_start <= 1'b0;
            //ADD - KEY8
            add_start <= 1'b1;
            add_one_in <= int_key;
            add_two_in <= shft_tmv;

            curr_state <= 6'd15;
          end
        end
        6'd15 : begin
          if (m2p64add_rdy == 1'b1) begin
            tmv_key <= m2p64add_out;

            //ADD - KEY8
            add_one_in <= m2p64add_out;
            add_two_in <= trans_key_in;

            curr_state <= 6'd16;
          end
        end
        6'd16 : begin
          if (m2p64add_rdy == 1'b1) begin
            //ADD - KEY8
            add_start <= 1'b0;
            //SPLT - KEY8
            sbpsmc_start <= 1'b1;
            add_one_in <= m2p64add_out;

            curr_state <= 6'd17;
          end
        end
        6'd17 : begin
          if (sbpsmc_rdy == 1'b1) begin
            //SPLT - KEY8
            sbpsmc_start <= 1'b0;
            //XOR - KEY8
            xor_start <= 1'b1;
            add_one_in <= tmv_key;
            add_two_in <= sbpsmc_out;

            curr_state <= 6'd18;
          end
        end
        6'd18 : begin
          if (m2add_rdy == 1'b1) begin
            //XOR - KEY8
            xor_start <= 1'b0;
            //SPLT - KEY8
            sbpsmc_start <= 1'b1;
            add_one_in <= m2add_out;

            curr_state <= 6'd19;
          end
        end
        6'd19 : begin
          if (sbpsmc_rdy == 1'b1) begin
            //SPLT - KEY8
            sbpsmc_start <= 1'b0;
            //ADD - KEY8
            add_start <= 1'b1;
            add_one_in <= tmv_key;
            add_two_in <= sbpsmc_out;

            curr_state <= 6'd20;
          end
        end
        //Round 8 key generation ends here and Round 9-8 operations start here
        6'd20 : begin
          if (m2p64add_rdy == 1'b1) begin
            tmv_key <= m2p64add_out;
            //ADD - KEY8
            add_start <= 1'b0;
            //XOR - RND9
            xor_start <= 1'b1;
            add_one_in <= round_out;
            add_two_in <= {m2p64add_out[BLOCK_SIZE-1-the_lr:0], m2p64add_out[BLOCK_SIZE-1:BLOCK_SIZE-the_lr]};

            curr_state <= 6'd21;
          end
        end
        6'd21 : begin
          if (m2add_rdy == 1'b1) begin
            //XOR - RND9
            xor_start <= 1'b0;
            //INV SPLT - RND9
            sbpsmc_start <= 1'b1;
            add_one_in <= m2add_out;

            curr_state <= 6'd22;
          end
        end
        6'd22 : begin
          if (inv_sbpsmc_rdy == 1'b1) begin
            //INV SPLT - RND9
            sbpsmc_start <= 1'b0;
            //XOR - RND8
            xor_start <= 1'b1;
            add_one_in <= inv_sbpsmc_out;
            add_two_in <= tmv_key;

            curr_state <= 6'd23;
          end
        end
        6'd23 : begin
          if (m2add_rdy == 1'b1) begin
            //RND - KEY6
            rnd_num <= rnd_num - 5'd2;
            //XOR - RND8
            xor_start <= 1'b0;
            //INV SPLT - RND8
            sbpsmc_start <= 1'b1;
            add_one_in <= m2add_out;

            curr_state <= 6'd24;
          end
        end
        //Round 9-8 operations end here and Round 6 key operations start here
        6'd24 : begin
          if (inv_sbpsmc_rdy == 1'b1) begin
            round_out <= inv_sbpsmc_out;
            //INV SPLT - RND8
            sbpsmc_start <= 1'b0;
            //ADD - KEY6
            add_start <= 1'b1;
            add_one_in <= int_key;
            add_two_in <= shft_tmv;

            curr_state <= 6'd25;
          end
        end
        6'd25 : begin
          if (m2p64add_rdy == 1'b1) begin
            tmv_key <= m2p64add_out;

            //ADD - KEY6
            add_one_in <= m2p64add_out;
            add_two_in <= trans_key_in;

            curr_state <= 6'd26;
          end
        end
        6'd26 : begin
          if (m2p64add_rdy == 1'b1) begin
            //ADD - KEY6
            add_start <= 1'b0;
            //SPLT - KEY6
            sbpsmc_start <= 1'b1;
            add_one_in <= m2p64add_out;

            curr_state <= 6'd27;
          end
        end
        6'd27 : begin
          if (sbpsmc_rdy == 1'b1) begin
            //SPLT - KEY6
            sbpsmc_start <= 1'b0;
            //XOR - KEY6
            xor_start <= 1'b1;
            add_one_in <= tmv_key;
            add_two_in <= sbpsmc_out;

            curr_state <= 6'd28;
          end
        end
        6'd28 : begin
          if (m2add_rdy == 1'b1) begin
            //XOR - KEY6
            xor_start <= 1'b0;
            //SPLT - KEY6
            sbpsmc_start <= 1'b1;
            add_one_in <= m2add_out;

            curr_state <= 6'd29;
          end
        end
        6'd29 : begin
          if (sbpsmc_rdy == 1'b1) begin
            //SPLT - KEY6
            sbpsmc_start <= 1'b0;
            //ADD - KEY6
            add_start <= 1'b1;
            add_one_in <= tmv_key;
            add_two_in <= sbpsmc_out;

            curr_state <= 6'd30;
          end
        end
        //Round 6 key generation ends here and Round 7-6 operations start here
        6'd30 : begin
          if (m2p64add_rdy == 1'b1) begin
            tmv_key <= m2p64add_out;
            //ADD - KEY6
            add_start <= 1'b0;
            //XOR - RND7
            xor_start <= 1'b1;
            add_one_in <= round_out;
            add_two_in <= {m2p64add_out[BLOCK_SIZE-1-the_lr:0], m2p64add_out[BLOCK_SIZE-1:BLOCK_SIZE-the_lr]};

            curr_state <= 6'd31;
          end
        end
        6'd31 : begin
          if (m2add_rdy == 1'b1) begin
            //XOR - RND7
            xor_start <= 1'b0;
            //INV SPLT - RND7
            sbpsmc_start <= 1'b1;
            add_one_in <= m2add_out;

            curr_state <= 6'd32;
          end
        end
        6'd32 : begin
          if (inv_sbpsmc_rdy == 1'b1) begin
            //INV SPLT - RND7
            sbpsmc_start <= 1'b0;
            //XOR - RND6
            xor_start <= 1'b1;
            add_one_in <= inv_sbpsmc_out;
            add_two_in <= tmv_key;

            curr_state <= 6'd33;
          end
        end
        6'd33 : begin
          if (m2add_rdy == 1'b1) begin
            //RND - KEY4
            rnd_num <= rnd_num - 5'd2;
            //XOR - RND6
            xor_start <= 1'b0;
            //INV SPLT - RND6
            sbpsmc_start <= 1'b1;
            add_one_in <= m2add_out;

            curr_state <= 6'd34;
          end
        end
        //Round 7-6 operations end here and Round 4 key operations start here
        6'd34 : begin
          if (inv_sbpsmc_rdy == 1'b1) begin
            round_out <= inv_sbpsmc_out;
            //INV SPLT - RND6
            sbpsmc_start <= 1'b0;
            //ADD - KEY4
            add_start <= 1'b1;
            add_one_in <= int_key;
            add_two_in <= shft_tmv;

            curr_state <= 6'd35;
          end
        end
        6'd35 : begin
          if (m2p64add_rdy == 1'b1) begin
            tmv_key <= m2p64add_out;

            //ADD - KEY4
            add_one_in <= m2p64add_out;
            add_two_in <= trans_key_in;

            curr_state <= 6'd36;
          end
        end
        6'd36 : begin
          if (m2p64add_rdy == 1'b1) begin
            //ADD - KEY4
            add_start <= 1'b0;
            //SPLT - KEY4
            sbpsmc_start <= 1'b1;
            add_one_in <= m2p64add_out;

            curr_state <= 6'd37;
          end
        end
        6'd37 : begin
          if (sbpsmc_rdy == 1'b1) begin
            //SPLT - KEY4
            sbpsmc_start <= 1'b0;
            //XOR - KEY4
            xor_start <= 1'b1;
            add_one_in <= tmv_key;
            add_two_in <= sbpsmc_out;

            curr_state <= 6'd38;
          end
        end
        6'd38 : begin
          if (m2add_rdy == 1'b1) begin
            //XOR - KEY4
            xor_start <= 1'b0;
            //SPLT - KEY4
            sbpsmc_start <= 1'b1;
            add_one_in <= m2add_out;

            curr_state <= 6'd39;
          end
        end
        6'd39 : begin
          if (sbpsmc_rdy == 1'b1) begin
            //SPLT - KEY4
            sbpsmc_start <= 1'b0;
            //ADD - KEY4
            add_start <= 1'b1;
            add_one_in <= tmv_key;
            add_two_in <= sbpsmc_out;

            curr_state <= 6'd40;
          end
        end
        //Round 4 key generation ends here and Round 5-4 operations start here
        6'd40 : begin
          if (m2p64add_rdy == 1'b1) begin
            tmv_key <= m2p64add_out;
            //ADD - KEY4
            add_start <= 1'b0;
            //XOR - RND5
            xor_start <= 1'b1;
            add_one_in <= round_out;
            add_two_in <= {m2p64add_out[BLOCK_SIZE-1-the_lr:0], m2p64add_out[BLOCK_SIZE-1:BLOCK_SIZE-the_lr]};

            curr_state <= 6'd41;
          end
        end
        6'd41 : begin
          if (m2add_rdy == 1'b1) begin
            //XOR - RND5
            xor_start <= 1'b0;
            //INV SPLT - RND5
            sbpsmc_start <= 1'b1;
            add_one_in <= m2add_out;

            curr_state <= 6'd42;
          end
        end
        6'd42 : begin
          if (inv_sbpsmc_rdy == 1'b1) begin
            //INV SPLT - RND5
            sbpsmc_start <= 1'b0;
            //XOR - RND4
            xor_start <= 1'b1;
            add_one_in <= inv_sbpsmc_out;
            add_two_in <= tmv_key;

            curr_state <= 6'd43;
          end
        end
        6'd43 : begin
          if (m2add_rdy == 1'b1) begin
            //RND - KEY2
            rnd_num <= rnd_num - 5'd2;
            //XOR - RND4
            xor_start <= 1'b0;
            //INV SPLT - RND4
            sbpsmc_start <= 1'b1;
            add_one_in <= m2add_out;

            curr_state <= 6'd44;
          end
        end
        //Round 5-4 operations end here and Round 2 key operations start here
        6'd44 : begin
          if (inv_sbpsmc_rdy == 1'b1) begin
            round_out <= inv_sbpsmc_out;
            //INV SPLT - RND4
            sbpsmc_start <= 1'b0;
            //ADD - KEY2
            add_start <= 1'b1;
            add_one_in <= int_key;
            add_two_in <= shft_tmv;

            curr_state <= 6'd45;
          end
        end
        6'd45 : begin
          if (m2p64add_rdy == 1'b1) begin
            tmv_key <= m2p64add_out;

            //ADD - KEY2
            add_one_in <= m2p64add_out;
            add_two_in <= trans_key_in;

            curr_state <= 6'd46;
          end
        end
        6'd46 : begin
          if (m2p64add_rdy == 1'b1) begin
            //ADD - KEY2
            add_start <= 1'b0;
            //SPLT - KEY2
            sbpsmc_start <= 1'b1;
            add_one_in <= m2p64add_out;

            curr_state <= 6'd47;
          end
        end
        6'd47 : begin
          if (sbpsmc_rdy == 1'b1) begin
            //SPLT - KEY2
            sbpsmc_start <= 1'b0;
            //XOR - KEY2
            xor_start <= 1'b1;
            add_one_in <= tmv_key;
            add_two_in <= sbpsmc_out;

            curr_state <= 6'd48;
          end
        end
        6'd48 : begin
          if (m2add_rdy == 1'b1) begin
            //XOR - KEY2
            xor_start <= 1'b0;
            //SPLT - KEY2
            sbpsmc_start <= 1'b1;
            add_one_in <= m2add_out;

            curr_state <= 6'd49;
          end
        end
        6'd49 : begin
          if (sbpsmc_rdy == 1'b1) begin
            //SPLT - KEY2
            sbpsmc_start <= 1'b0;
            //ADD - KEY2
            add_start <= 1'b1;
            add_one_in <= tmv_key;
            add_two_in <= sbpsmc_out;

            curr_state <= 6'd50;
          end
        end
        //Round 2 key generation ends here and Round 3-2 operations start here
        6'd50 : begin
          if (m2p64add_rdy == 1'b1) begin
            tmv_key <= m2p64add_out;
            //ADD - KEY2
            add_start <= 1'b0;
            //XOR - RND3
            xor_start <= 1'b1;
            add_one_in <= round_out;
            add_two_in <= {m2p64add_out[BLOCK_SIZE-1-the_lr:0], m2p64add_out[BLOCK_SIZE-1:BLOCK_SIZE-the_lr]};

            curr_state <= 6'd51;
          end
        end
        6'd51 : begin
          if (m2add_rdy == 1'b1) begin
            //XOR - RND3
            xor_start <= 1'b0;
            //INV SPLT - RND3
            sbpsmc_start <= 1'b1;
            add_one_in <= m2add_out;

            curr_state <= 6'd52;
          end
        end
        6'd52 : begin
          if (inv_sbpsmc_rdy == 1'b1) begin
            //INV SPLT - RND3
            sbpsmc_start <= 1'b0;
            //XOR - RND2
            xor_start <= 1'b1;
            add_one_in <= inv_sbpsmc_out;
            add_two_in <= tmv_key;

            curr_state <= 6'd53;
          end
        end
        6'd53 : begin
          if (m2add_rdy == 1'b1) begin
            //RND - KEY0
            rnd_num <= rnd_num - 5'd2;
            //XOR - RND2
            xor_start <= 1'b0;
            //INV SPLT - RND2
            sbpsmc_start <= 1'b1;
            add_one_in <= m2add_out;

            curr_state <= 6'd54;
          end
        end
        //Round 3-2 operations end here and Round 0 key operations start here
        6'd54 : begin
          if (inv_sbpsmc_rdy == 1'b1) begin
            round_out <= inv_sbpsmc_out;
            //INV SPLT - RND2
            sbpsmc_start <= 1'b0;
            //ADD - KEY0
            add_start <= 1'b1;
            add_one_in <= int_key;
            add_two_in <= shft_tmv;

            if (rnd_cnt == 5'd10) begin
              curr_state <= 6'd55;
            end
            else if (rnd_cnt == 5'd14) begin
              if (rnd_num == 5'd0) begin
                curr_state <= 6'd55;
              end
              else begin
                curr_state <= 6'd35;
              end
            end
            else begin
              if (rnd_num == 5'd0) begin
                curr_state <= 6'd55;
              end
              else begin
                curr_state <= 6'd15;
              end
            end
          end
        end
        6'd55 : begin
          if (m2p64add_rdy == 1'b1) begin
            tmv_key <= m2p64add_out;

            //ADD - KEY0
            add_one_in <= m2p64add_out;
            add_two_in <= trans_key_in;

            curr_state <= 6'd56;
          end
        end
        6'd56 : begin
          if (m2p64add_rdy == 1'b1) begin
            //ADD - KEY0
            add_start <= 1'b0;
            //SPLT - KEY0
            sbpsmc_start <= 1'b1;
            add_one_in <= m2p64add_out;

            curr_state <= 6'd57;
          end
        end
        6'd57 : begin
          if (sbpsmc_rdy == 1'b1) begin
            //SPLT - KEY0
            sbpsmc_start <= 1'b0;
            //XOR - KEY0
            xor_start <= 1'b1;
            add_one_in <= tmv_key;
            add_two_in <= sbpsmc_out;

            curr_state <= 6'd58;
          end
        end
        6'd58 : begin
          if (m2add_rdy == 1'b1) begin
            //XOR - KEY0
            xor_start <= 1'b0;
            //SPLT - KEY0
            sbpsmc_start <= 1'b1;
            add_one_in <= m2add_out;

            curr_state <= 6'd59;
          end
        end
        6'd59 : begin
          if (sbpsmc_rdy == 1'b1) begin
            //SPLT - KEY0
            sbpsmc_start <= 1'b0;
            //ADD - KEY0
            add_start <= 1'b1;
            add_one_in <= tmv_key;
            add_two_in <= sbpsmc_out;

            curr_state <= 6'd60;
          end
        end
        //Round 0 key generation ends here and Round 1-0 operations start here
        6'd60 : begin
          if (m2p64add_rdy == 1'b1) begin
            tmv_key <= m2p64add_out;
            //ADD - KEY0
            add_start <= 1'b0;
            //XOR - RND1
            xor_start <= 1'b1;
            add_one_in <= round_out;
            add_two_in <= {m2p64add_out[BLOCK_SIZE-1-the_lr:0], m2p64add_out[BLOCK_SIZE-1:BLOCK_SIZE-the_lr]};

            curr_state <= 6'd61;
          end
        end
        6'd61 : begin
          if (m2add_rdy == 1'b1) begin
            //XOR - RND1
            xor_start <= 1'b0;
            //INV SPLT - RND1
            sbpsmc_start <= 1'b1;
            add_one_in <= m2add_out;

            curr_state <= 6'd62;
          end
        end
        6'd62 : begin
          if (inv_sbpsmc_rdy == 1'b1) begin
            //INV SPLT - RND1
            sbpsmc_start <= 1'b0;
            //SUB - RND0
            add_start <= 1'b1;
            add_one_in <= inv_sbpsmc_out;
            add_two_in <= tmv_key;

            curr_state <= 6'd63;
          end
        end
        6'd63 : begin
          if (m2p64sub_rdy == 1'b1) begin
            round_out <= m2p64sub_out;
            reg_block_rdy <= 1'b1;

            //SUB - RND0
            add_start <= 1'b0;

            curr_state <= 6'd0;
          end
        end
        default : begin
          rnd_num <= 5'd0;
          add_start <= 1'b0;
          xor_start <= 1'b0;
          curr_state <= 6'd0;
          sbpsmc_start <= 1'b0;
          reg_block_rdy <= 1'b0;
          tmv_key <= {BLOCK_SIZE{1'b0}};
          int_key <= {BLOCK_SIZE{1'b0}};
          round_out <= {BLOCK_SIZE{1'b0}};
          add_one_in <= {BLOCK_SIZE{1'b0}};
          add_two_in <= {BLOCK_SIZE{1'b0}};
        end
      endcase
    end
  end
end

//Additions
mod2_add_serial64b #(.BLOCK_SIZE(BLOCK_SIZE)) m2a_ins (.clk(clk), .rst(rst), .m2add_start(xor_start), .m2add_in_one(add_one_in), .m2add_in_two(add_two_in), .m2add_out(m2add_out), .m2add_rdy(m2add_rdy));
mod2p64_add_serial64b #(.BLOCK_SIZE(BLOCK_SIZE)) m2p64a_ins (.clk(clk), .rst(rst), .m2p64add_start(add_start), .m2p64add_in_one(add_one_in), .m2p64add_in_two(add_two_in), .m2p64add_out(m2p64add_out), .m2p64add_rdy(m2p64add_rdy));
//Substitution Permutation Mix-Column
sbpsmc_serial64b #(.BLOCK_SIZE(BLOCK_SIZE)) sbpsmc64b_ins (.clk(clk), .rst(rst), .sbpsmc_start(sbpsmc_start), .sbpsmc_in(add_one_in), .sbpsmc_out(sbpsmc_out), .sbpsmc_rdy(sbpsmc_rdy));
//Inverse Addition
inv_mod2p64_add_serial64b #(.BLOCK_SIZE(BLOCK_SIZE)) inv_m2p64a_ins (.clk(clk), .rst(rst), .m2p64add_start(add_start), .m2p64add_in_one(add_one_in), .m2p64add_in_two(add_two_in), .m2p64add_out(m2p64sub_out), .m2p64add_rdy(m2p64sub_rdy));
//Inverse Substitution Permutation Mix-Column
inv_sbpsmc_serial64b #(.BLOCK_SIZE(BLOCK_SIZE)) inv_sbpsmc64b_ins (.clk(clk), .rst(rst), .sbpsmc_start(sbpsmc_start), .sbpsmc_in(add_one_in), .sbpsmc_out(inv_sbpsmc_out), .sbpsmc_rdy(inv_sbpsmc_rdy));

//Block Outputs
always @ (posedge clk) begin
  if (rst == 1'b1) begin
    block_rdy <= 1'b0;
    block_out <= {BLOCK_SIZE{1'b0}};
  end
  else begin
    if (reg_dec_start == 1'b0) begin
      block_rdy <= 1'b0;
      block_out <= {BLOCK_SIZE{1'b0}};
    end
    else begin
      if (reg_block_rdy == 1'b1) begin
        block_rdy <= 1'b1;
        block_out <= round_out;
      end
    end
  end
end

endmodule

//KALYNA DECRYPTION BLOCK - SERIAL - ONE 64-bit OPERATION in ONE CLOCK CYCLE - First-Order Masking + Hiding + Hybrid Duplication
module kalyna_dec_block_serial64b_oboc_fomhidhybdup #(parameter BLOCK_SIZE = 128, parameter KEY_LENGTH = 128) (clk, rst, start, block_in, key_in, block_out, block_rdy);

input clk, rst, start;
input [BLOCK_SIZE-1:0] block_in;
input [KEY_LENGTH-1:0] key_in;
output reg [BLOCK_SIZE-1:0] block_out;
output reg block_rdy;

//Local parameters
localparam bs_m8 = BLOCK_SIZE - 8;
localparam bs_d16 = BLOCK_SIZE/16;
localparam the_lr = (BLOCK_SIZE/4+24);
localparam rnd_cnt = (BLOCK_SIZE == KEY_LENGTH && BLOCK_SIZE == 128) ? 5'd10 : (BLOCK_SIZE == KEY_LENGTH && BLOCK_SIZE == 256) ? 5'd14 : (BLOCK_SIZE == KEY_LENGTH && BLOCK_SIZE == 512) ? 5'd18 : (BLOCK_SIZE != KEY_LENGTH && BLOCK_SIZE == 128) ? 5'd14 : 5'd18;

//Variables
reg [4:0] rnd_num;
reg [KEY_LENGTH-1:0] trans_in;
reg [5:0] curr_state, pre_curr_state;
reg xor_start, add_start, sbpsmc_start, inv_add_start, inv_sbpsmc_start, reg_block_rdy, reg_dec_start, reg_flt_inj, reg_flt_state;
reg [BLOCK_SIZE-1:0] key_alfa, key_omega, add_one_in, add_two_in, int_key, shft_tmv, trans_key_in, tmv_key, round_out, m2add_out, m2p64add_out, sbpsmc_out, m2p64sub_out, inv_sbpsmc_out;
wire [63:0] prng_out;
wire [BLOCK_SIZE-1:0] int_key_in, the_tmv;
wire [7:0] the_const = (BLOCK_SIZE+KEY_LENGTH)/64 + 1;
wire [BLOCK_SIZE-1:0] m2add_out_one, m2add_out_two, m2p64add_out_one, m2p64add_out_two, sbpsmc_out_one, sbpsmc_out_two, m2p64sub_out_one, m2p64sub_out_two, inv_sbpsmc_out_one, inv_sbpsmc_out_two;
wire m2add_rdy, m2add_rdy_one, m2add_rdy_two, m2p64add_rdy, m2p64add_rdy_one, m2p64add_rdy_two, sbpsmc_rdy, sbpsmc_rdy_one, sbpsmc_rdy_two, m2p64sub_rdy, m2p64sub_rdy_one, m2p64sub_rdy_two, inv_sbpsmc_rdy, inv_sbpsmc_rdy_one, inv_sbpsmc_rdy_two, flt_inj, flt_state;

//Input to the intermediate key transformation
assign int_key_in = {the_const, {bs_m8{1'b0}}};

//Alfa and Omega Keys for the intermediate key transformation
always @ (*) begin
  if (BLOCK_SIZE == KEY_LENGTH) begin
    key_alfa = key_in;
    key_omega = key_in;
  end
  else begin
    key_alfa = key_in[KEY_LENGTH-1:KEY_LENGTH/2];
    key_omega = key_in[KEY_LENGTH/2-1:0];
  end
end

//Generation of the TMV signal and its shifted version
assign the_tmv= {bs_d16{16'h0100}};
always @ (*) begin
  case (rnd_num)
    5'd0    : shft_tmv = the_tmv;
    5'd2    : shft_tmv = {the_tmv[BLOCK_SIZE-2:0],  1'd0};
    5'd4    : shft_tmv = {the_tmv[BLOCK_SIZE-3:0],  2'd0};
    5'd6    : shft_tmv = {the_tmv[BLOCK_SIZE-4:0],  3'd0};
    5'd8    : shft_tmv = {the_tmv[BLOCK_SIZE-5:0],  4'd0};
    5'd10   : shft_tmv = {the_tmv[BLOCK_SIZE-6:0],  5'd0};
    5'd12   : shft_tmv = {the_tmv[BLOCK_SIZE-7:0],  6'd0};
    5'd14   : shft_tmv = {the_tmv[BLOCK_SIZE-8:0],  7'd0};
    5'd16   : shft_tmv = {the_tmv[BLOCK_SIZE-9:0],  7'd0, 1'b1};
    5'd18   : shft_tmv = {the_tmv[BLOCK_SIZE-10:0], 7'd0, 1'b1, 1'b0}; //Last two lines are due to the conflict between rotate and shift
    default : shft_tmv = the_tmv;
  endcase
end

//Generation of the input to the transformations
always @ (*) begin
  if (BLOCK_SIZE == KEY_LENGTH) begin
    if (BLOCK_SIZE == 128) begin
      case (rnd_num) 
        5'd0    : trans_in = key_in;
        5'd2    : trans_in = {key_in[63:0], key_in[127:64]};
        5'd4    : trans_in = key_in;
        5'd6    : trans_in = {key_in[63:0], key_in[127:64]};
        5'd8    : trans_in = key_in;
        5'd10   : trans_in = {key_in[63:0], key_in[127:64]};
        default : trans_in = key_in;
      endcase
    end
    else if (BLOCK_SIZE == 256) begin
      case (rnd_num) 
        5'd0    : trans_in = key_in;
        5'd2    : trans_in = {key_in[191:0], key_in[255:192]};
        5'd4    : trans_in = {key_in[127:0], key_in[255:128]};
        5'd6    : trans_in = {key_in[63:0],  key_in[255:64]};
        5'd8    : trans_in = key_in;
        5'd10   : trans_in = {key_in[191:0], key_in[255:192]};
        5'd12   : trans_in = {key_in[127:0], key_in[255:128]};
        5'd14   : trans_in = {key_in[63:0],  key_in[255:64]};
        default : trans_in = key_in;
      endcase
    end
    else begin
      case (rnd_num) 
        5'd0    : trans_in = key_in;
        5'd2    : trans_in = {key_in[447:0], key_in[511:448]};
        5'd4    : trans_in = {key_in[383:0], key_in[511:384]};
        5'd6    : trans_in = {key_in[319:0], key_in[511:320]};
        5'd8    : trans_in = {key_in[255:0], key_in[511:256]};
        5'd10   : trans_in = {key_in[191:0], key_in[511:192]};
        5'd12   : trans_in = {key_in[127:0], key_in[511:128]};
        5'd14   : trans_in = {key_in[63:0],  key_in[511:64]};
        5'd16   : trans_in = key_in;
        5'd18   : trans_in = {key_in[447:0], key_in[511:448]};
        default : trans_in = key_in;
      endcase
    end
  end
  else begin
    if (BLOCK_SIZE == 128) begin
      case (rnd_num) 
        5'd0    : trans_in = key_in;
        5'd2    : trans_in = key_in;
        5'd4    : trans_in = {key_in[191:0], key_in[255:192]};
        5'd6    : trans_in = {key_in[191:0], key_in[255:192]};
        5'd8    : trans_in = {key_in[127:0], key_in[255:128]};
        5'd10   : trans_in = {key_in[127:0], key_in[255:128]};
        5'd12   : trans_in = {key_in[63:0],  key_in[255:64]};
        5'd14   : trans_in = {key_in[63:0],  key_in[255:64]};
        default : trans_in = key_in;
      endcase
    end
    else begin
      case (rnd_num) 
        5'd0    : trans_in = key_in;
        5'd2    : trans_in = key_in;
        5'd4    : trans_in = {key_in[447:0], key_in[511:448]};
        5'd6    : trans_in = {key_in[447:0], key_in[511:448]};
        5'd8    : trans_in = {key_in[383:0], key_in[511:384]};
        5'd10   : trans_in = {key_in[383:0], key_in[511:384]};
        5'd12   : trans_in = {key_in[319:0], key_in[511:320]};
        5'd14   : trans_in = {key_in[319:0], key_in[511:320]};
        5'd16   : trans_in = {key_in[255:0], key_in[511:256]};
        5'd18   : trans_in = {key_in[255:0], key_in[511:256]};
        default : trans_in = key_in;
      endcase
    end
  end
end
always @ (*) begin
  if (BLOCK_SIZE == KEY_LENGTH) begin
    trans_key_in = trans_in;
  end
  else begin
    case (rnd_num) 
      5'd0    : trans_key_in = trans_in[KEY_LENGTH-1:KEY_LENGTH-BLOCK_SIZE];
      5'd2    : trans_key_in = trans_in[BLOCK_SIZE-1:0];
      5'd4    : trans_key_in = trans_in[KEY_LENGTH-1:KEY_LENGTH-BLOCK_SIZE]; 
      5'd6    : trans_key_in = trans_in[BLOCK_SIZE-1:0]; 
      5'd8    : trans_key_in = trans_in[KEY_LENGTH-1:KEY_LENGTH-BLOCK_SIZE]; 
      5'd10   : trans_key_in = trans_in[BLOCK_SIZE-1:0]; 
      5'd12   : trans_key_in = trans_in[KEY_LENGTH-1:KEY_LENGTH-BLOCK_SIZE]; 
      5'd14   : trans_key_in = trans_in[BLOCK_SIZE-1:0]; 
      5'd16   : trans_key_in = trans_in[KEY_LENGTH-1:KEY_LENGTH-BLOCK_SIZE]; 
      5'd18   : trans_key_in = trans_in[BLOCK_SIZE-1:0]; 
      default : trans_key_in = trans_in[BLOCK_SIZE-1:0]; 
    endcase
  end
end

//The reg_dec_start signal indicates that the encryption process is started
always @ (posedge clk) begin
  if (rst == 1'b1) begin
    reg_dec_start <= 1'b0;
  end
  else begin
    if (block_rdy == 1'b1) begin
      reg_dec_start <= 1'b0;
    end
    else begin
      if (reg_flt_inj | reg_flt_state) begin
        reg_dec_start <= 1'b0;
      end
      else begin
        if (start == 1'b1) begin
          reg_dec_start <= 1'b1;
        end
      end
    end
  end
end

//Block inputs in each state  
always @ (posedge clk) begin
  if (rst == 1'b1) begin
    rnd_num <= 5'd0;
    add_start <= 1'b0;
    xor_start <= 1'b0;
    curr_state <= 6'd0;
    sbpsmc_start <= 1'b0;
    reg_block_rdy <= 1'b0;
    inv_add_start <= 1'b0;
    inv_sbpsmc_start <= 1'b0;
    tmv_key <= {BLOCK_SIZE{1'b0}};
    int_key <= {BLOCK_SIZE{1'b0}};
    round_out <= {BLOCK_SIZE{1'b0}};
    add_one_in <= {BLOCK_SIZE{1'b0}};
    add_two_in <= {BLOCK_SIZE{1'b0}};
  end
  else begin
    if (reg_dec_start == 1'b0) begin
      rnd_num <= 5'd0;
      add_start <= 1'b0;
      xor_start <= 1'b0;
      curr_state <= 6'd0;
      sbpsmc_start <= 1'b0;
      reg_block_rdy <= 1'b0;
      inv_add_start <= 1'b0;
      inv_sbpsmc_start <= 1'b0;
      tmv_key <= {BLOCK_SIZE{1'b0}};
      int_key <= {BLOCK_SIZE{1'b0}};
      round_out <= {BLOCK_SIZE{1'b0}};
      add_one_in <= {BLOCK_SIZE{1'b0}};
      add_two_in <= {BLOCK_SIZE{1'b0}};
    end
    else begin
      case (curr_state)
        //Intermediate key generattion starts here
        6'd0 : begin
          //SOME OPERATIONS
          xor_start <= add_one_in[0];
          sbpsmc_start <= add_one_in[1];
          inv_add_start <= add_two_in[0];
          inv_sbpsmc_start <= add_two_in[1];

          //ADD - INTKEY
          add_start <= 1'b1;
          add_one_in <= int_key_in;
          add_two_in <= key_alfa;

          curr_state <= 6'd1;
        end
        6'd1 : begin
          if (m2p64add_rdy == 1'b1) begin
            //SOME OPERATIONS
            add_start <= add_one_in[2];
            xor_start <= add_one_in[3];
            inv_add_start <= add_two_in[2];
            inv_sbpsmc_start <= add_two_in[3];

            //SPLT - INTKEY
            sbpsmc_start <= 1'b1;
            add_one_in <= m2p64add_out;

            curr_state <= 6'd2;
          end
        end
        6'd2 : begin
          if (sbpsmc_rdy == 1'b1) begin
            //SOME OPERATIONS
            add_start <= add_one_in[4];
            sbpsmc_start <= add_one_in[5];
            inv_add_start <= add_two_in[4];
            inv_sbpsmc_start <= add_two_in[5];

            //XOR - INTKEY
            xor_start <= 1'b1;
            add_one_in <= key_omega;
            add_two_in <= sbpsmc_out;

            curr_state <= 6'd3;
          end
        end
        6'd3 : begin
          if (m2add_rdy == 1'b1) begin
            //SOME OPERATIONS
            add_start <= add_one_in[6];
            xor_start <= add_one_in[7];
            inv_add_start <= add_two_in[6];
            inv_sbpsmc_start <= add_two_in[7];

            //SPLT - INTKEY
            sbpsmc_start <= 1'b1;
            add_one_in <= m2add_out;
            
            curr_state <= 6'd4;
          end
        end
        6'd4 : begin
          if (sbpsmc_rdy == 1'b1) begin
            //SOME OPERATIONS
            xor_start <= add_one_in[8];
            sbpsmc_start <= add_one_in[9];
            inv_add_start <= add_two_in[8];
            inv_sbpsmc_start <= add_two_in[9];

