            add_two_in <= sbpsmc_out;

            curr_state <= 6'd50;
          end
        end
        //Round 2 key generation ends here and Round 3-2 operations start here
        6'd50 : begin
          if (m2p64add_rdy == 1'b1) begin
            //SOME OPERATIONS
            add_start <= add_one_in[100];
            sbpsmc_start <= add_one_in[101];
            inv_add_start <= add_two_in[100];
            inv_sbpsmc_start <= add_two_in[101];

            tmv_key <= m2p64add_out;
            //XOR - RND3
            xor_start <= 1'b1;
            add_one_in <= round_out;
            add_two_in <= {m2p64add_out[BLOCK_SIZE-1-the_lr:0], m2p64add_out[BLOCK_SIZE-1:BLOCK_SIZE-the_lr]};

            curr_state <= 6'd51;
          end
        end
        6'd51 : begin
          if (m2add_rdy == 1'b1) begin
            //SOME OPERATIONS
            add_start <= add_one_in[102];
            xor_start <= add_one_in[103];
            inv_add_start <= add_two_in[102];
            sbpsmc_start <= add_two_in[103];

            //INV SPLT - RND3
            inv_sbpsmc_start <= 1'b1;
            add_one_in <= m2add_out;

            curr_state <= 6'd52;
          end
        end
        6'd52 : begin
          if (inv_sbpsmc_rdy == 1'b1) begin
            //SOME OPERATIONS
            add_start <= add_one_in[104];
            sbpsmc_start <= add_one_in[105];
            inv_add_start <= add_two_in[104];
            inv_sbpsmc_start <= add_two_in[105];

            //XOR - RND2
            xor_start <= 1'b1;
            add_one_in <= inv_sbpsmc_out;
            add_two_in <= tmv_key;

            curr_state <= 6'd53;
          end
        end
        6'd53 : begin
          if (m2add_rdy == 1'b1) begin
            //SOME OPERATIONS
            add_start <= add_one_in[106];
            xor_start <= add_one_in[107];
            inv_add_start <= add_two_in[106];
            sbpsmc_start <= add_two_in[107];

            //RND - KEY0
            rnd_num <= rnd_num - 5'd2;
            //INV SPLT - RND2
            inv_sbpsmc_start <= 1'b1;
            add_one_in <= m2add_out;

            curr_state <= 6'd54;
          end
        end
        //Round 3-2 operations end here and Round 0 key operations start here
        6'd54 : begin
          if (inv_sbpsmc_rdy == 1'b1) begin
            //SOME OPERATIONS
            sbpsmc_start <= add_one_in[108];
            xor_start <= add_one_in[109];
            inv_add_start <= add_two_in[108];
            inv_sbpsmc_start <= add_two_in[109];

            round_out <= inv_sbpsmc_out;
            //ADD - KEY0
            add_start <= 1'b1;
            add_one_in <= int_key;
            add_two_in <= shft_tmv;

            if (rnd_cnt == 5'd10) begin
              curr_state <= 6'd55;
            end
            else if (rnd_cnt == 5'd14) begin
              if (rnd_num == 5'd0) begin
                curr_state <= 6'd55;
              end
              else begin
                curr_state <= 6'd35;
              end
            end
            else begin
              if (rnd_num == 5'd0) begin
                curr_state <= 6'd55;
              end
              else begin
                curr_state <= 6'd15;
              end
            end
          end
        end
        6'd55 : begin
          if (m2p64add_rdy == 1'b1) begin
            //SOME OPERATIONS
            sbpsmc_start <= add_one_in[110];
            xor_start <= add_one_in[111];
            inv_add_start <= add_two_in[110];
            inv_sbpsmc_start <= add_two_in[111];

            tmv_key <= m2p64add_out;

            //ADD - KEY0
            add_one_in <= m2p64add_out;
            add_two_in <= trans_key_in;

            curr_state <= 6'd56;
          end
        end
        6'd56 : begin
          if (m2p64add_rdy == 1'b1) begin
            //SOME OPERATIONS
            add_start <= add_one_in[112];
            xor_start <= add_one_in[113];
            inv_add_start <= add_two_in[112];
            inv_sbpsmc_start <= add_two_in[113];

            //SPLT - KEY0
            sbpsmc_start <= 1'b1;
            add_one_in <= m2p64add_out;

            curr_state <= 6'd57;
          end
        end
        6'd57 : begin
          if (sbpsmc_rdy == 1'b1) begin
            //SOME OPERATIONS
            add_start <= add_one_in[114];
            sbpsmc_start <= add_one_in[115];
            inv_add_start <= add_two_in[114];
            inv_sbpsmc_start <= add_two_in[115];

            //XOR - KEY0
            xor_start <= 1'b1;
            add_one_in <= tmv_key;
            add_two_in <= sbpsmc_out;

            curr_state <= 6'd58;
          end
        end
        6'd58 : begin
          if (m2add_rdy == 1'b1) begin
            //SOME OPERATIONS
            add_start <= add_one_in[116];
            xor_start <= add_one_in[117];
            inv_add_start <= add_two_in[116];
            inv_sbpsmc_start <= add_two_in[117];

            //SPLT - KEY0
            sbpsmc_start <= 1'b1;
            add_one_in <= m2add_out;

            curr_state <= 6'd59;
          end
        end
        6'd59 : begin
          if (sbpsmc_rdy == 1'b1) begin
            //SOME OPERATIONS
            sbpsmc_start <= add_one_in[118];
            xor_start <= add_one_in[119];
            inv_add_start <= add_two_in[118];
            inv_sbpsmc_start <= add_two_in[119];

            //ADD - KEY0
            add_start <= 1'b1;
            add_one_in <= tmv_key;
            add_two_in <= sbpsmc_out;

            curr_state <= 6'd60;
          end
        end
        //Round 0 key generation ends here and Round 1-0 operations start here
        6'd60 : begin
          if (m2p64add_rdy == 1'b1) begin
            //SOME OPERATIONS
            add_start <= add_one_in[120];
            sbpsmc_start <= add_one_in[121];
            inv_add_start <= add_two_in[120];
            inv_sbpsmc_start <= add_two_in[121];

            tmv_key <= m2p64add_out;

            //XOR - RND1
            xor_start <= 1'b1;
            add_one_in <= round_out;
            add_two_in <= {m2p64add_out[BLOCK_SIZE-1-the_lr:0], m2p64add_out[BLOCK_SIZE-1:BLOCK_SIZE-the_lr]};

            curr_state <= 6'd61;
          end
        end
        6'd61 : begin
          if (m2add_rdy == 1'b1) begin
            //SOME OPERATIONS
            add_start <= add_one_in[122];
            xor_start <= add_one_in[123];
            inv_add_start <= add_two_in[122];
            sbpsmc_start <= add_two_in[123];

            //INV SPLT - RND1
            inv_sbpsmc_start <= 1'b1;
            add_one_in <= m2add_out;

            curr_state <= 6'd62;
          end
        end
        6'd62 : begin
          if (inv_sbpsmc_rdy == 1'b1) begin
            //SOME OPERATIONS
            sbpsmc_start <= add_one_in[124];
            xor_start <= add_one_in[125];
            add_start <= add_two_in[124];
            inv_sbpsmc_start <= add_two_in[125];

            //SUB - RND0
            inv_add_start <= 1'b1;
            add_one_in <= inv_sbpsmc_out;
            add_two_in <= tmv_key;

            curr_state <= 6'd63;
          end
        end
        6'd63 : begin
          if (m2p64sub_rdy == 1'b1) begin
            round_out <= m2p64sub_out;
            reg_block_rdy <= 1'b1;

            //SUB - RND0
            add_start <= 1'b0;
            xor_start <= 1'b0;
            sbpsmc_start <= 1'b0;
            inv_add_start <= 1'b0;
            inv_sbpsmc_start <= 1'b0;

            curr_state <= 6'd0;
          end
        end
        default : begin
          rnd_num <= 5'd0;
          add_start <= 1'b0;
          xor_start <= 1'b0;
          curr_state <= 6'd0;
          sbpsmc_start <= 1'b0;
          reg_block_rdy <= 1'b0;
          inv_add_start <= 1'b0;
          inv_sbpsmc_start <= 1'b0;
          tmv_key <= {BLOCK_SIZE{1'b0}};
          int_key <= {BLOCK_SIZE{1'b0}};
          round_out <= {BLOCK_SIZE{1'b0}};
          add_one_in <= {BLOCK_SIZE{1'b0}};
          add_two_in <= {BLOCK_SIZE{1'b0}};
        end
      endcase
    end
  end
end

//Pseudo-Random Number Generator
`ifdef XORSHIFT
  //XORSHIFT
  xorshift64 xs_ins (.clk(clk), .rst(rst), .start(reg_dec_start), .seed(block_in[63:0]), .xs_out(prng_out));
`elsif LFSR
  //LFSR
  lfsr64 lfsr_ins (.clk(clk), .rst(rst), .start(reg_dec_start), .seed(block_in[63:0]), .lfsr_out(prng_out));
`endif

//Additions + Duplications
mod2_add_serial64b #(.BLOCK_SIZE(BLOCK_SIZE)) m2a_ins_one (.clk(clk), .rst(rst), .m2add_start(xor_start), .m2add_in_one(add_one_in), .m2add_in_two(add_two_in), .m2add_out(m2add_out_one), .m2add_rdy(m2add_rdy_one));
mod2_add_serial64b_fom #(.BLOCK_SIZE(BLOCK_SIZE)) m2a_ins_two (.clk(clk), .rst(rst), .m2add_start(xor_start), .m2add_in_one(add_one_in), .m2add_in_two(add_two_in), .lfsr_in(prng_out), .m2add_out(m2add_out_two), .m2add_rdy(m2add_rdy_two));
mod2p64_add_serial64b #(.BLOCK_SIZE(BLOCK_SIZE)) m2p64a_ins_one (.clk(clk), .rst(rst), .m2p64add_start(add_start), .m2p64add_in_one(add_one_in), .m2p64add_in_two(add_two_in), .m2p64add_out(m2p64add_out_one), .m2p64add_rdy(m2p64add_rdy_one));
mod2p64_add_serial64b_fom #(.BLOCK_SIZE(BLOCK_SIZE)) m2p64a_ins_two (.clk(clk), .rst(rst), .m2p64add_start(add_start), .m2p64add_in_one(add_one_in), .m2p64add_in_two(add_two_in), .lfsr_in(prng_out), .m2p64add_out(m2p64add_out_two), .m2p64add_rdy(m2p64add_rdy_two));
//Substitution Permutation Mix-Column + Duplications
sbpsmc_serial64b #(.BLOCK_SIZE(BLOCK_SIZE)) sbpsmc64b_ins_one (.clk(clk), .rst(rst), .sbpsmc_start(sbpsmc_start), .sbpsmc_in(add_one_in), .sbpsmc_out(sbpsmc_out_one), .sbpsmc_rdy(sbpsmc_rdy_one));
sbpsmc_serial64b_fom #(.BLOCK_SIZE(BLOCK_SIZE)) sbpsmc64b_ins_two (.clk(clk), .rst(rst), .sbpsmc_start(sbpsmc_start), .sbpsmc_in(add_one_in), .lfsr_in(prng_out), .sbpsmc_out(sbpsmc_out_two), .sbpsmc_rdy(sbpsmc_rdy_two));
//Inverse Addition + Duplications
inv_mod2p64_add_serial64b #(.BLOCK_SIZE(BLOCK_SIZE)) inv_m2p64a_ins_one (.clk(clk), .rst(rst), .m2p64add_start(inv_add_start), .m2p64add_in_one(add_one_in), .m2p64add_in_two(add_two_in), .m2p64add_out(m2p64sub_out_one), .m2p64add_rdy(m2p64sub_rdy_one));
inv_mod2p64_add_serial64b_fom #(.BLOCK_SIZE(BLOCK_SIZE)) inv_m2p64a_ins_two (.clk(clk), .rst(rst), .m2p64add_start(inv_add_start), .m2p64add_in_one(add_one_in), .m2p64add_in_two(add_two_in), .lfsr_in(prng_out), .m2p64add_out(m2p64sub_out_two), .m2p64add_rdy(m2p64sub_rdy_two));
//Inverse Substitution Permutation Mix-Column + Duplications
inv_sbpsmc_serial64b #(.BLOCK_SIZE(BLOCK_SIZE)) inv_sbpsmc64b_ins_one (.clk(clk), .rst(rst), .sbpsmc_start(inv_sbpsmc_start), .sbpsmc_in(add_one_in), .sbpsmc_out(inv_sbpsmc_out_one), .sbpsmc_rdy(inv_sbpsmc_rdy_one));
inv_sbpsmc_serial64b_fom #(.BLOCK_SIZE(BLOCK_SIZE)) inv_sbpsmc64b_ins_two (.clk(clk), .rst(rst), .sbpsmc_start(inv_sbpsmc_start), .sbpsmc_in(add_one_in), .lfsr_in(prng_out), .sbpsmc_out(inv_sbpsmc_out_two), .sbpsmc_rdy(inv_sbpsmc_rdy_two));

//Duplication Comparisons
//Modulo 2 Addition
assign m2add_rdy = m2add_rdy_one & m2add_rdy_two;
always @ (m2add_rdy, m2add_out_one, m2add_out_two) begin
  if (m2add_rdy == 1'b1) begin
    if (m2add_out_one == m2add_out_two) begin
      m2add_out = m2add_out_one;
    end
    else begin
      m2add_out = {BLOCK_SIZE{1'b0}};
    end
  end
  else begin
    m2add_out = m2add_out_one;
  end
end
//Modulo 2^64 Addition
assign m2p64add_rdy = m2p64add_rdy_one & m2p64add_rdy_two;
always @ (m2p64add_rdy, m2p64add_out_one, m2p64add_out_two) begin
  if (m2p64add_rdy == 1'b1) begin
    if (m2p64add_out_one == m2p64add_out_two) begin
      m2p64add_out = m2p64add_out_one;
    end
    else begin
      m2p64add_out = {BLOCK_SIZE{1'b0}};
    end
  end
  else begin
    m2p64add_out = m2p64add_out_one;
  end
end
//SPM
assign sbpsmc_rdy = sbpsmc_rdy_one & sbpsmc_rdy_two;
always @ (sbpsmc_rdy, sbpsmc_out_one, sbpsmc_out_two) begin
  if (sbpsmc_rdy == 1'b1) begin
    if (sbpsmc_out_one == sbpsmc_out_two) begin
      sbpsmc_out = sbpsmc_out_one;
    end
    else begin
      sbpsmc_out = {BLOCK_SIZE{1'b0}};
    end
  end
  else begin
    sbpsmc_out = sbpsmc_out_one;
  end
end
//Modulo 2^64 Subtraction
assign m2p64sub_rdy = m2p64sub_rdy_one & m2p64sub_rdy_two;
always @ (m2p64sub_rdy, m2p64sub_out_one, m2p64sub_out_two) begin
  if (m2p64sub_rdy == 1'b1) begin
    if (m2p64sub_out_one == m2p64sub_out_two) begin
      m2p64sub_out = m2p64sub_out_one;
    end
    else begin
      m2p64sub_out = {BLOCK_SIZE{1'b0}};
    end
  end
  else begin
    m2p64sub_out = m2p64sub_out_one;
  end
end
//Inverse SPM
assign inv_sbpsmc_rdy = inv_sbpsmc_rdy_one & inv_sbpsmc_rdy_two;
always @ (inv_sbpsmc_rdy, inv_sbpsmc_out_one, inv_sbpsmc_out_two) begin
  if (inv_sbpsmc_rdy == 1'b1) begin
    if (inv_sbpsmc_out_one == inv_sbpsmc_out_two) begin
      inv_sbpsmc_out = inv_sbpsmc_out_one;
    end
    else begin
      inv_sbpsmc_out = {BLOCK_SIZE{1'b0}};
    end
  end
  else begin
    inv_sbpsmc_out = inv_sbpsmc_out_one;
  end
end

//Fault Injection
assign flt_inj = ((m2add_rdy & m2add_out_one != m2add_out_two) | (m2p64add_rdy & m2p64add_out_one != m2p64add_out_two) | (sbpsmc_rdy & sbpsmc_out_one != sbpsmc_out_two) | (m2p64sub_rdy & m2p64sub_out_one != m2p64sub_out_two) | (inv_sbpsmc_rdy & inv_sbpsmc_out_one != inv_sbpsmc_out_two)) ? 1'b1 : 1'b0;
always @ (posedge clk) begin
  if (rst == 1'b1) begin
    reg_flt_inj <= 1'b0;
  end
  else begin
    if (flt_inj == 1'b1) begin
      reg_flt_inj <= 1'b1;
    end
  end
end

//Previous current state
always @ (posedge clk) begin
  if (rst == 1'b1) begin
    pre_curr_state <= 6'd0;
  end
  else begin
    if (reg_dec_start == 1'b0) begin
      pre_curr_state <= 6'd0;
    end
    else begin
      if (m2add_rdy == 1'b1 | m2p64add_rdy == 1'b1 | sbpsmc_rdy == 1'b1 | m2p64sub_rdy == 1'b1 | inv_sbpsmc_rdy == 1'b1) begin
        pre_curr_state <= curr_state;
      end
    end
  end
end

//Fault in the state
assign flt_state = (pre_curr_state != 6'd54 & pre_curr_state != 6'd63 & curr_state - pre_curr_state > 6'd1) ? 1'b1 : 1'b0;
always @ (posedge clk) begin
  if (rst == 1'b1) begin
    reg_flt_state <= 1'b0;
  end
  else begin
    if (flt_state == 1'b1) begin
      reg_flt_state <= 1'b1;
    end
  end
end

//Block Outputs
always @ (posedge clk) begin
  if (rst == 1'b1) begin
    block_rdy <= 1'b0;
    block_out <= {BLOCK_SIZE{1'b0}};
  end
  else begin
    if (reg_dec_start == 1'b0) begin
      block_rdy <= 1'b0;
      block_out <= {BLOCK_SIZE{1'b0}};
    end
    else begin
      if (reg_block_rdy == 1'b1) begin
        block_rdy <= 1'b1;
        block_out <= round_out;
      end
    end
  end
end

endmodule

//KALYNA DECRYPTION BLOCK - SERIAL - ONE 64-bit OPERATION in ONE CLOCK CYCLE - First-Order Masking + Hiding
module kalyna_dec_block_serial64b_oboc_fomhid #(parameter BLOCK_SIZE = 128, parameter KEY_LENGTH = 128) (clk, rst, start, block_in, key_in, block_out, block_rdy);

input clk, rst, start;
input [BLOCK_SIZE-1:0] block_in;
input [KEY_LENGTH-1:0] key_in;
output reg [BLOCK_SIZE-1:0] block_out;
output reg block_rdy;

//Local parameters
localparam bs_m8 = BLOCK_SIZE - 8;
localparam bs_d16 = BLOCK_SIZE/16;
localparam the_lr = (BLOCK_SIZE/4+24);
localparam rnd_cnt = (BLOCK_SIZE == KEY_LENGTH && BLOCK_SIZE == 128) ? 5'd10 : (BLOCK_SIZE == KEY_LENGTH && BLOCK_SIZE == 256) ? 5'd14 : (BLOCK_SIZE == KEY_LENGTH && BLOCK_SIZE == 512) ? 5'd18 : (BLOCK_SIZE != KEY_LENGTH && BLOCK_SIZE == 128) ? 5'd14 : 5'd18;

//Variables
reg [4:0] rnd_num;
reg [5:0] curr_state;
reg [KEY_LENGTH-1:0] trans_in;
reg xor_start, add_start, sbpsmc_start, inv_add_start, inv_sbpsmc_start, reg_block_rdy, reg_dec_start;
reg [BLOCK_SIZE-1:0] key_alfa, key_omega, add_one_in, add_two_in, int_key, shft_tmv, trans_key_in, tmv_key, round_out;
wire [63:0] prng_out;
wire [BLOCK_SIZE-1:0] int_key_in, the_tmv;
wire [7:0] the_const = (BLOCK_SIZE+KEY_LENGTH)/64 + 1;
wire m2add_rdy, m2p64add_rdy, sbpsmc_rdy, m2p64sub_rdy, inv_sbpsmc_rdy;
wire [BLOCK_SIZE-1:0] m2add_out, m2p64add_out, sbpsmc_out, m2p64sub_out, inv_sbpsmc_out;

//Input to the intermediate key transformation
assign int_key_in = {the_const, {bs_m8{1'b0}}};

//Alfa and Omega Keys for the intermediate key transformation
always @ (*) begin
  if (BLOCK_SIZE == KEY_LENGTH) begin
    key_alfa = key_in;
    key_omega = key_in;
  end
  else begin
    key_alfa = key_in[KEY_LENGTH-1:KEY_LENGTH/2];
    key_omega = key_in[KEY_LENGTH/2-1:0];
  end
end

//Generation of the TMV signal and its shifted version
assign the_tmv= {bs_d16{16'h0100}};
always @ (*) begin
  case (rnd_num)
    5'd0    : shft_tmv = the_tmv;
    5'd2    : shft_tmv = {the_tmv[BLOCK_SIZE-2:0],  1'd0};
    5'd4    : shft_tmv = {the_tmv[BLOCK_SIZE-3:0],  2'd0};
    5'd6    : shft_tmv = {the_tmv[BLOCK_SIZE-4:0],  3'd0};
    5'd8    : shft_tmv = {the_tmv[BLOCK_SIZE-5:0],  4'd0};
    5'd10   : shft_tmv = {the_tmv[BLOCK_SIZE-6:0],  5'd0};
    5'd12   : shft_tmv = {the_tmv[BLOCK_SIZE-7:0],  6'd0};
    5'd14   : shft_tmv = {the_tmv[BLOCK_SIZE-8:0],  7'd0};
    5'd16   : shft_tmv = {the_tmv[BLOCK_SIZE-9:0],  7'd0, 1'b1};
    5'd18   : shft_tmv = {the_tmv[BLOCK_SIZE-10:0], 7'd0, 1'b1, 1'b0}; //Last two lines are due to the conflict between rotate and shift
    default : shft_tmv = the_tmv;
  endcase
end

//Generation of the input to the transformations
always @ (*) begin
  if (BLOCK_SIZE == KEY_LENGTH) begin
    if (BLOCK_SIZE == 128) begin
      case (rnd_num) 
        5'd0    : trans_in = key_in;
        5'd2    : trans_in = {key_in[63:0], key_in[127:64]};
        5'd4    : trans_in = key_in;
        5'd6    : trans_in = {key_in[63:0], key_in[127:64]};
        5'd8    : trans_in = key_in;
        5'd10   : trans_in = {key_in[63:0], key_in[127:64]};
        default : trans_in = key_in;
      endcase
    end
    else if (BLOCK_SIZE == 256) begin
      case (rnd_num) 
        5'd0    : trans_in = key_in;
        5'd2    : trans_in = {key_in[191:0], key_in[255:192]};
        5'd4    : trans_in = {key_in[127:0], key_in[255:128]};
        5'd6    : trans_in = {key_in[63:0],  key_in[255:64]};
        5'd8    : trans_in = key_in;
        5'd10   : trans_in = {key_in[191:0], key_in[255:192]};
        5'd12   : trans_in = {key_in[127:0], key_in[255:128]};
        5'd14   : trans_in = {key_in[63:0],  key_in[255:64]};
        default : trans_in = key_in;
      endcase
    end
    else begin
      case (rnd_num) 
        5'd0    : trans_in = key_in;
        5'd2    : trans_in = {key_in[447:0], key_in[511:448]};
        5'd4    : trans_in = {key_in[383:0], key_in[511:384]};
        5'd6    : trans_in = {key_in[319:0], key_in[511:320]};
        5'd8    : trans_in = {key_in[255:0], key_in[511:256]};
        5'd10   : trans_in = {key_in[191:0], key_in[511:192]};
        5'd12   : trans_in = {key_in[127:0], key_in[511:128]};
        5'd14   : trans_in = {key_in[63:0],  key_in[511:64]};
        5'd16   : trans_in = key_in;
        5'd18   : trans_in = {key_in[447:0], key_in[511:448]};
        default : trans_in = key_in;
      endcase
    end
  end
  else begin
    if (BLOCK_SIZE == 128) begin
      case (rnd_num) 
        5'd0    : trans_in = key_in;
        5'd2    : trans_in = key_in;
        5'd4    : trans_in = {key_in[191:0], key_in[255:192]};
        5'd6    : trans_in = {key_in[191:0], key_in[255:192]};
        5'd8    : trans_in = {key_in[127:0], key_in[255:128]};
        5'd10   : trans_in = {key_in[127:0], key_in[255:128]};
        5'd12   : trans_in = {key_in[63:0],  key_in[255:64]};
        5'd14   : trans_in = {key_in[63:0],  key_in[255:64]};
        default : trans_in = key_in;
      endcase
    end
    else begin
      case (rnd_num) 
        5'd0    : trans_in = key_in;
        5'd2    : trans_in = key_in;
        5'd4    : trans_in = {key_in[447:0], key_in[511:448]};
        5'd6    : trans_in = {key_in[447:0], key_in[511:448]};
        5'd8    : trans_in = {key_in[383:0], key_in[511:384]};
        5'd10   : trans_in = {key_in[383:0], key_in[511:384]};
        5'd12   : trans_in = {key_in[319:0], key_in[511:320]};
        5'd14   : trans_in = {key_in[319:0], key_in[511:320]};
        5'd16   : trans_in = {key_in[255:0], key_in[511:256]};
        5'd18   : trans_in = {key_in[255:0], key_in[511:256]};
        default : trans_in = key_in;
      endcase
    end
  end
end
always @ (*) begin
  if (BLOCK_SIZE == KEY_LENGTH) begin
    trans_key_in = trans_in;
  end
  else begin
    case (rnd_num) 
      5'd0    : trans_key_in = trans_in[KEY_LENGTH-1:KEY_LENGTH-BLOCK_SIZE];
      5'd2    : trans_key_in = trans_in[BLOCK_SIZE-1:0];
      5'd4    : trans_key_in = trans_in[KEY_LENGTH-1:KEY_LENGTH-BLOCK_SIZE]; 
      5'd6    : trans_key_in = trans_in[BLOCK_SIZE-1:0]; 
      5'd8    : trans_key_in = trans_in[KEY_LENGTH-1:KEY_LENGTH-BLOCK_SIZE]; 
      5'd10   : trans_key_in = trans_in[BLOCK_SIZE-1:0]; 
      5'd12   : trans_key_in = trans_in[KEY_LENGTH-1:KEY_LENGTH-BLOCK_SIZE]; 
      5'd14   : trans_key_in = trans_in[BLOCK_SIZE-1:0]; 
      5'd16   : trans_key_in = trans_in[KEY_LENGTH-1:KEY_LENGTH-BLOCK_SIZE]; 
      5'd18   : trans_key_in = trans_in[BLOCK_SIZE-1:0]; 
      default : trans_key_in = trans_in[BLOCK_SIZE-1:0]; 
    endcase
  end
end

//The reg_dec_start signal indicates that the encryption process is started
always @ (posedge clk) begin
  if (rst == 1'b1) begin
    reg_dec_start <= 1'b0;
  end
  else begin
    if (block_rdy == 1'b1) begin
      reg_dec_start <= 1'b0;
    end
    else begin
      if (start == 1'b1) begin
        reg_dec_start <= 1'b1;
      end
    end
  end
end

//Block inputs in each state  
always @ (posedge clk) begin
  if (rst == 1'b1) begin
    rnd_num <= 5'd0;
    add_start <= 1'b0;
    xor_start <= 1'b0;
    curr_state <= 6'd0;
    sbpsmc_start <= 1'b0;
    reg_block_rdy <= 1'b0;
    inv_add_start <= 1'b0;
    inv_sbpsmc_start <= 1'b0;
    tmv_key <= {BLOCK_SIZE{1'b0}};
    int_key <= {BLOCK_SIZE{1'b0}};
    round_out <= {BLOCK_SIZE{1'b0}};
    add_one_in <= {BLOCK_SIZE{1'b0}};
    add_two_in <= {BLOCK_SIZE{1'b0}};
  end
  else begin
    if (reg_dec_start == 1'b0) begin
      rnd_num <= 5'd0;
      add_start <= 1'b0;
      xor_start <= 1'b0;
      curr_state <= 6'd0;
      sbpsmc_start <= 1'b0;
      reg_block_rdy <= 1'b0;
