        end
        6'd42 : begin
          if (inv_sbpsmc_rdy == 1'b1) begin
            //SOME OPERATIONS
            add_start <= add_one_in[84];
            sbpsmc_start <= add_one_in[85];
            inv_add_start <= add_two_in[84];
            inv_sbpsmc_start <= add_two_in[85];

            //XOR - RND4
            xor_start <= 1'b1;
            add_one_in <= inv_sbpsmc_out;
