            inv_add_start <= add_two_in[106];
            sbpsmc_start <= add_two_in[107];

            //RND - KEY0
            rnd_num <= rnd_num - 5'd2;
            //INV SPLT - RND2
            inv_sbpsmc_start <= 1'b1;
