            else if (rnd_cnt == 5'd14) begin
              if (rnd_num == 5'd0) begin
                curr_state <= 6'd55;
              end
              else begin
                curr_state <= 6'd35;
              end
            end
            else begin
              if (rnd_num == 5'd0) begin
                curr_state <= 6'd55;
              end
              else begin
                curr_state <= 6'd15;
              end
            end
          end
        end
        6'd55 : begin
          if (m2p64add_rdy == 1'b1) begin
