            sbpsmc_start <= 1'b1;
            add_one_in <= m2add_out;

            curr_state <= 6'd49;
          end
        end
        6'd49 : begin
          if (sbpsmc_rdy == 1'b1) begin
            //SOME OPERATIONS
            sbpsmc_start <= add_one_in[98];
            xor_start <= add_one_in[99];
            inv_add_start <= add_two_in[98];
            inv_sbpsmc_start <= add_two_in[99];

            //ADD - KEY2
            add_start <= 1'b1;
            add_one_in <= tmv_key;
            add_two_in <= sbpsmc_out;

            curr_state <= 6'd50;
          end
        end
        //Round 2 key generation ends here and Round 3-2 operations start here
        6'd50 : begin
          if (m2p64add_rdy == 1'b1) begin
            //SOME OPERATIONS
            add_start <= add_one_in[100];
            sbpsmc_start <= add_one_in[101];
            inv_add_start <= add_two_in[100];
            inv_sbpsmc_start <= add_two_in[101];

            tmv_key <= m2p64add_out;
            //XOR - RND3
            xor_start <= 1'b1;
            add_one_in <= round_out;
            add_two_in <= {m2p64add_out[BLOCK_SIZE-1-the_lr:0], m2p64add_out[BLOCK_SIZE-1:BLOCK_SIZE-the_lr]};

            curr_state <= 6'd51;
          end
        end
        6'd51 : begin
          if (m2add_rdy == 1'b1) begin
            //SOME OPERATIONS
            add_start <= add_one_in[102];
            xor_start <= add_one_in[103];
            inv_add_start <= add_two_in[102];
            sbpsmc_start <= add_two_in[103];

            //INV SPLT - RND3
            inv_sbpsmc_start <= 1'b1;
            add_one_in <= m2add_out;

            curr_state <= 6'd52;
          end
        end
        6'd52 : begin
          if (inv_sbpsmc_rdy == 1'b1) begin
            //SOME OPERATIONS
            add_start <= add_one_in[104];
            sbpsmc_start <= add_one_in[105];
            inv_add_start <= add_two_in[104];
            inv_sbpsmc_start <= add_two_in[105];

            //XOR - RND2
            xor_start <= 1'b1;
            add_one_in <= inv_sbpsmc_out;
            add_two_in <= tmv_key;

            curr_state <= 6'd53;
          end
        end
        6'd53 : begin
          if (m2add_rdy == 1'b1) begin
            //SOME OPERATIONS
            add_start <= add_one_in[106];
            xor_start <= add_one_in[107];
            inv_add_start <= add_two_in[106];
            sbpsmc_start <= add_two_in[107];

            //RND - KEY0
            rnd_num <= rnd_num - 5'd2;
            //INV SPLT - RND2
            inv_sbpsmc_start <= 1'b1;
            add_one_in <= m2add_out;

            curr_state <= 6'd54;
          end
        end
        //Round 3-2 operations end here and Round 0 key operations start here
        6'd54 : begin
          if (inv_sbpsmc_rdy == 1'b1) begin
            //SOME OPERATIONS
            sbpsmc_start <= add_one_in[108];
            xor_start <= add_one_in[109];
            inv_add_start <= add_two_in[108];
            inv_sbpsmc_start <= add_two_in[109];

            round_out <= inv_sbpsmc_out;
            //ADD - KEY0
            add_start <= 1'b1;
            add_one_in <= int_key;
            add_two_in <= shft_tmv;

            if (rnd_cnt == 5'd10) begin
              curr_state <= 6'd55;
            end
            else if (rnd_cnt == 5'd14) begin
              if (rnd_num == 5'd0) begin
                curr_state <= 6'd55;
              end
              else begin
                curr_state <= 6'd35;
              end
            end
            else begin
              if (rnd_num == 5'd0) begin
                curr_state <= 6'd55;
              end
              else begin
                curr_state <= 6'd15;
              end
            end
          end
        end
        6'd55 : begin
          if (m2p64add_rdy == 1'b1) begin
            //SOME OPERATIONS
            sbpsmc_start <= add_one_in[110];
            xor_start <= add_one_in[111];
            inv_add_start <= add_two_in[110];
            inv_sbpsmc_start <= add_two_in[111];

            tmv_key <= m2p64add_out;

            //ADD - KEY0
            add_one_in <= m2p64add_out;
            add_two_in <= trans_key_in;

            curr_state <= 6'd56;
          end
        end
        6'd56 : begin
          if (m2p64add_rdy == 1'b1) begin
            //SOME OPERATIONS
            add_start <= add_one_in[112];
            xor_start <= add_one_in[113];
            inv_add_start <= add_two_in[112];
            inv_sbpsmc_start <= add_two_in[113];

            //SPLT - KEY0
            sbpsmc_start <= 1'b1;
            add_one_in <= m2p64add_out;

            curr_state <= 6'd57;
          end
        end
        6'd57 : begin
          if (sbpsmc_rdy == 1'b1) begin
            //SOME OPERATIONS
            add_start <= add_one_in[114];
            sbpsmc_start <= add_one_in[115];
            inv_add_start <= add_two_in[114];
            inv_sbpsmc_start <= add_two_in[115];

            //XOR - KEY0
            xor_start <= 1'b1;
            add_one_in <= tmv_key;
            add_two_in <= sbpsmc_out;

            curr_state <= 6'd58;
          end
        end
        6'd58 : begin
          if (m2add_rdy == 1'b1) begin
            //SOME OPERATIONS
            add_start <= add_one_in[116];
            xor_start <= add_one_in[117];
            inv_add_start <= add_two_in[116];
            inv_sbpsmc_start <= add_two_in[117];

            //SPLT - KEY0
            sbpsmc_start <= 1'b1;
            add_one_in <= m2add_out;

            curr_state <= 6'd59;
          end
        end
        6'd59 : begin
          if (sbpsmc_rdy == 1'b1) begin
            //SOME OPERATIONS
            sbpsmc_start <= add_one_in[118];
            xor_start <= add_one_in[119];
            inv_add_start <= add_two_in[118];
            inv_sbpsmc_start <= add_two_in[119];

            //ADD - KEY0
            add_start <= 1'b1;
            add_one_in <= tmv_key;
            add_two_in <= sbpsmc_out;

            curr_state <= 6'd60;
          end
        end
        //Round 0 key generation ends here and Round 1-0 operations start here
        6'd60 : begin
          if (m2p64add_rdy == 1'b1) begin
            //SOME OPERATIONS
            add_start <= add_one_in[120];
            sbpsmc_start <= add_one_in[121];
            inv_add_start <= add_two_in[120];
            inv_sbpsmc_start <= add_two_in[121];

            tmv_key <= m2p64add_out;

            //XOR - RND1
            xor_start <= 1'b1;
            add_one_in <= round_out;
            add_two_in <= {m2p64add_out[BLOCK_SIZE-1-the_lr:0], m2p64add_out[BLOCK_SIZE-1:BLOCK_SIZE-the_lr]};

            curr_state <= 6'd61;
          end
        end
        6'd61 : begin
          if (m2add_rdy == 1'b1) begin
            //SOME OPERATIONS
            add_start <= add_one_in[122];
            xor_start <= add_one_in[123];
            inv_add_start <= add_two_in[122];
            sbpsmc_start <= add_two_in[123];

            //INV SPLT - RND1
            inv_sbpsmc_start <= 1'b1;
            add_one_in <= m2add_out;

            curr_state <= 6'd62;
          end
        end
        6'd62 : begin
          if (inv_sbpsmc_rdy == 1'b1) begin
            //SOME OPERATIONS
            sbpsmc_start <= add_one_in[124];
            xor_start <= add_one_in[125];
            add_start <= add_two_in[124];
            inv_sbpsmc_start <= add_two_in[125];

            //SUB - RND0
            inv_add_start <= 1'b1;
            add_one_in <= inv_sbpsmc_out;
            add_two_in <= tmv_key;

            curr_state <= 6'd63;
          end
        end
        6'd63 : begin
          if (m2p64sub_rdy == 1'b1) begin
            round_out <= m2p64sub_out;
            reg_block_rdy <= 1'b1;

            //SUB - RND0
            add_start <= 1'b0;
            xor_start <= 1'b0;
            sbpsmc_start <= 1'b0;
            inv_add_start <= 1'b0;
            inv_sbpsmc_start <= 1'b0;

            curr_state <= 6'd0;
          end
        end
        default : begin
          rnd_num <= 5'd0;
          add_start <= 1'b0;
          xor_start <= 1'b0;
          curr_state <= 6'd0;
          sbpsmc_start <= 1'b0;
          reg_block_rdy <= 1'b0;
          inv_add_start <= 1'b0;
          inv_sbpsmc_start <= 1'b0;
          tmv_key <= {BLOCK_SIZE{1'b0}};
          int_key <= {BLOCK_SIZE{1'b0}};
          round_out <= {BLOCK_SIZE{1'b0}};
          add_one_in <= {BLOCK_SIZE{1'b0}};
          add_two_in <= {BLOCK_SIZE{1'b0}};
        end
      endcase
    end
  end
end

//Additions
mod2_add_serial64b #(.BLOCK_SIZE(BLOCK_SIZE)) m2a_ins (.clk(clk), .rst(rst), .m2add_start(xor_start), .m2add_in_one(add_one_in), .m2add_in_two(add_two_in), .m2add_out(m2add_out), .m2add_rdy(m2add_rdy));
mod2p64_add_serial64b #(.BLOCK_SIZE(BLOCK_SIZE)) m2p64a_ins (.clk(clk), .rst(rst), .m2p64add_start(add_start), .m2p64add_in_one(add_one_in), .m2p64add_in_two(add_two_in), .m2p64add_out(m2p64add_out), .m2p64add_rdy(m2p64add_rdy));
//Substitution Permutation Mix-Column
sbpsmc_serial64b #(.BLOCK_SIZE(BLOCK_SIZE)) sbpsmc64b_ins (.clk(clk), .rst(rst), .sbpsmc_start(sbpsmc_start), .sbpsmc_in(add_one_in), .sbpsmc_out(sbpsmc_out), .sbpsmc_rdy(sbpsmc_rdy));
//Inverse Addition
inv_mod2p64_add_serial64b #(.BLOCK_SIZE(BLOCK_SIZE)) inv_m2p64a_ins (.clk(clk), .rst(rst), .m2p64add_start(inv_add_start), .m2p64add_in_one(add_one_in), .m2p64add_in_two(add_two_in), .m2p64add_out(m2p64sub_out), .m2p64add_rdy(m2p64sub_rdy));
//Inverse Substitution Permutation Mix-Column
inv_sbpsmc_serial64b #(.BLOCK_SIZE(BLOCK_SIZE)) inv_sbpsmc64b_ins (.clk(clk), .rst(rst), .sbpsmc_start(inv_sbpsmc_start), .sbpsmc_in(add_one_in), .sbpsmc_out(inv_sbpsmc_out), .sbpsmc_rdy(inv_sbpsmc_rdy));

//Block Outputs
always @ (posedge clk) begin
  if (rst == 1'b1) begin
    block_rdy <= 1'b0;
    block_out <= {BLOCK_SIZE{1'b0}};
  end
  else begin
    if (reg_dec_start == 1'b0) begin
      block_rdy <= 1'b0;
      block_out <= {BLOCK_SIZE{1'b0}};
    end
    else begin
      if (reg_block_rdy == 1'b1) begin
        block_rdy <= 1'b1;
        block_out <= round_out;
      end
    end
  end
end

endmodule

//KALYNA DECRYPTION BLOCK - SERIAL - ONE ROUND in ONE CLOCK CYCLE
module kalyna_dec_block_serial #(parameter BLOCK_SIZE = 512, parameter KEY_LENGTH = 512) (clk, rst, start, block_in, key_in, block_out, block_rdy);

input clk, rst, start;
input [BLOCK_SIZE-1:0] block_in;
input [KEY_LENGTH-1:0] key_in;
output reg [BLOCK_SIZE-1:0] block_out;
output reg block_rdy;

localparam rnd_cnt = (BLOCK_SIZE == KEY_LENGTH && BLOCK_SIZE == 128) ? 5'd10 : (BLOCK_SIZE == KEY_LENGTH && BLOCK_SIZE == 256) ? 5'd14 : (BLOCK_SIZE == KEY_LENGTH && BLOCK_SIZE == 512) ? 5'd18 : (BLOCK_SIZE != KEY_LENGTH && BLOCK_SIZE == 128) ? 5'd14 : 5'd18;

//Variables
reg [4:0] rnd_counter, eo_counter, eo_index, rnd_index;
wire [BLOCK_SIZE-1:0] int_key, even_key, odd_key;
wire [BLOCK_SIZE-1:0] m2p64add_out, m2_out, mc_out, ps_out, sb_out;
reg [BLOCK_SIZE-1:0] sb_reg, m2p64_block_in, m2p64_key_in, m2_key_in, mc_block_in;

//Counters
always @ (posedge clk) begin
  if (rst == 1'b1) begin
    rnd_counter <= 5'd0;
    eo_counter <= rnd_cnt;
  end
  else begin
    if (start == 1'b0) begin
      rnd_counter <= 5'd0;
      eo_counter <= rnd_cnt;
    end
    else begin
      if (rnd_counter <= rnd_cnt + 1'b1) begin
        rnd_counter <= rnd_counter + 1'd1;

        if (rnd_counter[0] == 1'b0) begin
          eo_counter <= eo_counter - 2'd2;
        end
      end
    end
  end
end
//rnd_index
always @ (*) begin
  if (rnd_counter > 5'd0) begin
    rnd_index = rnd_counter - 1'b1;
  end
  else begin
    rnd_index = 5'd0;
  end
end
//eo_index
always @ (*) begin
  if (rnd_counter <= rnd_cnt + 2'd2) begin
    eo_index = eo_counter + 2'd2;
  end
  else begin
    eo_index = rnd_cnt;
  end
end

//Registers
always @ (posedge clk) begin
  if (rst == 1'b1) begin
    block_out <= {BLOCK_SIZE{1'b0}};
    sb_reg <= {BLOCK_SIZE{1'b0}};
    block_rdy <= 1'b0;
  end
  else begin
    if (start == 1'b0) begin
      block_out <= {BLOCK_SIZE{1'b0}};
      sb_reg <= {BLOCK_SIZE{1'b0}};
      block_rdy <= 1'b0;
    end
    else begin
      sb_reg <= sb_out;

      if (rnd_index == rnd_cnt) begin
        block_out <= m2p64add_out;
        block_rdy <= 1'b1;
      end
      else begin
        block_out <= {BLOCK_SIZE{1'b0}};
        block_rdy <= 1'b0;
      end
    end
  end
end

//m2p64_block_in and m2p64_key_in
always @ (*) begin
  if (rnd_index == 5'd0 || rnd_index == 5'd1) begin
    m2p64_block_in = block_in;
    m2p64_key_in = even_key;
  end
  else if (rnd_index == rnd_cnt) begin
    m2p64_block_in = sb_out;
    m2p64_key_in = even_key;
  end
  else begin
    m2p64_block_in = {BLOCK_SIZE{1'b0}};
    m2p64_key_in = {BLOCK_SIZE{1'b0}};
  end
end

//m2_key_in
always @ (*) begin
  if (rnd_index[0] == 1'b0) begin
    m2_key_in = odd_key;
  end
  else begin
    m2_key_in = even_key;
  end
end

//mc_block_in
always @ (*) begin
  if (rnd_index == 5'd0 || rnd_index == 5'd1) begin
    mc_block_in = m2p64add_out;
  end
  else begin
    mc_block_in = m2_out;
  end
end

//Generate Intermediate Even and Odd Keys
gen_int_key #(.BLOCK_SIZE(BLOCK_SIZE), .KEY_LENGTH(KEY_LENGTH)) gik_ins (.key_in(key_in), .int_key_out(int_key));
gen_even_rnd_key # (.BLOCK_SIZE(BLOCK_SIZE), .KEY_LENGTH(KEY_LENGTH)) gerk_ins (.key_in(key_in), .int_key_in(int_key), .rnd_num_in(eo_index), .even_key_out(even_key));
gen_odd_rnd_key # (.BLOCK_SIZE(BLOCK_SIZE)) gork_ins (.even_key_in(even_key), .odd_key_out(odd_key));

//Transformations
mod2p64_sub #(.BLOCK_SIZE(BLOCK_SIZE)) m2p64_ins (.m2p64sub_in_one(m2p64_block_in), .m2p64sub_in_two(m2p64_key_in), .m2p64sub_out(m2p64add_out));
mod2_add #(.BLOCK_SIZE(BLOCK_SIZE)) m2_ins (.m2add_in_one(sb_reg), .m2add_in_two(m2_key_in), .m2add_out(m2_out));
inv_mix_column #(.BLOCK_SIZE(BLOCK_SIZE)) mx_ins (.mc_in(mc_block_in), .mc_out(mc_out));
inv_permute_state #(.BLOCK_SIZE(BLOCK_SIZE)) ps_ins (.ps_in(mc_out), .ps_out(ps_out));
inv_substitute_byte_foursbox #(.BLOCK_SIZE(BLOCK_SIZE)) sb_ins (.sb_in(ps_out), .sb_out(sb_out));

endmodule

//KALYNA DECRYPTION BLOCK - SERIAL - TWO ROUNDS IN ONE CLOCK CYCLE
module kalyna_dec_block_serial_2rnd # (parameter BLOCK_SIZE = 512, parameter KEY_LENGTH = 512) (clk, rst, start, block_in, key_in, block_out, block_rdy);

input clk, rst, start;
input [BLOCK_SIZE-1:0] block_in;
input [KEY_LENGTH-1:0] key_in;
output reg [BLOCK_SIZE-1:0] block_out;
output reg block_rdy;

localparam rnd_cnt = (BLOCK_SIZE == KEY_LENGTH && BLOCK_SIZE == 128) ? 5'd10 : (BLOCK_SIZE == KEY_LENGTH && BLOCK_SIZE == 256) ? 5'd14 : (BLOCK_SIZE == KEY_LENGTH && BLOCK_SIZE == 512) ? 5'd18 : (BLOCK_SIZE != KEY_LENGTH && BLOCK_SIZE == 128) ? 5'd14 : 5'd18;

//Variables
wire [4:0] eo_index;
reg [4:0] rnd_counter, rnd_index;
reg [BLOCK_SIZE-1:0] sb0_reg, m2p64_block_in, m2p64_key_in, mc0_block_in;
wire [BLOCK_SIZE-1:0] int_key, odd_key, even_key;
wire [BLOCK_SIZE-1:0] sb1_out, ps1_out, mc1_out, m21_out, sb0_out, ps0_out, mc0_out, m20_out, m2p64add_out;

//Counters
always @ (posedge clk) begin
  if (rst == 1'b1) begin
    rnd_counter <= 5'd0;
  end
  else begin
    if (start == 1'b0) begin
      rnd_counter <= 5'd0;
    end
    else begin
      if (rnd_counter <= rnd_cnt + 2'd2) begin
        rnd_counter <= rnd_counter + 2'd2;
      end
    end
  end
end
//rnd_index
always @ (*) begin
  if (rnd_counter > 5'd0) begin
    rnd_index = rnd_counter - 2'd2;
  end
  else begin
    rnd_index = 5'd0;
  end
end
//eo_index
assign eo_index = rnd_cnt - rnd_index;

//Registers
always @ (posedge clk) begin
  if (rst == 1'b1 || start == 1'b0) begin
    sb0_reg <= {BLOCK_SIZE{1'b0}};
    block_out <= {BLOCK_SIZE{1'b0}};
    block_rdy <= 1'b0;
  end
  else begin
    sb0_reg <= sb0_out;
    if (rnd_index == rnd_cnt) begin
      block_out <= m2p64add_out;
      block_rdy <= 1'b1;
    end
    else begin
      block_out <= {BLOCK_SIZE{1'b0}};
      block_rdy <= 1'b0;
    end
  end
end

//m2p64_block_in and m2p64_key_in
always @ (*) begin
  if (rnd_index == 5'd0) begin
    m2p64_block_in = block_in;
    m2p64_key_in = even_key;
  end
  else if (rnd_index == rnd_cnt) begin
    m2p64_block_in = sb1_out;
    m2p64_key_in = even_key;
  end
  else begin
    m2p64_block_in = {BLOCK_SIZE{1'b0}};
    m2p64_key_in = {BLOCK_SIZE{1'b0}};
  end
end

//mc0_block_in
always @ (*) begin
  if (rnd_index == 5'd0) begin
    mc0_block_in = m2p64add_out;
  end
  else begin
    mc0_block_in = m20_out;
  end
end

//Generate Intermediate Even and Odd Keys
gen_int_key #(.BLOCK_SIZE(BLOCK_SIZE), .KEY_LENGTH(KEY_LENGTH)) gik_ins (.key_in(key_in), .int_key_out(int_key));
gen_even_rnd_key # (.BLOCK_SIZE(BLOCK_SIZE), .KEY_LENGTH(KEY_LENGTH)) gerk_ins (.key_in(key_in), .int_key_in(int_key), .rnd_num_in(eo_index), .even_key_out(even_key));
gen_odd_rnd_key # (.BLOCK_SIZE(BLOCK_SIZE)) gork_ins (.even_key_in(even_key), .odd_key_out(odd_key));

//Transformations
mod2p64_sub #(.BLOCK_SIZE(BLOCK_SIZE)) m2p64_ins (.m2p64sub_in_one(m2p64_block_in), .m2p64sub_in_two(m2p64_key_in), .m2p64sub_out(m2p64add_out));

mod2_add #(.BLOCK_SIZE(BLOCK_SIZE)) m2_ins0 (.m2add_in_one(sb1_out), .m2add_in_two(even_key), .m2add_out(m20_out));
inv_mix_column #(.BLOCK_SIZE(BLOCK_SIZE)) mx_ins0 (.mc_in(mc0_block_in), .mc_out(mc0_out));
inv_permute_state #(.BLOCK_SIZE(BLOCK_SIZE)) ps_ins0 (.ps_in(mc0_out), .ps_out(ps0_out));
inv_substitute_byte_foursbox #(.BLOCK_SIZE(BLOCK_SIZE)) sb_ins0 (.sb_in(ps0_out), .sb_out(sb0_out));

mod2_add #(.BLOCK_SIZE(BLOCK_SIZE)) m2_ins1 (.m2add_in_one(sb0_reg), .m2add_in_two(odd_key), .m2add_out(m21_out));
inv_mix_column #(.BLOCK_SIZE(BLOCK_SIZE)) mx_ins1 (.mc_in(m21_out), .mc_out(mc1_out));
inv_permute_state #(.BLOCK_SIZE(BLOCK_SIZE)) ps_ins1 (.ps_in(mc1_out), .ps_out(ps1_out));
inv_substitute_byte_foursbox #(.BLOCK_SIZE(BLOCK_SIZE)) sb_ins1 (.sb_in(ps1_out), .sb_out(sb1_out));

endmodule

//KALYNA ENCRYPTION and DECRYPTION - SERIAL - TWO ROUNDS IN ONE CLOCK CYCLE
module kalyna_encdec_block_serial_2rnd #(parameter BLOCK_SIZE = 512, parameter KEY_LENGTH = 512) (clk, rst, start, mode, block_in, key_in, block_out, block_rdy);

input clk, rst, start, mode;
input [BLOCK_SIZE-1:0] block_in;
input [KEY_LENGTH-1:0] key_in;
output reg [BLOCK_SIZE-1:0] block_out;
output reg block_rdy;

localparam rnd_cnt = (BLOCK_SIZE == KEY_LENGTH && BLOCK_SIZE == 128) ? 5'd10 : (BLOCK_SIZE == KEY_LENGTH && BLOCK_SIZE == 256) ? 5'd14 : (BLOCK_SIZE == KEY_LENGTH && BLOCK_SIZE == 512) ? 5'd18 : (BLOCK_SIZE != KEY_LENGTH && BLOCK_SIZE == 128) ? 5'd14 : 5'd18;

//Common Blocks
//Variables
reg [4:0] rnd_counter, rnd_index;
wire [4:0] rnd_key_index, eo_index;
wire [BLOCK_SIZE-1:0] int_key, odd_key, even_key;
//Counters
always @ (posedge clk) begin
  if (rst == 1'b1) begin
    rnd_counter <= 5'd0;
  end
  else begin
    if (start == 1'b0) begin
      rnd_counter <= 5'd0;
    end
    else begin
      if (rnd_counter <= rnd_cnt + 2'd2) begin
        rnd_counter <= rnd_counter + 2'd2;
      end
    end
  end
end
//rnd_index
always @ (*) begin
  if (rnd_counter > 5'd0) begin
    rnd_index = rnd_counter - 2'd2;
  end
  else begin
    rnd_index = 5'd0;
  end
end
//eo_index
assign eo_index = rnd_cnt - rnd_index;
//key_index
assign rnd_key_index = (mode == 1'b0) ? rnd_index : eo_index;
//Generate Intermediate Even and Odd Keys
gen_int_key #(.BLOCK_SIZE(BLOCK_SIZE), .KEY_LENGTH(KEY_LENGTH)) gik_ins (.key_in(key_in), .int_key_out(int_key));
gen_even_rnd_key # (.BLOCK_SIZE(BLOCK_SIZE), .KEY_LENGTH(KEY_LENGTH)) gerk_ins (.key_in(key_in), .int_key_in(int_key), .rnd_num_in(rnd_key_index), .even_key_out(even_key));
gen_odd_rnd_key # (.BLOCK_SIZE(BLOCK_SIZE)) gork_ins (.even_key_in(even_key), .odd_key_out(odd_key));

//Encryption
//Variables
wire [BLOCK_SIZE-1:0] enc_m2p64a_out, enc_m2a0_out, enc_m2a1_out, enc_sb0_out, enc_sb1_out, enc_ps0_out, enc_ps1_out, enc_mc0_out, enc_mc1_out;
reg [BLOCK_SIZE-1:0] enc_rnd_key, enc_fal_block_in, enc_rnd_block_in, enc_m2a0_reg;
//Registers
always @ (posedge clk) begin
  if (rst == 1'b1) begin
    enc_m2a0_reg <= {{BLOCK_SIZE}{1'b0}};
  end
  else begin
    if (start == 1'b0) begin
      enc_m2a0_reg <= {{BLOCK_SIZE}{1'b0}};
    end
    else begin
      enc_m2a0_reg <= enc_m2a0_out;
    end
  end
end
//rnd_key and fal_block_in
always @ (*) begin
  if (rnd_index == 5'd0) begin
    enc_rnd_key = even_key;
    enc_fal_block_in = block_in;
  end
  else if (rnd_index == rnd_cnt) begin
    enc_rnd_key = even_key;
    enc_fal_block_in = enc_mc1_out;
  end
  else begin
    enc_rnd_key = {BLOCK_SIZE{1'b0}};
    enc_fal_block_in = {BLOCK_SIZE{1'b0}};
  end
end
//rnd_block_in
always @ (*) begin
  if (rnd_index == 5'd0) begin
    enc_rnd_block_in = enc_m2p64a_out;
  end
  else begin
    enc_rnd_block_in = enc_m2a1_out;
  end
end
//Transformations
mod2p64_add #(.BLOCK_SIZE(BLOCK_SIZE)) m2p64a_enc_ins (.m2p64add_in_one(enc_rnd_key), .m2p64add_in_two(enc_fal_block_in), .m2p64add_out(enc_m2p64a_out));
substitute_byte_foursbox #(.BLOCK_SIZE(BLOCK_SIZE)) sb_enc_ins0 (.sb_in(enc_rnd_block_in), .sb_out(enc_sb0_out));
permute_state #(.BLOCK_SIZE(BLOCK_SIZE)) ps_enc_ins0 (.ps_in(enc_sb0_out), .ps_out(enc_ps0_out));
mix_column #(.BLOCK_SIZE(BLOCK_SIZE)) mx_enc_ins0 (.mc_in(enc_ps0_out), .mc_out(enc_mc0_out));
mod2_add #(.BLOCK_SIZE(BLOCK_SIZE)) m2a_enc_ins0 (.m2add_in_one(odd_key), .m2add_in_two(enc_mc0_out), .m2add_out(enc_m2a0_out));
substitute_byte_foursbox #(.BLOCK_SIZE(BLOCK_SIZE)) sb_enc_ins1 (.sb_in(enc_m2a0_reg), .sb_out(enc_sb1_out));
permute_state #(.BLOCK_SIZE(BLOCK_SIZE)) ps_enc_ins1 (.ps_in(enc_sb1_out), .ps_out(enc_ps1_out));
mix_column #(.BLOCK_SIZE(BLOCK_SIZE)) mx_enc_ins1 (.mc_in(enc_ps1_out), .mc_out(enc_mc1_out));
mod2_add #(.BLOCK_SIZE(BLOCK_SIZE)) m2a_enc_ins1 (.m2add_in_one(even_key), .m2add_in_two(enc_mc1_out), .m2add_out(enc_m2a1_out));

// Decryption
//Variables
reg [BLOCK_SIZE-1:0] dec_sb0_reg, dec_m2p64_block_in, dec_m2p64_key_in, dec_mc0_block_in;
wire [BLOCK_SIZE-1:0] dec_sb1_out, dec_ps1_out, dec_mc1_out, dec_m21_out, dec_sb0_out, dec_ps0_out, dec_mc0_out, dec_m20_out, dec_m2p64_out;
//Registers
always @ (posedge clk) begin
  if (rst == 1'b1 || start == 1'b0) begin
    dec_sb0_reg <= {BLOCK_SIZE{1'b0}};
  end
  else begin
    dec_sb0_reg <= dec_sb0_out;
  end
end
//m2p64_block_in and m2p64_key_in
always @ (*) begin
  if (rnd_index == 5'd0) begin
    dec_m2p64_block_in = block_in;
    dec_m2p64_key_in = even_key;
  end
  else if (rnd_index == rnd_cnt) begin
    dec_m2p64_block_in = dec_sb1_out;
    dec_m2p64_key_in = even_key;
  end
  else begin
    dec_m2p64_block_in = {BLOCK_SIZE{1'b0}};
    dec_m2p64_key_in = {BLOCK_SIZE{1'b0}};
  end
end
//mc0_block_in
always @ (*) begin
  if (rnd_index == 5'd0) begin
    dec_mc0_block_in = dec_m2p64_out;
  end
  else begin
    dec_mc0_block_in = dec_m20_out;
  end
end
//Transformations
mod2p64_sub #(.BLOCK_SIZE(BLOCK_SIZE)) m2p64_dec_ins (.m2p64sub_in_one(dec_m2p64_block_in), .m2p64sub_in_two(dec_m2p64_key_in), .m2p64sub_out(dec_m2p64_out));
mod2_add #(.BLOCK_SIZE(BLOCK_SIZE)) m2_dec_ins0 (.m2add_in_one(dec_sb1_out), .m2add_in_two(even_key), .m2add_out(dec_m20_out));
inv_mix_column #(.BLOCK_SIZE(BLOCK_SIZE)) mx_dec_ins0 (.mc_in(dec_mc0_block_in), .mc_out(dec_mc0_out));
inv_permute_state #(.BLOCK_SIZE(BLOCK_SIZE)) ps_dec_ins0 (.ps_in(dec_mc0_out), .ps_out(dec_ps0_out));
inv_substitute_byte_foursbox #(.BLOCK_SIZE(BLOCK_SIZE)) sb_dec_ins0 (.sb_in(dec_ps0_out), .sb_out(dec_sb0_out));
mod2_add #(.BLOCK_SIZE(BLOCK_SIZE)) m2_dec_ins1 (.m2add_in_one(dec_sb0_reg), .m2add_in_two(odd_key), .m2add_out(dec_m21_out));
inv_mix_column #(.BLOCK_SIZE(BLOCK_SIZE)) mx_dec_ins1 (.mc_in(dec_m21_out), .mc_out(dec_mc1_out));
inv_permute_state #(.BLOCK_SIZE(BLOCK_SIZE)) ps_dec_ins1 (.ps_in(dec_mc1_out), .ps_out(dec_ps1_out));
inv_substitute_byte_foursbox #(.BLOCK_SIZE(BLOCK_SIZE)) sb_dec_ins1 (.sb_in(dec_ps1_out), .sb_out(dec_sb1_out));

//Outputs
always @ (posedge clk) begin
  if (rst == 1'b1 || start == 1'b0) begin
    block_out <= {BLOCK_SIZE{1'b0}};
    block_rdy <= 1'b0;
  end
  else begin
    if (rnd_index == rnd_cnt) begin
      block_rdy <= 1'b1;
      if (mode == 1'b0) begin
        block_out <= enc_m2p64a_out;
      end
      else begin
        block_out <= dec_m2p64_out;
      end
    end
    else begin
      block_out <= {BLOCK_SIZE{1'b0}};
      block_rdy <= 1'b0;
    end
  end
end

endmodule

//KALYNA ENCRYPTION and DECRYPTION BLOCK - SERIAL - ONE OPERATION in ONE CLOCK CYCLE 
module kalyna_encdec_block_serial_oboc #(parameter BLOCK_SIZE = 128, parameter KEY_LENGTH = 128) (clk, rst, start, mode, block_in, key_in, block_out, block_rdy);

input clk, rst, start, mode;
input [BLOCK_SIZE-1:0] block_in;
input [KEY_LENGTH-1:0] key_in;
output reg [BLOCK_SIZE-1:0] block_out;
output reg block_rdy;

//Local parameters
localparam bs_m8 = BLOCK_SIZE - 8;
localparam bs_d16 = BLOCK_SIZE/16;
localparam the_lr = (BLOCK_SIZE/4+24);
localparam rnd_cnt = (BLOCK_SIZE == KEY_LENGTH && BLOCK_SIZE == 128) ? 5'd10 : (BLOCK_SIZE == KEY_LENGTH && BLOCK_SIZE == 256) ? 5'd14 : (BLOCK_SIZE == KEY_LENGTH && BLOCK_SIZE == 512) ? 5'd18 : (BLOCK_SIZE != KEY_LENGTH && BLOCK_SIZE == 128) ? 5'd14 : 5'd18;

//Variables
reg [4:0] rnd_num;
reg [5:0] curr_state;
reg [KEY_LENGTH-1:0] trans_in;
reg reg_block_rdy, reg_encdec_start;
reg [BLOCK_SIZE-1:0] key_alfa, key_omega, add_one_in, add_two_in, int_key, shft_tmv, trans_key_in, tmv_key, round_out;
wire [BLOCK_SIZE-1:0] int_key_in, the_tmv;
wire [7:0] the_const = (BLOCK_SIZE+KEY_LENGTH)/64 + 1;
wire [BLOCK_SIZE-1:0] m2add_out, m2p64add_out, sbpsmc_out, m2p64sub_out, inv_sbpsmc_out;

//Input to the intermediate key transformation
assign int_key_in = {the_const, {bs_m8{1'b0}}};

//Alfa and Omega Keys for the intermediate key transformation
always @ (*) begin
  if (BLOCK_SIZE == KEY_LENGTH) begin
    key_alfa = key_in;
    key_omega = key_in;
  end
  else begin
    key_alfa = key_in[KEY_LENGTH-1:KEY_LENGTH/2];
    key_omega = key_in[KEY_LENGTH/2-1:0];
  end
end

//Generation of the TMV signal and its shifted version
assign the_tmv= {bs_d16{16'h0100}};
always @ (*) begin
  case (rnd_num)
    5'd0    : shft_tmv = the_tmv;
    5'd2    : shft_tmv = {the_tmv[BLOCK_SIZE-2:0],  1'd0};
    5'd4    : shft_tmv = {the_tmv[BLOCK_SIZE-3:0],  2'd0};
    5'd6    : shft_tmv = {the_tmv[BLOCK_SIZE-4:0],  3'd0};
    5'd8    : shft_tmv = {the_tmv[BLOCK_SIZE-5:0],  4'd0};
    5'd10   : shft_tmv = {the_tmv[BLOCK_SIZE-6:0],  5'd0};
    5'd12   : shft_tmv = {the_tmv[BLOCK_SIZE-7:0],  6'd0};
    5'd14   : shft_tmv = {the_tmv[BLOCK_SIZE-8:0],  7'd0};
    5'd16   : shft_tmv = {the_tmv[BLOCK_SIZE-9:0],  7'd0, 1'b1};
    5'd18   : shft_tmv = {the_tmv[BLOCK_SIZE-10:0], 7'd0, 1'b1, 1'b0}; //Last two lines are due to the conflict between rotate and shift
    default : shft_tmv = the_tmv;
  endcase
end

//Generation of the input to the transformations
always @ (*) begin
  if (BLOCK_SIZE == KEY_LENGTH) begin
    if (BLOCK_SIZE == 128) begin
      case (rnd_num) 
        5'd0    : trans_in = key_in;
        5'd2    : trans_in = {key_in[63:0], key_in[127:64]};
        5'd4    : trans_in = key_in;
        5'd6    : trans_in = {key_in[63:0], key_in[127:64]};
        5'd8    : trans_in = key_in;
        5'd10   : trans_in = {key_in[63:0], key_in[127:64]};
        default : trans_in = key_in;
      endcase
    end
    else if (BLOCK_SIZE == 256) begin
      case (rnd_num) 
        5'd0    : trans_in = key_in;
        5'd2    : trans_in = {key_in[191:0], key_in[255:192]};
        5'd4    : trans_in = {key_in[127:0], key_in[255:128]};
        5'd6    : trans_in = {key_in[63:0],  key_in[255:64]};
        5'd8    : trans_in = key_in;
        5'd10   : trans_in = {key_in[191:0], key_in[255:192]};
        5'd12   : trans_in = {key_in[127:0], key_in[255:128]};
        5'd14   : trans_in = {key_in[63:0],  key_in[255:64]};
        default : trans_in = key_in;
      endcase
    end
    else begin
      case (rnd_num) 
        5'd0    : trans_in = key_in;
        5'd2    : trans_in = {key_in[447:0], key_in[511:448]};
        5'd4    : trans_in = {key_in[383:0], key_in[511:384]};
        5'd6    : trans_in = {key_in[319:0], key_in[511:320]};
        5'd8    : trans_in = {key_in[255:0], key_in[511:256]};
        5'd10   : trans_in = {key_in[191:0], key_in[511:192]};
        5'd12   : trans_in = {key_in[127:0], key_in[511:128]};
        5'd14   : trans_in = {key_in[63:0],  key_in[511:64]};
        5'd16   : trans_in = key_in;
        5'd18   : trans_in = {key_in[447:0], key_in[511:448]};
        default : trans_in = key_in;
      endcase
    end
  end
  else begin
    if (BLOCK_SIZE == 128) begin
      case (rnd_num) 
        5'd0    : trans_in = key_in;
        5'd2    : trans_in = key_in;
        5'd4    : trans_in = {key_in[191:0], key_in[255:192]};
        5'd6    : trans_in = {key_in[191:0], key_in[255:192]};
        5'd8    : trans_in = {key_in[127:0], key_in[255:128]};
        5'd10   : trans_in = {key_in[127:0], key_in[255:128]};
        5'd12   : trans_in = {key_in[63:0],  key_in[255:64]};
        5'd14   : trans_in = {key_in[63:0],  key_in[255:64]};
        default : trans_in = key_in;
      endcase
    end
    else begin
      case (rnd_num) 
        5'd0    : trans_in = key_in;
        5'd2    : trans_in = key_in;
        5'd4    : trans_in = {key_in[447:0], key_in[511:448]};
        5'd6    : trans_in = {key_in[447:0], key_in[511:448]};
        5'd8    : trans_in = {key_in[383:0], key_in[511:384]};
        5'd10   : trans_in = {key_in[383:0], key_in[511:384]};
        5'd12   : trans_in = {key_in[319:0], key_in[511:320]};
        5'd14   : trans_in = {key_in[319:0], key_in[511:320]};
        5'd16   : trans_in = {key_in[255:0], key_in[511:256]};
        5'd18   : trans_in = {key_in[255:0], key_in[511:256]};
        default : trans_in = key_in;
      endcase
    end
  end
end
always @ (*) begin
  if (BLOCK_SIZE == KEY_LENGTH) begin
    trans_key_in = trans_in;
  end
  else begin
    case (rnd_num) 
      5'd0    : trans_key_in = trans_in[KEY_LENGTH-1:KEY_LENGTH-BLOCK_SIZE];
      5'd2    : trans_key_in = trans_in[BLOCK_SIZE-1:0];
      5'd4    : trans_key_in = trans_in[KEY_LENGTH-1:KEY_LENGTH-BLOCK_SIZE]; 
      5'd6    : trans_key_in = trans_in[BLOCK_SIZE-1:0]; 
      5'd8    : trans_key_in = trans_in[KEY_LENGTH-1:KEY_LENGTH-BLOCK_SIZE]; 
      5'd10   : trans_key_in = trans_in[BLOCK_SIZE-1:0]; 
      5'd12   : trans_key_in = trans_in[KEY_LENGTH-1:KEY_LENGTH-BLOCK_SIZE]; 
      5'd14   : trans_key_in = trans_in[BLOCK_SIZE-1:0]; 
      5'd16   : trans_key_in = trans_in[KEY_LENGTH-1:KEY_LENGTH-BLOCK_SIZE]; 
      5'd18   : trans_key_in = trans_in[BLOCK_SIZE-1:0]; 
      default : trans_key_in = trans_in[BLOCK_SIZE-1:0]; 
    endcase
  end
end

//The reg_encdec_start signal indicates that the encryption process is started
always @ (posedge clk) begin
  if (rst == 1'b1) begin
    reg_encdec_start <= 1'b0;
  end
  else begin
    if (block_rdy == 1'b1) begin
      reg_encdec_start <= 1'b0;
    end
    else begin
      if (start == 1'b1) begin
        reg_encdec_start <= 1'b1;
      end
    end
  end
end

//Block inputs in each state  
always @ (posedge clk) begin
  if (rst == 1'b1) begin
    rnd_num <= 5'd0;
    curr_state <= 6'd0;
    reg_block_rdy <= 1'b0;
    tmv_key <= {BLOCK_SIZE{1'b0}};
    int_key <= {BLOCK_SIZE{1'b0}};
    round_out <= {BLOCK_SIZE{1'b0}};
    add_one_in <= {BLOCK_SIZE{1'b0}};
    add_two_in <= {BLOCK_SIZE{1'b0}};
  end
  else begin
    if (reg_encdec_start == 1'b0) begin
      rnd_num <= 5'd0;
      curr_state <= 6'd0;
      reg_block_rdy <= 1'b0;
      tmv_key <= {BLOCK_SIZE{1'b0}};
      int_key <= {BLOCK_SIZE{1'b0}};
      round_out <= {BLOCK_SIZE{1'b0}};
      add_one_in <= {BLOCK_SIZE{1'b0}};
      add_two_in <= {BLOCK_SIZE{1'b0}};
    end
    else begin
      //Encryption
      if (mode == 1'b0) begin
        case (curr_state)
          //Intermediate key generattion starts here
          6'd0 : begin
            //ADD - INTKEY
            add_one_in <= int_key_in;
            add_two_in <= key_alfa;

            curr_state <= 6'd1;
          end
          6'd1 : begin
            //SPLT - INTKEY
            add_one_in <= m2p64add_out;

            curr_state <= 6'd2;
          end
          6'd2 : begin
            //XOR - INTKEY
            add_one_in <= key_omega;
            add_two_in <= sbpsmc_out;

            curr_state <= 6'd3;
          end
          6'd3 : begin
            //SPLT - INTKEY
            add_one_in <= m2add_out;
            
            curr_state <= 6'd4;
          end
          6'd4 : begin
            //ADD - INTKEY
            add_one_in <= key_alfa;
            add_two_in <= sbpsmc_out;

            curr_state <= 6'd5;
          end
          6'd5 : begin
            //RND - KEY0
            rnd_num <= 5'd0;

            //SPLT - INTKEY
            add_one_in <= m2p64add_out;
            
            curr_state <= 6'd6;
          end
          //Intermediate key generation ends and round 0 key generation starts here
          6'd6 : begin
            int_key <= sbpsmc_out;

            //ADD - KEY0
            add_one_in <= sbpsmc_out;
            add_two_in <= shft_tmv;

            curr_state <= 6'd7;
          end
          6'd7 : begin
            tmv_key <= m2p64add_out;

            //ADD - KEY0
            add_one_in <= m2p64add_out;
            add_two_in <= trans_key_in;

            curr_state <= 6'd8;
          end
          6'd8 : begin
            //SPLT - KEY0
            add_one_in <= m2p64add_out;

            curr_state <= 6'd9;
          end
          6'd9 : begin
            //XOR - KEY0
            add_one_in <= tmv_key;
            add_two_in <= sbpsmc_out;

            curr_state <= 6'd10;
          end
          6'd10 : begin
            //SPLT - KEY0
            add_one_in <= m2add_out;

            curr_state <= 6'd11;
          end
          6'd11 : begin
            //ADD - KEY0
            add_one_in <= tmv_key;
            add_two_in <= sbpsmc_out;

            curr_state <= 6'd12;
          end
          //Round 0 key generation ends here and Round 0-1 operations start here
          6'd12 : begin
            tmv_key <= m2p64add_out;
            //ADD - RND0
            add_one_in <= m2p64add_out;
            add_two_in <= block_in;

            curr_state <= 6'd13;
          end
          6'd13 : begin
            //SPLT - RND1
            add_one_in <= m2p64add_out;

            curr_state <= 6'd14;
          end
          6'd14 : begin
            //RND - KEY2
            rnd_num <= rnd_num + 5'd2;
            //XOR - RND1
            add_one_in <= sbpsmc_out;
            add_two_in <= {tmv_key[BLOCK_SIZE-1-the_lr:0], tmv_key[BLOCK_SIZE-1:BLOCK_SIZE-the_lr]};

            curr_state <= 6'd15;
          end
          //Round 2 key generation starts here
          6'd15 : begin
            round_out <= m2add_out;
            //ADD - KEY2
            add_one_in <= int_key;
            add_two_in <= shft_tmv;

            curr_state <= 6'd16;
          end
          6'd16 : begin
            tmv_key <= m2p64add_out;

            //ADD - KEY2
            add_one_in <= m2p64add_out;
            add_two_in <= trans_key_in;

            curr_state <= 6'd17;
          end
          6'd17 : begin
            //SPLT - KEY2
            add_one_in <= m2p64add_out;

            curr_state <= 6'd18;
          end
          6'd18 : begin
            //XOR - KEY2
            add_one_in <= tmv_key;
            add_two_in <= sbpsmc_out;

            curr_state <= 6'd19;
          end
          6'd19 : begin
            //SPLT - KEY2
            add_one_in <= m2add_out;

            curr_state <= 6'd20;
          end
          6'd20 : begin
            //ADD - KEY2
            add_one_in <= tmv_key;
            add_two_in <= sbpsmc_out;

            curr_state <= 6'd21;
          end
          //Round 2 key generation ends here and Round 2-3 operations start here
          6'd21 : begin
            tmv_key <= m2p64add_out;

            //SPLT - RND2
            add_one_in <= round_out;

            curr_state <= 6'd22;
          end
          6'd22 : begin
            //XOR - RND2
            add_one_in <= sbpsmc_out;
            add_two_in <= tmv_key;

            curr_state <= 6'd23;
          end
          6'd23 : begin
            //SPLT -RND3
            add_one_in <= m2add_out;

            curr_state <= 6'd24;
          end
          6'd24 : begin
            //RND - KEY4
            rnd_num <= rnd_num + 5'd2;

            //XOR - RND3
            add_one_in <= sbpsmc_out;
            add_two_in <= {tmv_key[BLOCK_SIZE-1-the_lr:0], tmv_key[BLOCK_SIZE-1:BLOCK_SIZE-the_lr]};

            curr_state <= 6'd25;
          end
          //Round 2-3 operations end here and Round 4 key generation starts here
          6'd25 : begin
            round_out <= m2add_out;
            //ADD - KEY4
            add_one_in <= int_key;
            add_two_in <= shft_tmv;

            curr_state <= 6'd26;
          end
          6'd26 : begin
            tmv_key <= m2p64add_out;

            //ADD - KEY4
            add_one_in <= m2p64add_out;
            add_two_in <= trans_key_in;

            curr_state <= 6'd27;
          end
          6'd27 : begin
            //SPLT - KEY4
            add_one_in <= m2p64add_out;

            curr_state <= 6'd28;
          end
          6'd28 : begin
            //XOR - KEY4
            add_one_in <= tmv_key;
            add_two_in <= sbpsmc_out;

            curr_state <= 6'd29;
          end
          6'd29 : begin
            //SPLT - KEY4
            add_one_in <= m2add_out;

            curr_state <= 6'd30;
          end
          6'd30 : begin
            //ADD - KEY4
            add_one_in <= tmv_key;
            add_two_in <= sbpsmc_out;

            curr_state <= 6'd31;
          end
          //Round 4 key generation ends here and Round 4-5 operations start here
          6'd31 : begin
            tmv_key <= m2p64add_out;

            //SPLT - RND4
            add_one_in <= round_out;

            curr_state <= 6'd32;
          end
          6'd32 : begin
            //XOR - RND4
            add_one_in <= sbpsmc_out;
            add_two_in <= tmv_key;

            curr_state <= 6'd33;
          end
          6'd33 : begin
            //SPLT -RND5
            add_one_in <= m2add_out;

            curr_state <= 6'd34;
          end
          6'd34 : begin
